const PIN_STORAGE_KEY =
  'ob-sidebar-pinned-v1'

const FLOATING_OPEN_STORAGE_KEY =
  'ob-sidebar-floating-open-v1'

function loadPinned() {
  try {
    return (
      localStorage.getItem(
        PIN_STORAGE_KEY,
      ) !== 'false'
    )
  } catch {
    return true
  }
}

function loadFloatingOpen() {
  try {
    return (
      localStorage.getItem(
        FLOATING_OPEN_STORAGE_KEY,
      ) === 'true'
    )
  } catch {
    return false
  }
}

function getActiveSection(
  pathname: string,
): string | null {
  for (const section of sections) {
    if (section.id === 'administration' && pathname === '/administration') return section.id
    const active =
      section.items.some((item) => {
        if (item.children?.some(child => child.to === pathname)) return true
        if (!item.to) {
          return false
        }

        if (
          item.to === '/administration' ||
          item.to === '/communication' ||
          item.to === '/comptabilite' ||
          item.to === '/etablissement'
        ) {
          return pathname === item.to
        }

        return (
          pathname === item.to ||
          pathname.startsWith(
            `${item.to}/`,
          )
        )
      })

    if (active) {
      return section.id
    }
  }

  return null
}

export default function Sidebar() {
  const location = useLocation()
  const { canVisit } = useAccess()
  const visibleSections = sections.map((section) => ({
    ...section,
    items: section.items.map((item) => ({
      ...item,
      children: item.children?.filter(child => Boolean(child.to && canVisit(child.to))),
    })).filter(item => Boolean((item.to && canVisit(item.to)) || item.children?.length || !item.to)),
  })).filter((section) => section.items.length > 0)
  const { currentUser } = useUsers()
  const { settings } =
    useGeneralSettings()

  const [
    pinned,
    setPinned,
  ] = useState(loadPinned)

  const [
    floatingOpen,
    setFloatingOpen,
  ] = useState(loadFloatingOpen)

  const [bddOpen, setBddOpen] = useState(() =>
    window.location.pathname.startsWith('/bdd'),
  )

  const [
    mobileOpen,
    setMobileOpen,
  ] = useState(false)

  const [
    expandedSections,
    setExpandedSections,
  ] = useState<Record<string, boolean>>({
    gestion: true,
    bdd: window.location.pathname.startsWith('/bdd'),
  })

  const floatingCloseTimer =
    useRef<number | null>(null)

  const navRef =
    useRef<HTMLElement | null>(null)

  const previousPathRef = useRef(location.pathname)

  function cancelFloatingClose() {
    if (floatingCloseTimer.current !== null) {
      window.clearTimeout(
        floatingCloseTimer.current,
      )

      floatingCloseTimer.current = null
    }
  }

  function openFloatingSidebar() {
    if (pinned) {
      return
    }

    cancelFloatingClose()
    setFloatingOpen(true)
  }

  function scheduleFloatingClose() {
    if (pinned) {
      return
    }

    cancelFloatingClose()

    floatingCloseTimer.current =
      window.setTimeout(() => {
        setFloatingOpen(false)
        floatingCloseTimer.current = null
      }, 240)
  }

  const applicationName =
    settings.applicationName.trim() ||
    'Opération Brioches'

  const organizationName =
    settings.organizationName.trim() ||
    'AEIM'

  const activeSection =
    location.pathname.startsWith('/rubriques/')
      ? location.pathname.split('/')[2]
      : getActiveSection(location.pathname)

  const desktopOpen =
    pinned || floatingOpen

  useEffect(() => {
    try {
      localStorage.setItem(
        PIN_STORAGE_KEY,
        String(pinned),
      )

      localStorage.setItem(
        FLOATING_OPEN_STORAGE_KEY,
        String(floatingOpen),
      )
    } catch {
      // Le menu reste fonctionnel.
    }

    document.documentElement.style.setProperty(
      '--ob-sidebar-reserved',
      pinned
        ? 'var(--ob-sidebar-width)'
        : '0px',
    )

    document.documentElement.dataset.sidebarPinned =
      pinned ? 'true' : 'false'

    return () => {
      document.documentElement.style.removeProperty(
        '--ob-sidebar-reserved',
      )

      delete document.documentElement.dataset.sidebarPinned
    }
  }, [
    pinned,
    floatingOpen,
  ])

  useEffect(() => {
    if (location.pathname.startsWith('/bdd')) setBddOpen(true)
    if (activeSection) {
      setExpandedSections(
        (current) => ({
          ...current,
          [activeSection]: true,
        }),
      )
    }

    setMobileOpen(false)

    /*
      En mode flottant, la navigation se referme
      automatiquement après avoir choisi une page.
    */
    // Ne ferme le volet flottant qu'en cas de navigation,
    // pas quand l'utilisateur désépingle avec la punaise.
    if (previousPathRef.current !== location.pathname && !pinned) {
      setFloatingOpen(false)
    }
    previousPathRef.current = location.pathname
  }, [
    activeSection,
    location.pathname,
    pinned,
  ])

  useEffect(() => {
    if (
      !mobileOpen &&
      !floatingOpen
    ) {
      return
    }

    function handleEscape(
      event: KeyboardEvent,
    ) {
      if (event.key === 'Escape') {
        setMobileOpen(false)

        if (!pinned) {
          setFloatingOpen(false)
        }
      }
    }

    window.addEventListener(
      'keydown',
      handleEscape,
    )

    return () =>
      window.removeEventListener(
        'keydown',
        handleEscape,
      )
  }, [
    mobileOpen,
    floatingOpen,
    pinned,
  ])

  useEffect(() => {
    return () => {
      cancelFloatingClose()
    }
  }, [])

  useEffect(() => {
    const nav = navRef.current

    if (!nav) {
      return
    }

    const frame =
      window.requestAnimationFrame(() => {
        if (
          location.pathname === '/'
        ) {
          nav.scrollTo({
            top: 0,
            behavior: 'smooth',
          })

          return
        }

        const active =
          nav.querySelector<HTMLElement>(
            '.ob-sidebar-link.is-active, .ob-sidebar-home.is-active',
          )

        active?.scrollIntoView({
          block: 'nearest',
          behavior: 'smooth',
        })
      })

    return () =>
      window.cancelAnimationFrame(
        frame,
      )
  }, [
    location.pathname,
    floatingOpen,
    pinned,
  ])

  function pinSidebarFromBurger() {
    cancelFloatingClose()
    setFloatingOpen(false)
    setPinned(true)
  }

  function closeSidebar() {
    cancelFloatingClose()
    setMobileOpen(false)
    setFloatingOpen(false)
    setPinned(false)
  }

  function toggleSection(
    id: string,
  ) {
    setExpandedSections(
      (current) => ({
        ...current,
        [id]: !current[id],
      }),
    )
  }

  const sidebarClasses = [
    'ob-sidebar',
    !pinned
      ? 'ob-sidebar--floating'
      : '',
    !desktopOpen
      ? 'is-closed'
      : '',
    mobileOpen
      ? 'ob-sidebar--mobile-open'
      : '',
  ]
    .filter(Boolean)
    .join(' ')

  return (
    <>
      <div
        className={[
          'ob-sidebar-shell',
          pinned
            ? 'ob-sidebar-shell--pinned'
            : 'ob-sidebar-shell--floating',
        ].join(' ')}
      >
        <aside
          id="ob-main-sidebar"
          className={sidebarClasses}
          aria-label="Menu principal"
          onMouseEnter={
            openFloatingSidebar
          }
          onMouseLeave={
            scheduleFloatingClose
          }
        >
          <div className="ob-sidebar-header">
            <NavLink
              to="/"
              className="ob-sidebar-brand"
              onClick={() => {
                setMobileOpen(false)

                if (!pinned) {
                  setFloatingOpen(false)
                }
              }}
            >
              <div
                className="ob-sidebar-logo"
                aria-hidden="true"
              >
                <img
                  src="/brioche-favicon.svg"
                  alt=""
                />
              </div>

              <div className="ob-sidebar-brand-info">
                <strong>
                  {applicationName}
                </strong>

                <span>
                  {organizationName}
                </span>
              </div>
            </NavLink>

            <div className="ob-sidebar-header-actions">
              <button
                type="button"
                className={`ob-sidebar-pin ${pinned ? 'is-pinned' : ''}`}
                onClick={() => {
                  cancelFloatingClose()
                  // Désépingler ne ferme jamais immédiatement le menu.
                  // Il reste visible tant que la souris est dessus.
                  if (pinned) {
                    setFloatingOpen(true)
                    setPinned(false)
                  } else {
                    setPinned(true)
                    setFloatingOpen(false)
                  }
                }}
                aria-label={pinned ? 'Désépingler le menu' : 'Épingler le menu'}
                aria-pressed={pinned}
                title={pinned ? 'Désépingler le menu' : 'Épingler le menu'}
              >
                <Pin size={18} />
              </button>
              <button
                type="button"
                className="ob-sidebar-close"
                onClick={closeSidebar}
                title="Fermer la navigation"
                aria-label="Fermer la navigation"
              >
                <X size={18} />
              </button>
            </div>
          </div>

          <nav
            ref={navRef}
            className="ob-sidebar-nav"
            aria-label="Rubriques Opération Brioches"
          >
            {canVisit('/') && (
            <NavLink
              to="/"
              end
              className={({ isActive }) =>
                `ob-sidebar-home ${
                  isActive
                    ? 'is-active'
                    : ''
                }`
              }
              onClick={() => {
                setMobileOpen(false)

                if (!pinned) {
                  setFloatingOpen(false)
                }
              }}
            >
              <House size={20} />
              <span>Accueil</span>
            </NavLink>
            )}

            <div className="ob-sidebar-separator" />

            {visibleSections.map(
              (section) => {
                const Icon =
                  section.icon

                const expanded =
                  Boolean(
                    expandedSections[
                      section.id
                    ],
                  )

                const current =
                  activeSection ===
                  section.id

                return (
                  <div
                    key={section.id}
                    className="ob-sidebar-section"
                  >
                    {section.id === 'geographie' ? (
                      <NavLink
                        to="/geographie/carte"
                        className={({ isActive }) => `ob-sidebar-group ${isActive || current ? 'is-current' : ''}`}
                        onClick={() => {
                          setMobileOpen(false)
                          if (!pinned) setFloatingOpen(false)
                        }}
                      >
                        <Icon size={20} />
                        <span className="ob-sidebar-group-label">{section.label}</span>
                      </NavLink>
                    ) : section.id === 'administration' || section.id !== 'geographie' ? (
                      <div className={`ob-sidebar-group ${current ? 'is-current' : ''}`}>
                        <Icon size={20} />
                        <NavLink
                          to={section.id === 'administration' ? '/administration' : `/rubriques/${section.id}`}
                          className="ob-sidebar-group-label"
                          style={{ color: 'inherit', textDecoration: 'none', alignSelf: 'stretch', display: 'flex', alignItems: 'center' }}
                          onClick={() => {
                            setMobileOpen(false)
                            if (!pinned) setFloatingOpen(false)
                          }}
                        >
                          {section.label}
                        </NavLink>
                        <button
                          type="button"
                          onClick={() => toggleSection(section.id)}
                          aria-label={expanded ? `Replier ${section.label}` : `Déplier ${section.label}`}
                          aria-expanded={expanded}
                          aria-controls={`ob-sidebar-section-${section.id}`}
                          style={{ border: 0, background: 'transparent', color: 'inherit', cursor: 'pointer', padding: '10px 3px', display: 'flex', alignItems: 'center' }}
                        >
                          <ChevronDown size={16} className={`ob-sidebar-chevron ${expanded ? 'is-expanded' : ''}`} />
                        </button>
                      </div>
                    ) : (
                    <button
                      type="button"
                      className={`ob-sidebar-group ${
                        current
                          ? 'is-current'
                          : ''
                      }`}
                      onClick={(event) => {
                        event.preventDefault()
                        event.stopPropagation()
                        toggleSection(
                          section.id,
                        )
                      }}
                      aria-expanded={
                        expanded
                      }
                      aria-controls={`ob-sidebar-section-${section.id}`}
                    >
                      <Icon size={20} />

                      <span className="ob-sidebar-group-label">
                        {section.label}
                      </span>

                      <ChevronDown
                        size={16}
                        className={`ob-sidebar-chevron ${
                          expanded
                            ? 'is-expanded'
                            : ''
                        }`}
                      />
                    </button>
                    )}

                    {expanded && section.id !== 'geographie' && (
                      <div
                        id={`ob-sidebar-section-${section.id}`}
                        className="ob-sidebar-submenu"
                      >
                        {section.items.filter(item => item.to !== '/etablissements/recap-global' || ['administrateur','comptabilite','communication'].includes(currentUser?.role ?? '')).map(
                          (item) =>
                            item.children?.length ? (
                              <div key={item.label} className="ob-sidebar-bdd-group">
                                <button type="button" className="ob-sidebar-link ob-sidebar-bdd-toggle"
                                  onClick={() => setBddOpen(open => !open)}
                                  aria-expanded={bddOpen}
                                  aria-controls="ob-sidebar-bdd-items">
                                  <Database size={16} />
                                  <span className="ob-sidebar-link-label">BDD</span>
                                  <ChevronDown size={15} className={`ob-sidebar-chevron ${bddOpen ? 'is-expanded' : ''}`} />
                                </button>
                                {bddOpen && (
                                  <div id="ob-sidebar-bdd-items" className="ob-sidebar-bdd-children">
                                    {item.children.map(child => (
                                      <NavLink key={child.to} to={child.to!} end
                                        className={({ isActive }) => `ob-sidebar-link ob-sidebar-bdd-child ${isActive ? 'is-active' : ''}`}
                                        onClick={() => { setMobileOpen(false); if (!pinned) setFloatingOpen(false) }}>
                                        <span className="ob-sidebar-dot" />
                                        <span className="ob-sidebar-link-label">{child.label}</span>
                                      </NavLink>
                                    ))}
                                  </div>
                                )}
                              </div>
                            ) : item.to ? (
                              <NavLink
                                key={
                                  item.label
                                }
                                to={item.to}
                                end
                                className={({
                                  isActive,
                                }) =>
                                  `ob-sidebar-link ${
                                    isActive
                                      ? 'is-active'
                                      : ''
                                  }`
                                }
                                onClick={() => {
                                  setMobileOpen(
                                    false,
                                  )

                                  if (!pinned) {
                                    setFloatingOpen(
                                      false,
                                    )
                                  }
                                }}
                              >
                                <span className="ob-sidebar-dot" />

                                <span className="ob-sidebar-link-label">
                                  {item.label}
                                </span>

                                {item.badge && (
                                  <span className="ob-sidebar-badge ob-sidebar-badge--special">
                                    {
                                      item.badge
                                    }
                                  </span>
                                )}
                              </NavLink>
                            ) : (
                              <div
                                key={
                                  item.label
                                }
                                className="ob-sidebar-link ob-sidebar-link--disabled"
                              >
                                <span className="ob-sidebar-dot" />

                                <span className="ob-sidebar-link-label">
                                  {item.label}
                                </span>

                                <span className="ob-sidebar-badge">
                                  À venir
                                </span>
                              </div>
                            ),
                        )}
                      </div>
                    )}
                  </div>
                )
              },
            )}
          </nav>

          <div
            className="ob-sidebar-community"
            aria-hidden="true"
          >
            <img
              src="/ob/ob-sidebar-community.png"
              alt=""
            />
          </div>
        </aside>
      </div>

      {!pinned && !floatingOpen && (
        <div
          className="ob-sidebar-edge-trigger"
          onMouseEnter={
            openFloatingSidebar
          }
          aria-hidden="true"
        />
      )}

      {!pinned && !floatingOpen && (
        <button
          type="button"
          className={`ob-sidebar-burger ob-sidebar-burger--desktop ${
            floatingOpen
              ? 'with-panel'
              : ''
          }`}
          onClick={
            pinSidebarFromBurger
          }
          aria-label="Ouvrir et épingler le menu latéral"
          aria-expanded={false}
          aria-controls="ob-main-sidebar"
          title="Ouvrir et épingler le menu"
        >
          <Menu size={21} />
        </button>
      )}

      <button
        type="button"
        className="ob-sidebar-burger ob-sidebar-burger--mobile"
        onClick={() =>
          setMobileOpen(
            (current) => !current,
          )
        }
