          mobileOpen
            ? 'Fermer le menu'
            : 'Ouvrir le menu'
        }
        aria-expanded={mobileOpen}
        aria-controls="ob-main-sidebar"
      >
        {mobileOpen ? (
          <X size={21} />
        ) : (
          <Menu size={21} />
        )}
      </button>

      {mobileOpen && (
        <button
          type="button"
          className="ob-sidebar-overlay"
          aria-label="Fermer le menu"
          onClick={() => {
            setMobileOpen(false)

            if (!pinned) {
              setFloatingOpen(false)
            }
          }}
        />
      )}
    </>
  )
}

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
  type Dispatch,
  type ReactNode,
  type SetStateAction,
} from 'react'
import type { Artisan, CommandeArtisan, Fournisseur } from '../types/artisans'

const LEGACY_ARTISANS_KEY = 'ob-artisans-v1'
const FOURNISSEURS_KEY = 'ob-fournisseurs-v1'
const COMMANDES_KEY = 'ob-commandes-artisans-v1'
const RESET_KEY = 'ob-achats-reset-complet-20261013-v1'
const BACKUP_KEY = 'ob-achats-sauvegarde-avant-reset-20261013-v1'

/** Remise à zéro demandée : exécutée une fois dans CE navigateur.
 *  Copie de secours non utilisée par les modules, conservée pour restauration manuelle.
 */
function effectuerResetInitial(): void {
  try {
    if (localStorage.getItem(RESET_KEY) === 'ok') return
    const sauvegarde = {
      date: new Date().toISOString(),
      fournisseurs: localStorage.getItem(FOURNISSEURS_KEY),
      artisansHistoriques: localStorage.getItem(LEGACY_ARTISANS_KEY),
      commandesAchats: localStorage.getItem(COMMANDES_KEY),
    }
    // Ne pas remplacer une sauvegarde existante en cas de rechargement.
    if (localStorage.getItem(BACKUP_KEY) === null) {
      localStorage.setItem(BACKUP_KEY, JSON.stringify(sauvegarde))
    }
    localStorage.setItem(FOURNISSEURS_KEY, '[]')
    localStorage.setItem(LEGACY_ARTISANS_KEY, '[]')
    localStorage.setItem(COMMANDES_KEY, '[]')
    localStorage.setItem(RESET_KEY, 'ok')
  } catch (error) {
    console.error('La remise à zéro des achats a échoué :', error)
  }
}


function lireTableau<T>(cle: string, initial: T[]): T[] {
  try {
    const brut = localStorage.getItem(cle)
    if (brut === null) return initial
    const parsed: unknown = JSON.parse(brut)
    return Array.isArray(parsed) ? parsed as T[] : initial
  } catch {
    return initial
  }
}

/** Migration non destructive : priorité à la nouvelle base si elle existe. */
function chargerFournisseurs(): Fournisseur[] {
  try {
    const brut = localStorage.getItem(FOURNISSEURS_KEY)
    if (brut !== null) {
      const parsed: unknown = JSON.parse(brut)
      if (Array.isArray(parsed)) {
        return parsed.map(item => ({
          ...(item as Fournisseur),
          type: (item as Fournisseur).type === 'GMS'
            ? 'GMS' as const
            : (item as Fournisseur).type === 'INDUSTRIEL'
              ? 'INDUSTRIEL' as const
              : 'ARTISAN' as const,
        }))
      }
    }
  } catch {
    // Une base illisible n'efface pas les données historiques.
  }

  return lireTableau<Artisan>(LEGACY_ARTISANS_KEY, [])
    .map(artisan => ({ ...artisan, type: 'ARTISAN' as const }))
}

type ArtisansContextValue = {
  fournisseurs: Fournisseur[]
  setFournisseurs: Dispatch<SetStateAction<Fournisseur[]>>
  /** Interface historique conservée pour CommandesArtisans et PlanningArtisans. */
  artisans: Artisan[]
  setArtisans: Dispatch<SetStateAction<Artisan[]>>
  commandesArtisans: CommandeArtisan[]
  setCommandesArtisans: Dispatch<SetStateAction<CommandeArtisan[]>>
}

const Context = createContext<ArtisansContextValue | null>(null)

export function ArtisansProvider({ children }: { children: ReactNode }) {
  const [fournisseurs, setFournisseurs] = useState<Fournisseur[]>(chargerFournisseurs)
  const [commandesArtisans, setCommandesArtisans] = useState<CommandeArtisan[]>(() =>
    lireTableau(COMMANDES_KEY, []),
  )

  const artisans = useMemo(
    () => fournisseurs.filter(fournisseur => fournisseur.type === 'ARTISAN'),
    [fournisseurs],
  )

  // Les composants de la V1 qui appellent setArtisans continuent à fonctionner.
  // La mise à jour ne touche jamais aux fiches GMS ou industrielles.
  const setArtisans = useCallback<Dispatch<SetStateAction<Artisan[]>>>(miseAJour => {
    setFournisseurs(anciens => {
      const anciensArtisans = anciens.filter(f => f.type === 'ARTISAN')
      const suivants = typeof miseAJour === 'function'
        ? miseAJour(anciensArtisans)
        : miseAJour
      const autresFournisseurs = anciens.filter(f => f.type !== 'ARTISAN')
      return [...autresFournisseurs, ...suivants.map(a => ({ ...a, type: 'ARTISAN' as const }))]
    })
  }, [])

  useEffect(() => {
    try {
      localStorage.setItem(FOURNISSEURS_KEY, JSON.stringify(fournisseurs))
      // Maintenir le format historique afin de ne pas casser un éventuel autre module.
      localStorage.setItem(LEGACY_ARTISANS_KEY, JSON.stringify(artisans))
    } catch (error) {
      console.error('Sauvegarde des fournisseurs impossible :', error)
    }
  }, [fournisseurs, artisans])

  useEffect(() => {
    try {
      localStorage.setItem(COMMANDES_KEY, JSON.stringify(commandesArtisans))
    } catch (error) {
      console.error('Sauvegarde des commandes artisans impossible :', error)
    }
  }, [commandesArtisans])

  return (
    <Context.Provider value={{
      fournisseurs, setFournisseurs, artisans, setArtisans,
      commandesArtisans, setCommandesArtisans,
    }}>
      {children}
    </Context.Provider>
  )
}

export function useArtisans() {
  const context = useContext(Context)
  if (!context) {
    throw new Error('Ce module doit être enveloppé par ArtisansProvider dans App.tsx.')
  }
  return context
}

import { createContext, useCallback, useContext, useMemo, useState, type ReactNode } from 'react'
import { useUsers, DEMO_CURRENT_USER_ID } from './UsersContext'

const KEY = 'ob2026-local-credentials-v1'
const SESSION = 'ob2026-auth-session-v1'
type Credential = { salt: string; hash: string; mustChange?: boolean }
type Credentials = Record<string, Credential>
type AuthValue = {
  authenticated: boolean; userId: string | null; needsSetup: boolean
  signIn: (identifier: string, password: string) => Promise<string | null>
  initializeAdmin: (password: string) => Promise<void>
  setPassword: (userId: string, password: string) => Promise<void>
  hasPassword: (userId: string) => boolean
  setTemporaryPassword: (userId: string, password: string) => Promise<void>
  changePassword: (identifier: string, currentPassword: string, newPassword: string) => Promise<void>
  signOut: () => void
}
const Context = createContext<AuthValue | null>(null)
function readCredentials(): Credentials {
  try { const value = JSON.parse(localStorage.getItem(KEY) || '{}'); return value && typeof value === 'object' && !Array.isArray(value) ? value : {} }
  catch { return {} }
}
function hex(buffer: ArrayBuffer): string { return [...new Uint8Array(buffer)].map(n => n.toString(16).padStart(2, '0')).join('') }
async function derive(password: string, salt: string) {
  const bytes = new TextEncoder()
  const secret = await crypto.subtle.importKey('raw', bytes.encode(password), 'PBKDF2', false, ['deriveBits'])
  return hex(await crypto.subtle.deriveBits({ name: 'PBKDF2', salt: bytes.encode(salt), iterations: 210000, hash: 'SHA-256' }, secret, 256))
}
function initialSession(): string | null { try { return sessionStorage.getItem(SESSION) } catch { return null } }
export function AuthProvider({ children }: { children: ReactNode }) {
  const { users, setCurrentUserId } = useUsers()
  const [credentials, setCredentials] = useState<Credentials>(readCredentials)
  const [sessionId, setSessionId] = useState<string | null>(initialSession)
  const needsSetup = !credentials[DEMO_CURRENT_USER_ID]
  const active = users.find(u => u.id === sessionId && u.status === 'actif')
  const userId = active && credentials[active.id] ? active.id : null
  // UsersContext restaure la session réelle au chargement ; ne pas écraser un profil simulé à chaque rendu.
  const persist = useCallback((next: Credentials) => { localStorage.setItem(KEY, JSON.stringify(next)); setCredentials(next) }, [])
  const setPassword = useCallback(async (id: string, password: string) => {
    if (password.length < 12) throw new Error('Utilise au moins 12 caractères.')
    if (!users.some(u => u.id === id && u.status === 'actif')) throw new Error('Compte introuvable ou inactif.')
    const salt = hex(crypto.getRandomValues(new Uint8Array(16)).buffer)
    persist({ ...readCredentials(), [id]: { salt, hash: await derive(password, salt) } })
  }, [persist, users])
  const setTemporaryPassword = useCallback(async (id: string, password: string) => {
    if (password.length < 12) throw new Error('Utilise au moins 12 caractères.')
    if (!users.some(u => u.id === id && u.status === 'actif')) throw new Error('Compte introuvable ou inactif.')
    const salt = hex(crypto.getRandomValues(new Uint8Array(16)).buffer)
    persist({ ...readCredentials(), [id]: { salt, hash: await derive(password, salt), mustChange: true } })
  }, [persist, users])
  const findUser = useCallback((identifier: string) => {
    const query = identifier.trim().toLocaleLowerCase('fr')
    return users.find(u => u.status === 'actif' && ((u.id === DEMO_CURRENT_USER_ID && query === 'admin') || (u.email.trim() && u.email.trim().toLocaleLowerCase('fr') === query)))
  }, [users])
  const changePassword = useCallback(async (identifier: string, current: string, next: string) => {
    const user = findUser(identifier)
    const record = user && readCredentials()[user.id]
    if (!record || !current || await derive(current, record.salt) !== record.hash) throw new Error('Identifiant ou mot de passe actuel incorrect.')
    if (next.length < 12) throw new Error('Le nouveau mot de passe doit contenir au moins 12 caractères.')
    if (current === next) throw new Error('Le nouveau mot de passe doit être différent de l’ancien.')
    const salt = hex(crypto.getRandomValues(new Uint8Array(16)).buffer)
    persist({ ...readCredentials(), [user!.id]: { salt, hash: await derive(next, salt), mustChange: false } })
  }, [findUser, persist])
  const initializeAdmin = useCallback(async (password: string) => {
    if (readCredentials()[DEMO_CURRENT_USER_ID]) throw new Error('Le compte administrateur est déjà initialisé.')
    await setPassword(DEMO_CURRENT_USER_ID, password)
  }, [setPassword])
  const signIn = useCallback(async (identifier: string, password: string): Promise<string | null> => {
    const user = findUser(identifier)
    if (!user || !credentials[user.id] || !password) return 'Identifiant ou mot de passe incorrect.'
    const record = credentials[user.id]
    if (await derive(password, record.salt) !== record.hash) return 'Identifiant ou mot de passe incorrect.'
    if (record.mustChange) return 'PASSWORD_CHANGE_REQUIRED'
    sessionStorage.setItem(SESSION, user.id)
    setSessionId(user.id)
    setCurrentUserId(user.id)
    return null
  }, [findUser, credentials, setCurrentUserId])
  const signOut = useCallback(() => { sessionStorage.removeItem(SESSION); sessionStorage.removeItem('ob-test-current-user-v1'); setSessionId(null) }, [])
