        ),
    }),
    [etablissements],
  )

  return (
    <EtablissementsContext.Provider value={value}>
      {children}
    </EtablissementsContext.Provider>
  )
}

export function useEtablissements() {
  const context = useContext(
    EtablissementsContext,
  )

  if (!context) {
