/* =========================================================
   CLÉS DE STOCKAGE

   On conserve les anciennes clés.
   Les dépôts utilisent une nouvelle clé.
   ========================================================= */

const DONATEURS_KEY = 'ob-donateurs'

const COMMANDES_KEY = 'ob-commandes'

const FICHES_KEY = 'ob-fiches-caisse'

const CAMPAGNES_KEY = 'ob-campagnes-v1'

const DEPOTS_KEY = 'ob-depots-banque-v1'

/* =========================================================
   CHARGEMENT DES TABLEAUX
   ========================================================= */

function loadArray<T>(
  key: string,
  fallback: T[],
): T[] {
  try {
    const saved = localStorage.getItem(key)

    if (!saved) {
      return fallback
    }

    const parsed: unknown = JSON.parse(saved)

    return Array.isArray(parsed)
      ? parsed as T[]
      : fallback
  } catch {
    return fallback
  }
}

/* =========================================================
   EXTRACTION DE L'ANNÉE

   Exemple : "OB 2026" => 2026
   ========================================================= */

function getYearFromCode(
  code: string,
): number | null {
  const match = code.match(
    /\b(?:19|20)\d{2}\b/,
  )

  return match
    ? Number(match[0])
    : null
}

/* =========================================================
   RECONSTITUTION D'UNE ANCIENNE CAMPAGNE

   Permet de conserver les campagnes référencées
   par les commandes et les fiches existantes.
   ========================================================= */

function createLegacyCampagne(
  code: string,
): Campagne {
  const annee = getYearFromCode(code)

  return {
    id: code,

    annee,

    nom: annee
      ? `Opération Brioches ${annee}`
      : code,

    description: '',

    statut:
      code === 'OB 2026'
        ? 'ACTIVE'
        : 'A_CONFIGURER',

    dateDebut: '',
    dateFin: '',

    prixUnitaire: null,

    objectifBrioches: null,
    objectifDonateurs: null,
    budgetPrevisionnel: null,
  }
}

/* =========================================================
   VALIDATION DES CAMPAGNES ENREGISTRÉES
   ========================================================= */

function isCampagne(
  value: unknown,
): value is Campagne {
  if (
    typeof value !== 'object' ||
    value === null
  ) {
    return false
  }

  const item = value as Record<
    string,
    unknown
  >

  return (
    typeof item.id === 'string' &&
    item.id.length > 0 &&

    (
      typeof item.annee === 'number' ||
      item.annee === null
    ) &&

    typeof item.nom === 'string' &&

    typeof item.description === 'string' &&

    typeof item.dateDebut === 'string' &&

    typeof item.dateFin === 'string' &&

    (
      item.statut === 'A_CONFIGURER' ||
      item.statut === 'PREPARATION' ||
      item.statut === 'ACTIVE' ||
      item.statut === 'TERMINEE'
    ) &&

    (
      item.prixUnitaire === null ||
      (
        typeof item.prixUnitaire === 'number' &&
        Number.isFinite(item.prixUnitaire)
      )
    ) &&

    (
      item.objectifBrioches === null ||
      typeof item.objectifBrioches === 'number'
    ) &&

    (
      item.objectifDonateurs === null ||
      typeof item.objectifDonateurs === 'number'
    ) &&

    (
      item.budgetPrevisionnel === null ||
      typeof item.budgetPrevisionnel === 'number'
    )
  )
}

/* =========================================================
   CHARGEMENT DES CAMPAGNES
   ========================================================= */

function loadCampagnes(
  commandes: Commande[],
  fichesCaisse: FicheCaisse[],
): Campagne[] {
  const codes = new Set<string>()

  // On conserve la campagne historique du prototype.

  codes.add('OB 2026')

  // Campagnes référencées par les commandes.

  for (const commande of commandes) {
    if (commande.campagne?.trim()) {
      codes.add(
        commande.campagne.trim(),
      )
    }
  }

  // Campagnes référencées par les fiches de caisse.

  for (const fiche of fichesCaisse) {
    if (fiche.campagne?.trim()) {
      codes.add(
        fiche.campagne.trim(),
      )
    }
  }

  const existing: Campagne[] = []

  try {
    const saved = localStorage.getItem(
      CAMPAGNES_KEY,
    )

    if (saved) {
      const parsed: unknown = JSON.parse(saved)

      if (Array.isArray(parsed)) {
        existing.push(
          ...parsed.filter(isCampagne),
        )
      }
    }
  } catch {
    // Les anciennes références permettent
    // de récupérer les campagnes.
  }

  const result = new Map<
    string,
    Campagne
  >()

  // Les paramètres déjà enregistrés sont prioritaires.

  for (const campagne of existing) {
    result.set(
      campagne.id,
      campagne,
    )
  }

  // Reconstitution des campagnes manquantes.

  for (const code of codes) {
    if (!result.has(code)) {
      result.set(
        code,
        createLegacyCampagne(code),
      )
    }
  }

  const campagnes = [
    ...result.values(),
  ]

  // Une seule campagne peut être active.

  let activeFound = false

  return campagnes.map(
    (campagne) => {
      if (campagne.statut !== 'ACTIVE') {
        return campagne
      }

      if (!activeFound) {
        activeFound = true

        return campagne
      }

      return {
        ...campagne,
        statut: 'PREPARATION',
      }
    },
  )
}

/* =========================================================
   DATE LOCALE

   Format YYYY-MM-DD pour le suivi des dépôts.
   ========================================================= */

function getLocalDate(): string {
  const date = new Date()

  const year = date.getFullYear()

  const month = String(
    date.getMonth() + 1,
  ).padStart(2, '0')

  const day = String(
    date.getDate(),
  ).padStart(2, '0')

  return `${year}-${month}-${day}`
}

/* =========================================================
   IDENTIFIANT UNIQUE POUR LES DÉPÔTS
   ========================================================= */

function createDepotId(): string {
  if (
    typeof crypto !== 'undefined' &&
    typeof crypto.randomUUID === 'function'
  ) {
    return crypto.randomUUID()
  }

  return [
    'depot',
    Date.now(),
    Math.random().toString(36).slice(2),
  ].join('-')
}

/* =========================================================
   TYPE POUR LA CRÉATION D'UN DÉPÔT

   L'identifiant, la date et le statut sont
   définis automatiquement par le contexte.
   ========================================================= */

export type NouveauDepotBanque = Omit<
  DepotBanque,
  'id' | 'date' | 'statut'
>

/* =========================================================
   TYPE DU CONTEXTE
   ========================================================= */

type ObDataContextValue = {

  /* DONATEURS */

  donateurs: Donateur[]

  setDonateurs: Dispatch<
    SetStateAction<Donateur[]>
  >

  /* COMMANDES */

  commandes: Commande[]

  setCommandes: Dispatch<
    SetStateAction<Commande[]>
  >

  /* FICHES DE CAISSE */

  fichesCaisse: FicheCaisse[]

  setFichesCaisse: Dispatch<
    SetStateAction<FicheCaisse[]>
  >

  /* CAMPAGNES */

  campagnes: Campagne[]

  activeCampagne: Campagne | null

  /** Campagne choisie pour la navigation locale (distincte du statut ACTIVE). */
  selectedCampagne: Campagne | null
  selectedCampagneId: string
  setSelectedCampagneId: (id: string) => void

  /* DÉPÔTS BANCAIRES */

  depotsBanque: DepotBanque[]

  creerDepotBanque: (
    entree: NouveauDepotBanque,
  ) => string

  annulerDepotBanque: (
    id: string,
  ) => void

  /* RECHERCHES */

  getDonateurById: (
    id: number,
  ) => Donateur | undefined

  getCommandesByDonateurId: (
    donateurId: number,
  ) => Commande[]

  getFicheCaisseById: (
    id: number,
  ) => FicheCaisse | undefined

  getCommandesByCampagne: (
    campagneId: string,
  ) => Commande[]

  getFichesByCampagne: (
    campagneId: string,
  ) => FicheCaisse[]

  getDepotsByCampagne: (
    campagneId: string,
  ) => DepotBanque[]

  /* GESTION DES CAMPAGNES */

  createCampagne: (
    input: NouvelleCampagne,
  ) => string

  updateCampagne: (
    id: string,
    details: CampagneDetails,
  ) => void

  duplicateCampagne: (
    id: string,
  ) => string

  activateCampagne: (
    id: string,
  ) => void

  finishCampagne: (
    id: string,
  ) => void
}

/* =========================================================
   CRÉATION DU CONTEXTE
   ========================================================= */

const ObDataContext = createContext<
  ObDataContextValue | undefined
>(undefined)

/* =========================================================
   PROVIDER PRINCIPAL
   ========================================================= */

export function ObDataProvider({
  children,
}: {
  children: ReactNode
}) {

  /* =======================================================
     1. DONATEURS
     ======================================================= */

  const [
    donateurs,
    setDonateurs,
  ] = useState<Donateur[]>(
    () =>
      loadArray(
        DONATEURS_KEY,
        initialDonateurs,
      ),
  )

  /* =======================================================
     2. COMMANDES
     ======================================================= */

  const [
    commandes,
    setCommandes,
  ] = useState<Commande[]>(
    () =>
      loadArray(
        COMMANDES_KEY,
        initialCommandes,
      ),
  )

  /* =======================================================
     3. FICHES DE CAISSE
     ======================================================= */

  const [
    fichesCaisse,
    setFichesCaisse,
  ] = useState<FicheCaisse[]>(
    () =>
      loadArray(
        FICHES_KEY,
        initialFichesCaisse,
      ),
  )

  /* =======================================================
     4. CAMPAGNES
     ======================================================= */

  const [
    campagnes,
    setCampagnes,
  ] = useState<Campagne[]>(
    () =>
      loadCampagnes(
        commandes,
        fichesCaisse,
      ),
  )

  /* Sélection de travail conservée dans ce navigateur. */
  const [selectedCampagneId, setSelectedCampagneIdState] = useState<string>(() => {
    try { return localStorage.getItem('ob-campagne-selection-v1') || '' } catch { return '' }
  })

  function setSelectedCampagneId(id: string) {
    setSelectedCampagneIdState(id)
    try {
      if (id) localStorage.setItem('ob-campagne-selection-v1', id)
      else localStorage.removeItem('ob-campagne-selection-v1')
    } catch { /* Stockage indisponible : état conservé jusqu'au rechargement. */ }
  }

  /* =======================================================
     5. DÉPÔTS BANCAIRES

     NOUVEAU

     Aucun dépôt fictif n'est créé.
     ======================================================= */

  const [
    depotsBanque,
    setDepotsBanque,
  ] = useState<DepotBanque[]>(
    () =>
      loadArray(
        DEPOTS_KEY,
        [],
      ),
  )

  /* =======================================================
     CAMPAGNE ACTIVE
     ======================================================= */

  const activeCampagne = useMemo(
    () =>
      campagnes.find(
        campagne =>
          campagne.statut === 'ACTIVE',
      ) ?? null,

    [campagnes],
  )

  const selectedCampagne = useMemo(
    () => campagnes.find(c => c.id === selectedCampagneId) ?? activeCampagne,
    [campagnes, selectedCampagneId, activeCampagne],
  )

  /* =======================================================
     SAUVEGARDE DES DONATEURS
     ======================================================= */

  useEffect(() => {
    localStorage.setItem(
      DONATEURS_KEY,
      JSON.stringify(donateurs),
    )
  }, [donateurs])

  /* =======================================================
     SAUVEGARDE DES COMMANDES
     ======================================================= */

  useEffect(() => {
    localStorage.setItem(
      COMMANDES_KEY,
      JSON.stringify(commandes),
    )
  }, [commandes])

  /* =======================================================
     SAUVEGARDE DES FICHES DE CAISSE
     ======================================================= */

  useEffect(() => {
    localStorage.setItem(
      FICHES_KEY,
      JSON.stringify(fichesCaisse),
    )
  }, [fichesCaisse])

  /* =======================================================
     SAUVEGARDE DES CAMPAGNES
     ======================================================= */

  useEffect(() => {
    try {
      localStorage.setItem(
        CAMPAGNES_KEY,
        JSON.stringify(campagnes),
      )
    } catch {
      console.warn(
        'Sauvegarde locale des campagnes indisponible.',
      )
    }
  }, [campagnes])

  /* =======================================================
     6. CRÉER UN DÉPÔT BANCAIRE

     RÈGLES :

     - campagne existante ;
     - référence obligatoire et unique ;
     - dépôt non vide ;
     - validation par le moteur du coffre ;
     - sauvegarde avant modification de l'état.

     Le calcul refuse un dépôt qui rendrait
     le stock négatif.
     ======================================================= */

  function creerDepotBanque(
    entree: NouveauDepotBanque,
  ): string {

    /* CAMPAGNE */

    const campagne = entree.campagne.trim()

    if (
      !campagne ||
      !campagnes.some(
        item =>
          item.id === campagne,
      )
    ) {
      throw new Error(
        'Campagne inconnue pour ce dépôt.',
      )
    }

    /* RÉFÉRENCE */

    const reference =
      entree.reference.trim()

    if (!reference) {
      throw new Error(
        'La référence du bordereau est obligatoire.',
      )
    }

    const referenceExiste =
      depotsBanque.some(
        depot =>
          depot.campagne === campagne &&
          depot.reference
            .trim()
            .toLowerCase() ===
          reference.toLowerCase(),
      )

    if (referenceExiste) {
      throw new Error(
        'Cette référence de dépôt existe déjà pour cette campagne.',
      )
    }

    /* LE DÉPÔT DOIT CONTENIR DES FONDS */

    const contientPieces =
      PIECES.some(
        piece =>
          entree[piece.key] > 0,
      )

    const contientBillets =
      BILLETS.some(
        billet =>
          entree[billet.key] > 0,
      )

    const contientCheques =
      entree.nbCheques > 0 ||
      entree.montantCheques > 0

    if (
      !contientPieces &&
      !contientBillets &&
      !contientCheques
    ) {
      throw new Error(
        'Le dépôt est vide. Indiquez les espèces ou les chèques déposés.',
      )
    }

    /* CRÉATION DU DÉPÔT */

    const id = createDepotId()

    const depot: DepotBanque = {
      ...entree,

      id,

      campagne,

      reference,

      date: getLocalDate(),

      statut: 'ENREGISTRE',
    }

    /* =====================================================
       VALIDATION AVANT ENREGISTREMENT

       On simule le dépôt dans le moteur.

       Si un montant ou une quantité devient
       négatif, calculerCoffre déclenche
       une erreur.

       Rien n'est enregistré dans ce cas.
       ===================================================== */

    const prochainsDepots = [
      ...depotsBanque,
      depot,
    ]

    calculerCoffre(
      campagne,
      fichesCaisse,
      prochainsDepots,
    )

    /* =====================================================
       SAUVEGARDE

       Si localStorage échoue, le dépôt n'est
       pas ajouté à l'état React.
       ===================================================== */

    localStorage.setItem(
      DEPOTS_KEY,
      JSON.stringify(
        prochainsDepots,
      ),
    )

    setDepotsBanque(
      prochainsDepots,
    )

    return id
  }

  /* =======================================================
     7. ANNULER UN DÉPÔT BANCAIRE

     On ne supprime pas l'enregistrement.

     Son statut passe à ANNULE, ce qui permet
     au coffre de réintégrer les sommes.
     ======================================================= */

  function annulerDepotBanque(
    id: string,
  ): void {
    const depot = depotsBanque.find(
      item =>
        item.id === id,
    )

    if (!depot) {
      throw new Error(
        'Dépôt bancaire introuvable.',
      )
    }

    if (depot.statut !== 'ENREGISTRE') {
      throw new Error(
        'Ce dépôt est déjà annulé.',
      )
    }

    const prochainsDepots: DepotBanque[] =
      depotsBanque.map(
        item =>
          item.id === id
            ? {
                ...item,

                statut: 'ANNULE',

                dateAnnulation:
                  new Date().toISOString(),
              }
            : item,
      )

    /* SAUVEGARDE */

    localStorage.setItem(
      DEPOTS_KEY,
      JSON.stringify(
        prochainsDepots,
      ),
    )

    setDepotsBanque(
      prochainsDepots,
    )
  }

  /* =======================================================
     8. CRÉER UNE CAMPAGNE
     ======================================================= */

  function createCampagne(
    input: NouvelleCampagne,
  ): string {
    const annee = input.annee

    const id = `OB ${annee}`

    if (
      !Number.isInteger(annee) ||
      annee < 2000 ||
      annee > 2100
    ) {
      throw new Error(
        "L'année de campagne est invalide.",
      )
    }

    if (
      campagnes.some(
        campagne =>
          campagne.id === id ||
          campagne.annee === annee,
      )
    ) {
      throw new Error(
        `La campagne ${annee} existe déjà.`,
      )
    }

    if (
      input.dateDebut &&
      input.dateFin &&
      input.dateFin < input.dateDebut
    ) {
      throw new Error(
        'La date de fin précède la date de début.',
      )
    }

    const nouvelle: Campagne = {
      ...input,

      id,

      nom:
        input.nom.trim() ||
        `Opération Brioches ${annee}`,

      statut: 'PREPARATION',
    }

    setCampagnes(
      current => [
        ...current,
        nouvelle,
      ],
    )

    return id
  }

  /* =======================================================
     9. MODIFIER UNE CAMPAGNE
     ======================================================= */

  function updateCampagne(
    id: string,
    details: CampagneDetails,
  ): void {
    const target = campagnes.find(
      campagne =>
        campagne.id === id,
    )

    if (!target) {
      throw new Error(
        'Campagne introuvable.',
      )
    }

    if (target.statut === 'TERMINEE') {
      throw new Error(
        'Cette campagne est terminée.',
      )
    }

    if (
      details.dateDebut &&
      details.dateFin &&
      details.dateFin < details.dateDebut
    ) {
      throw new Error(
        'La date de fin précède la date de début.',
      )
    }

    setCampagnes(
      current =>
        current.map(
          campagne =>
            campagne.id === id
              ? {
                  ...campagne,

                  ...details,

                  nom:
                    details.nom.trim(),

                  statut:
                    campagne.statut ===
                    'A_CONFIGURER'
                      ? 'PREPARATION'
                      : campagne.statut,
                }
              : campagne,
        ),
    )
  }

  /* =======================================================
     10. DUPLIQUER UNE CAMPAGNE

     Les commandes, fiches et dépôts bancaires
     ne sont jamais dupliqués.
     ======================================================= */

  function duplicateCampagne(
    id: string,
  ): string {
    const source = campagnes.find(
      campagne =>
        campagne.id === id,
    )

    if (
      !source ||
      source.annee === null
    ) {
      throw new Error(
        'Cette campagne ne peut pas être dupliquée.',
      )
    }

    let year =
      source.annee + 1

    while (
      campagnes.some(
        campagne =>
          campagne.annee === year ||
          campagne.id ===
            `OB ${year}`,
      )
    ) {
      year += 1
    }

    return createCampagne({
      annee: year,

      nom:
        `Opération Brioches ${year}`,

      description: '',

      // Dates à revalider chaque année.

      dateDebut: '',
      dateFin: '',

      prixUnitaire:
        source.prixUnitaire,

      objectifBrioches:
        source.objectifBrioches,

      objectifDonateurs:
        source.objectifDonateurs,

      budgetPrevisionnel:
        source.budgetPrevisionnel,
    })
  }

  /* =======================================================
     11. ACTIVER UNE CAMPAGNE
     ======================================================= */

  function activateCampagne(
    id: string,
  ): void {
    const target = campagnes.find(
      campagne =>
        campagne.id === id,
    )

    if (!target) {
      throw new Error(
        'Campagne introuvable.',
      )
    }

    if (target.statut === 'TERMINEE') {
      throw new Error(
        'Une campagne terminée ne peut pas être réactivée.',
      )
    }

    if (
      target.prixUnitaire === null ||
      target.prixUnitaire <= 0
    ) {
      throw new Error(
        'Renseigne un prix unitaire valide avant activation.',
      )
    }

    setCampagnes(
      current =>
        current.map(
          campagne => {
            if (campagne.id === id) {
              return {
                ...campagne,

                statut: 'ACTIVE',
              }
            }

            if (
              campagne.statut ===
              'ACTIVE'
            ) {
              return {
                ...campagne,

                statut: 'PREPARATION',
              }
            }

            return campagne
          },
        ),
    )
  }

  /* =======================================================
     12. TERMINER UNE CAMPAGNE
     ======================================================= */

  function finishCampagne(
    id: string,
  ): void {
    const target = campagnes.find(
      campagne =>
        campagne.id === id,
    )

    if (!target) {
      throw new Error(
        'Campagne introuvable.',
      )
    }

    setCampagnes(
      current =>
        current.map(
          campagne =>
            campagne.id === id
              ? {
                  ...campagne,

                  statut: 'TERMINEE',
                }
              : campagne,
        ),
    )
  }

  /* =======================================================
     13. VALEURS PARTAGÉES
     ======================================================= */

  const value: ObDataContextValue = {

    /* DONATEURS */

    donateurs,
    setDonateurs,

    /* COMMANDES */

    commandes,
    setCommandes,

    /* FICHES DE CAISSE */

    fichesCaisse,
    setFichesCaisse,

    /* CAMPAGNES */

    campagnes,
    activeCampagne,
    selectedCampagne,
    selectedCampagneId,
    setSelectedCampagneId,

    /* DÉPÔTS BANCAIRES */

    depotsBanque,

    creerDepotBanque,

    annulerDepotBanque,

    /* RECHERCHES */

    getDonateurById: id =>
      donateurs.find(
        donateur =>
          donateur.id === id,
      ),

    getCommandesByDonateurId:
      donateurId =>
        commandes.filter(
          commande =>
            commande.donateurId ===
            donateurId,
        ),

    getFicheCaisseById: id =>
      fichesCaisse.find(
        fiche =>
          fiche.id === id,
      ),

    getCommandesByCampagne: id =>
      commandes.filter(
        commande =>
          commande.campagne === id,
      ),

    getFichesByCampagne: id =>
      fichesCaisse.filter(
        fiche =>
          fiche.campagne === id,
      ),

    getDepotsByCampagne: id =>
      depotsBanque.filter(
        depot =>
          depot.campagne === id,
      ),

    /* ACTIONS CAMPAGNES */

    createCampagne,

    updateCampagne,

    duplicateCampagne,

    activateCampagne,

    finishCampagne,
  }

  /* =======================================================
     PROVIDER
     ======================================================= */

  return (
    <ObDataContext.Provider
      value={value}
    >
      {children}
    </ObDataContext.Provider>
  )
}

/* =========================================================
   HOOK D'ACCÈS AUX DONNÉES
   ========================================================= */

export function useObData() {
  const context = useContext(
    ObDataContext,
  )

  if (!context) {
    throw new Error(
      'useObData doit être utilisé dans ObDataProvider.',
    )
  }

  return context
}

import {
  createContext,
  useContext,
  useEffect,
  useState,
  type ReactNode,
} from 'react'

import {
  ROLE_LABELS,
  type UserRole,
} from './UsersContext'

/* =========================================================
   TYPES
   ========================================================= */

import { PERMISSION_MODULES, type PermissionAction, type PermissionModule } from '../lib/permissionCatalog'
export { PERMISSION_MODULES, PERMISSION_ACTIONS } from '../lib/permissionCatalog'
export type { PermissionAction, PermissionModule } from '../lib/permissionCatalog'

type RolePermissions = Record<
  PermissionModule,
  PermissionAction[]
>

export type PermissionMatrix = Record<
  UserRole,
  RolePermissions
>

const STORAGE_KEY = 'ob-role-permissions-v1'

const roles = Object.keys(ROLE_LABELS) as UserRole[]

/* =========================================================
   VALEURS PAR DÉFAUT
   ========================================================= */

/** Règles non négociables des profils : une matrice locale ne peut pas les outrepasser. */
const DEVELOPER_READ_ONLY = new Set<PermissionModule>([
  'utilisateurs', 'roles', 'campagnes', 'parametres', 'admin_etablissements',
  'journal', 'coffre', 'suivi_banque', 'gestion_cheques', 'comptabilite',
  'fiches_caisse', 'justificatifs', 'recapitulatif',
])

export function allowedForRole(role: UserRole, module: PermissionModule, action: PermissionAction): boolean {
  if (role === 'administrateur') return true
  if (role === 'developpeur') {
    if (DEVELOPER_READ_ONLY.has(module)) return action === 'consulter'
    if (action === 'supprimer' || action === 'valider') return false
    return true
  }
  if (role === 'stagiaire_communication') {
    if (module === 'accueil' || module === 'dashboard' || module === 'communication' || module === 'stands_brioches' || module === 'benevoles' || module === 'geographie') return action === 'consulter'
    return false
  }
  if (role === 'stagiaire_comptabilite') {
    if (module === 'accueil' || module === 'dashboard' || module === 'comptabilite' || module === 'justificatifs' || module === 'fiches_caisse') return action === 'consulter'
    return false
  }
  return true
}

function createDefaultMatrix(): PermissionMatrix {
  const matrix = {} as PermissionMatrix

  for (const role of roles) {
    const rolePermissions = {} as RolePermissions

    for (const module of PERMISSION_MODULES) {
      rolePermissions[module.key] =
        role === 'administrateur' || role === 'developpeur' || role.startsWith('stagiaire_')
          ? module.actions.filter(action => allowedForRole(role, module.key, action))
          : []
    }

    matrix[role] = rolePermissions
  }

  return matrix
}

/* =========================================================
   CHARGEMENT LOCAL
   ========================================================= */

function loadPermissions(): PermissionMatrix {
  const defaults = createDefaultMatrix()

  try {
    const stored = localStorage.getItem(STORAGE_KEY)

    if (!stored) return defaults

    const parsed: unknown = JSON.parse(stored)

    if (
      typeof parsed !== 'object' ||
      parsed === null
    ) {
      return defaults
    }

    const savedMatrix = parsed as Record<string, unknown>

    for (const role of roles) {
      // Le rôle administrateur reste protégé.
      if (role === 'administrateur') continue

      const savedRole = savedMatrix[role]

      if (
        typeof savedRole !== 'object' ||
        savedRole === null
      ) {
        continue
      }

      const savedModules = savedRole as Record<
        string,
        unknown
      >

      for (const module of PERMISSION_MODULES) {
        const savedActions = savedModules[module.key]

        if (!Array.isArray(savedActions)) continue

        const validActions = module.actions.filter(
          (action) => savedActions.includes(action) && allowedForRole(role, module.key, action),
        )

        defaults[role][module.key] =
          validActions.includes('consulter')
            ? [...validActions]
            : []
      }
    }

    return defaults
  } catch {
    return defaults
  }
}

/* =========================================================
   CONTEXTE
   ========================================================= */

type PermissionsContextValue = {
  permissions: PermissionMatrix

  hasPermission: (
    role: UserRole,
    module: PermissionModule,
    action: PermissionAction,
  ) => boolean

  togglePermission: (
    role: UserRole,
    module: PermissionModule,
    action: PermissionAction,
  ) => void

  resetRole: (role: UserRole) => void
}

const PermissionsContext = createContext<
  PermissionsContextValue | undefined
>(undefined)

/* =========================================================
   PROVIDER
   ========================================================= */

export function PermissionsProvider({
  children,
}: {
  children: ReactNode
}) {
  const [permissions, setPermissions] =
    useState<PermissionMatrix>(loadPermissions)

  useEffect(() => {
    try {
      localStorage.setItem(
        STORAGE_KEY,
        JSON.stringify(permissions),
      )
    } catch {
      console.warn(
        'Sauvegarde locale des permissions indisponible.',
      )
    }
  }, [permissions])

  /* VÉRIFICATION */

  function hasPermission(
    role: UserRole,
    module: PermissionModule,
    action: PermissionAction,
  ) {
    // L'administrateur conserve tous les droits, même pour un module
    // ajouté après la dernière sauvegarde locale des permissions.
    if (role === 'administrateur') return true
    if (!allowedForRole(role, module, action)) return false
    return permissions[role]?.[module]?.includes(action) ?? false
  }

  /* MODIFICATION */

  function togglePermission(
    role: UserRole,
    moduleKey: PermissionModule,
    action: PermissionAction,
  ) {
    if (role === 'administrateur' || !allowedForRole(role, moduleKey, action)) return

    const moduleDefinition = PERMISSION_MODULES.find(
      (module) => module.key === moduleKey,
    )

    if (
      !moduleDefinition ||
      !moduleDefinition.actions.some(
        (available) => available === action,
      )
    ) {
      return
    }

    setPermissions((current) => {
      const existing = current[role]?.[moduleKey] ?? []

      let updated: PermissionAction[]

      if (existing.includes(action)) {
        updated =
          action === 'consulter'
            ? []
            : existing.filter(
                (item) => item !== action,
              )
      } else {
        updated = Array.from(
          new Set<PermissionAction>([
            ...existing,
            'consulter',
            action,
          ]),
        )
      }

      return {
        ...current,
        [role]: {
          ...current[role],
          [moduleKey]: updated,
        },
      }
    })
  }

  /* RÉINITIALISATION */

  function resetRole(role: UserRole) {
    if (role === 'administrateur') return

    const defaults = createDefaultMatrix()

    setPermissions((current) => ({
      ...current,
      [role]: defaults[role],
    }))
  }

  return (
    <PermissionsContext.Provider
      value={{
        permissions,
        hasPermission,
        togglePermission,
        resetRole,
      }}
    >
      {children}
    </PermissionsContext.Provider>
  )
}

/* =========================================================
   HOOK
   ========================================================= */

export function usePermissions() {
  const context = useContext(PermissionsContext)

  if (!context) {
    throw new Error(
      'usePermissions doit être utilisé dans PermissionsProvider.',
    )
  }

  return context
}

import {
  createContext,
  useContext,
  useEffect,
  useMemo,
  useState,
  type Dispatch,
  type ReactNode,
  type SetStateAction,
} from 'react'

import type {
  MouvementMateriel,
  NouveauMouvementMateriel,
} from '../types/suiviMateriel'

const STORAGE_KEY =
  'ob-suivi-caisse-tpe-v1'

type SuiviMaterielContextValue = {
  mouvements: MouvementMateriel[]
  setMouvements: Dispatch<
    SetStateAction<MouvementMateriel[]>
  >
  createMouvement: (
    input: NouveauMouvementMateriel,
  ) => string
  updateMouvement: (
    id: string,
    input: NouveauMouvementMateriel,
  ) => void
  deleteMouvement: (
    id: string,
  ) => void
}

const SuiviMaterielContext =
  createContext<
    SuiviMaterielContextValue | undefined
  >(undefined)

function loadMouvements():
  MouvementMateriel[] {
  try {
    const raw =
      localStorage.getItem(
        STORAGE_KEY,
      )

    if (!raw) return []

    const parsed: unknown =
      JSON.parse(raw)

    return Array.isArray(parsed)
      ? (parsed as MouvementMateriel[])
      : []
  } catch {
    return []
  }
}

function createId() {
  if (
    typeof crypto !== 'undefined' &&
    typeof crypto.randomUUID === 'function'
  ) {
    return crypto.randomUUID()
  }

  return `suivi-${Date.now()}-${Math.random()
    .toString(36)
    .slice(2)}`
}

export function SuiviMaterielProvider({
  children,
}: {
  children: ReactNode
}) {
  const [
    mouvements,
    setMouvements,
  ] = useState<
    MouvementMateriel[]
  >(loadMouvements)

  useEffect(() => {
    localStorage.setItem(
      STORAGE_KEY,
      JSON.stringify(mouvements),
    )
  }, [mouvements])

  const value = useMemo<
    SuiviMaterielContextValue
  >(
    () => ({
      mouvements,
      setMouvements,

      createMouvement: (
        input,
      ) => {
        const id = createId()
        const now =
          new Date().toISOString()

        setMouvements(
          (current) => [
            ...current,
            {
              ...input,
              id,
              createdAt: now,
              updatedAt: now,
            },
          ],
        )

        return id
      },

      updateMouvement: (
        id,
        input,
      ) => {
        setMouvements(
          (current) =>
            current.map(
              (mouvement) =>
                mouvement.id === id
                  ? {
                      ...mouvement,
                      ...input,
                      updatedAt:
                        new Date().toISOString(),
                    }
                  : mouvement,
            ),
        )
      },

      deleteMouvement: (
        id,
      ) => {
        setMouvements(
          (current) =>
            current.filter(
              (mouvement) =>
                mouvement.id !== id,
            ),
        )
      },
    }),
    [mouvements],
  )

  return (
    <SuiviMaterielContext.Provider
      value={value}
    >
      {children}
    </SuiviMaterielContext.Provider>
  )
}

export function useSuiviMateriel() {
  const context = useContext(
    SuiviMaterielContext,
  )

  if (!context) {
    throw new Error(
      'useSuiviMateriel doit être utilisé dans SuiviMaterielProvider',
    )
  }

  return context
}

import { testModeEnabled, TEST_MODE_AVAILABLE } from '../lib/testMode'
import {
  createContext,
  useContext,
  useEffect,
  useMemo,
  useState,
  type ReactNode,
} from 'react'

/* =========================================================
   TYPES
   ========================================================= */

export const ROLE_LABELS = {
  administrateur: 'Administrateur',
  communication: 'Communication',
  comptabilite: 'Comptabilité',
  etablissement: 'Établissement',
  terrain: 'Coordinateur terrain',
  direction: 'Direction',
  stagiaire_communication: 'Stagiaire Communication',
  stagiaire_comptabilite: 'Stagiaire Comptabilité',
  developpeur: 'Développeur',
} as const

export type UserRole = keyof typeof ROLE_LABELS

export type UserStatus = 'actif' | 'inactif'

/** Affichage cohérent pour toute l'application : Prénom Nom. */
export function getUserDisplayName(user: Pick<AppUser, 'name' | 'prenom' | 'nom'> | null | undefined): string {
  if (!user) return 'Utilisateur'
  const ordered = [user.prenom?.trim(), user.nom?.trim()].filter(Boolean).join(' ')
  return ordered || user.name || 'Utilisateur'
}

export const POLE_LABELS = {
  communication: 'Communication',
  comptabilite: 'Comptabilité',
} as const
export type UserPole = keyof typeof POLE_LABELS


export type AppUser = {
  id: string
  name: string
  nom?: string
  prenom?: string
  email: string
  poste: string
  pole?: UserPole | null
  responsablePole?: boolean
  role: UserRole
  perimetre: string
  etablissementId?: string // Compatibilité avec les anciens modules
  etablissementIds?: string[]
  tousEtablissements?: boolean
  status: UserStatus
}

export type UserInput = Pick<
  AppUser,
  'name' | 'nom' | 'prenom' | 'email' | 'poste' | 'role' | 'perimetre' | 'etablissementId' | 'etablissementIds' | 'tousEtablissements'
> & Partial<Pick<AppUser, 'pole' | 'responsablePole'>>

/* =========================================================
   DONNÉES LOCALES
   ========================================================= */

const STORAGE_KEY = 'ob-users-v1'

// Identifiant provisoire du profil actuellement affiché
// dans la Topbar. Il sera remplacé par l'identifiant
// fourni par l'authentification.
export const DEMO_CURRENT_USER_ID = 'demo-admin'

const demoAdmin: AppUser = {
  id: DEMO_CURRENT_USER_ID,
  name: 'Maxime Claudel',
  nom: 'Claudel',
  prenom: 'Maxime',
  email: '',
  poste: '',
  role: 'administrateur',
  perimetre: '',
  status: 'actif',
  etablissementIds: [],
  tousEtablissements: true,
}

/* =========================================================
   VALIDATION DES DONNÉES STOCKÉES
   ========================================================= */

function isAppUser(value: unknown): value is AppUser {
  if (typeof value !== 'object' || value === null) {
    return false
  }

  const user = value as Record<string, unknown>

  return (
    typeof user.id === 'string' &&
    typeof user.name === 'string' &&
    typeof user.email === 'string' &&
    typeof user.poste === 'string' &&
    typeof user.perimetre === 'string' &&
    typeof user.role === 'string' &&
    user.role in ROLE_LABELS &&
    (user.status === 'actif' ||
      user.status === 'inactif')
  )
}

/** Harmonise les comptes anciens (un seul établissement) avec le modèle multi-sites. */
function normalizeUser(user: AppUser): AppUser {
  const ids = Array.isArray(user.etablissementIds)
    ? user.etablissementIds.filter((id): id is string => typeof id === 'string' && id.length > 0)
    : (user.etablissementId ? [user.etablissementId] : [])
  const etablissementIds = [...new Set(ids)]
  const tousEtablissements = user.tousEtablissements === true
  return {
    ...user,
    name: user.prenom?.trim() && user.nom?.trim() ? `${user.prenom.trim()} ${user.nom.trim()}` : user.name,
    pole: user.pole && user.pole in POLE_LABELS ? user.pole : null,
    responsablePole: Boolean(user.responsablePole && user.pole && user.pole in POLE_LABELS),
    etablissementIds: tousEtablissements ? [] : etablissementIds,
    etablissementId: tousEtablissements ? '' : (etablissementIds[0] ?? ''),
    tousEtablissements,
  }
}

/* =========================================================
   CHARGEMENT
   ========================================================= */

function loadUsers(): AppUser[] {
  try {
    const saved = localStorage.getItem(STORAGE_KEY)

    if (!saved) {
      return [demoAdmin]
    }

    const parsed: unknown = JSON.parse(saved)

    if (!Array.isArray(parsed)) {
      return [demoAdmin]
    }

    const validUsers = parsed.filter(isAppUser).map(normalizeUser)

    // Conserver le profil de démonstration tant que
    // l'authentification n'est pas développée.
    if (
      !validUsers.some(
        (user) => user.id === DEMO_CURRENT_USER_ID,
      )
    ) {
      return [demoAdmin, ...validUsers]
    }

    // Le compte système reste toujours actif et administrateur, même si
    // une ancienne sauvegarde locale contient une version modifiée.
    return [demoAdmin, ...validUsers.filter(user => user.id !== DEMO_CURRENT_USER_ID)]
  } catch {
    return [demoAdmin]
  }
}

/* =========================================================
   CONTEXTE
   ========================================================= */

type UsersContextValue = {
  users: AppUser[]
  currentUserId: string
  setCurrentUserId: (id: string) => void
  currentUser: AppUser | null
  addUser: (input: UserInput) => void
  updateUser: (id: string, input: UserInput) => void
  toggleUserStatus: (id: string) => void
}

const UsersContext = createContext<
  UsersContextValue | undefined
>(undefined)

/* =========================================================
   PROVIDER
   ========================================================= */

export function UsersProvider({
  children,
}: {
  children: ReactNode
}) {
  const [users, setUsers] = useState<AppUser[]>(loadUsers)
  const [selectedUserId, setSelectedUserId] = useState<string>(() => {
    try { return sessionStorage.getItem('ob2026-auth-session-v1') || DEMO_CURRENT_USER_ID }
    catch { return DEMO_CURRENT_USER_ID }
  })
  const currentUserId = users.some(user => user.id === selectedUserId && user.status === 'actif')
    ? selectedUserId
    : DEMO_CURRENT_USER_ID

  function setCurrentUserId(id: string) {
    // Session réelle : seule l'authentification choisit librement le profil.
    const sessionId = sessionStorage.getItem('ob2026-auth-session-v1')
    const simulationAutorisee = TEST_MODE_AVAILABLE && testModeEnabled() && sessionId === DEMO_CURRENT_USER_ID
    if (sessionId !== id && !simulationAutorisee) return
    if (!users.some(user => user.id === id && user.status === 'actif')) return
    setSelectedUserId(id)
  }

  // Quand le mode test est coupé, revenir immédiatement au vrai compte connecté.
  useEffect(() => {
    const restore = () => {
      if (testModeEnabled()) return
      try {
        const realId = sessionStorage.getItem('ob2026-auth-session-v1')
        if (realId) setSelectedUserId(realId)
      } catch { /* stockage indisponible */ }
    }
    window.addEventListener('ob2026-test-mode-change', restore)
    return () => window.removeEventListener('ob2026-test-mode-change', restore)
  }, [])

  /* SAUVEGARDE */

  useEffect(() => {
    try {
      localStorage.setItem(
        STORAGE_KEY,
        JSON.stringify(users),
      )
    } catch {
      console.warn(
        'Sauvegarde locale des utilisateurs indisponible.',
      )
    }
  }, [users])

  /* UTILISATEUR ACTUEL */

  const currentUser =
    users.find(
      (user) => user.id === currentUserId,
    ) ?? null

  /* AJOUT */

  function addUser(input: UserInput) {
    const newUser: AppUser = {
      ...normalizeUser({ ...input, id: crypto.randomUUID(), status: 'actif' }),
      status: 'actif',
    }

    setUsers((current) => {
      // Un responsable de pôle maximum ; aucun changement de rôle ni de droits.
      if (newUser.pole && newUser.responsablePole && current.some(u => u.status === 'actif' && u.pole === newUser.pole && u.responsablePole)) return current
      return [...current, newUser]
    })
  }

  /* MODIFICATION */

  function updateUser(id: string, input: UserInput) {
    setUsers((current) => {
      if (input.pole && input.responsablePole && current.some(u => u.id !== id && u.status === 'actif' && u.pole === input.pole && u.responsablePole)) return current
      return current.map((user) =>
        user.id === id
          ? {
              ...normalizeUser({ ...user, ...input }),
            }
          : user,
      )
    })
  }

  /* ACTIVATION / DÉSACTIVATION */

  function toggleUserStatus(id: string) {
    // Éviter de désactiver le profil de démonstration
    // avant la mise en place de l'authentification.
    if (id === DEMO_CURRENT_USER_ID) {
      return
    }

    setUsers((current) => {
      const target = current.find(u => u.id === id)
      if (target?.status === 'inactif' && target.pole && target.responsablePole && current.some(u => u.id !== id && u.status === 'actif' && u.pole === target.pole && u.responsablePole)) return current
      return current.map((user) =>
        user.id === id
          ? {
              ...user,
              status:
                user.status === 'actif'
                  ? 'inactif'
                  : 'actif',
            }
          : user,
      )
    })
  }

  /* VALEUR PARTAGÉE */

  const value = useMemo<UsersContextValue>(
    () => ({
      users,
      currentUserId,
      setCurrentUserId,
      currentUser,
      addUser,
      updateUser,
      toggleUserStatus,
    }),
    [users, currentUser, currentUserId],
  )

  return (
    <UsersContext.Provider value={value}>
      {children}
    </UsersContext.Provider>
  )
}

/* =========================================================
   HOOK UTILISATEURS
   ========================================================= */

export function useUsers() {
  const context = useContext(UsersContext)

  if (!context) {
    throw new Error(
      'useUsers doit être utilisé dans UsersProvider.',
    )
  }

  return context
}

