  /* =========================================================
     JOURNÉES
     ========================================================= */

  function toggleDay(
    date: string,
  ) {
    setCollapsedDays(
      (current) => ({
        ...current,

        [date]:
          !current[date],
      }),
    )
  }

  function expandAllDays() {
    setCollapsedDays({})
  }

  function collapseAllDays() {
    const next =
      groupes.reduce<
        Record<
          string,
          boolean
        >
      >(
        (
          result,
          groupe,
        ) => {
          result[
            groupe.date
          ] = true

          return result
        },
        {},
      )

    setCollapsedDays(
      next,
    )
  }

  /* =========================================================
     MODALE
     ========================================================= */

  function openCreateCommande() {
    if (!campagneId || lectureSeule) return
    setModalMode(
      'create',
    )

    setEditingCommande(
      null,
    )

    setPreselectedDonateurId(
      null,
    )

    setModalOpen(true)

    setActionMenuId(
      null,
    )

    setExportMenuOpen(
      false,
    )
  }

  function openEditCommande(
    commande: Commande,
  ) {
    if (!memeCampagneEntreprise(commande.campagne, campagneId) || !peutModifierCommande(commande)) return
    setModalMode(
      'edit',
    )

    setEditingCommande(
      commande,
    )

    setPreselectedDonateurId(
      commande.donateurId,
    )

    setModalOpen(true)

    setActionMenuId(
      null,
    )
  }

  function closeModal() {
    setModalOpen(false)

    setEditingCommande(
      null,
    )

    setPreselectedDonateurId(
      null,
    )

    if (
      searchParams.has(
        'donateur',
      )
    ) {
      searchParams.delete(
        'donateur',
      )

      setSearchParams(
        searchParams,
        {
          replace: true,
        },
      )
    }
  }

  function saveCommande(
    commande: Commande,
  ) {
    if (!campagneId || !memeCampagneEntreprise(commande.campagne, campagneId)) return
    if (modalMode === 'edit') {
      const original = commandes.find(item => item.id === commande.id)
      if (!original || !peutModifierCommande(original)) return
      // Une commande ne peut pas être déplacée silencieusement vers une autre campagne.
      if (!memeCampagneEntreprise(original.campagne, commande.campagne)) return
    } else if (lectureSeule) return
    if (
      modalMode ===
      'edit'
    ) {
      setCommandes(
        (current) =>
          current.map(
            (item) =>
              item.id ===
              commande.id
                ? commande
                : item,
          ),
      )
    } else {
      setCommandes(
        (current) => [
          ...current,
          commande,
        ],
      )
    }

    setSelectedCommande(
      commande,
    )

    closeModal()
  }

  function cancelCommande(
    commande: Commande,
  ) {
    if (!memeCampagneEntreprise(commande.campagne, campagneId) || !peutModifierCommande(commande)) return
    const updated: Commande = {
      ...commande,
      statut: 'ANNULEE',
    }

    setCommandes(
      (current) =>
        current.map(
          (item) =>
            item.id ===
            commande.id
              ? updated
              : item,
        ),
    )

    if (
      selectedCommande?.id ===
      commande.id
    ) {
      setSelectedCommande(
        updated,
      )
    }

    setActionMenuId(
      null,
    )
  }

  function resetFilters() {
    setSearch('')
    setStatutFilter(
      'Tous',
    )
  }

