        width: 20,
      },
      {
        header: 'Date',
        key: 'date',
        width: 14,
      },
      {
        header:
          'Campagne',
        key: 'campagne',
        width: 14,
      },
      {
        header:
          'Code donateur',
        key: 'code',
        width: 18,
      },
      {
        header:
          'Donateur',
        key: 'donateur',
        width: 35,
      },
      {
        header: 'Ville',
        key: 'ville',
        width: 22,
      },
      {
        header:
          'Quantité',
        key: 'quantite',
        width: 12,
      },
      {
        header:
          'Prix unitaire',
        key: 'prix',
        width: 15,
      },
      {
        header:
          'Montant',
        key: 'montant',
        width: 16,
      },
      {
        header:
          'Statut',
        key: 'statut',
        width: 16,
      },
      {
        header:
          'Règlement',
        key: 'reglement',
        width: 18,
      },
      {
        header: 'JDI',
        key: 'jdi',
        width: 9,
      },
      {
        header: 'JDP',
        key: 'jdp',
        width: 9,
      },
      {
        header: 'RF',
        key: 'rf',
        width: 9,
      },
    ]

    commandesVue.forEach(
      (commande) => {
        const donateur =
          getDonateur(
            commande.donateurId,
          )

        worksheet.addRow({
          numero:
            commande.numero,

          date:
            formatDateShort(
              commande.dateCommande,
            ),

          campagne:
            commande.campagne,

          code:
            donateur
              ? `DON-${donateur.code.padStart(
                  6,
                  '0',
                )}`
              : '',

          donateur:
            donateur?.nom ||
            '',

          ville:
            donateur?.ville ||
            '',

          quantite:
            commande.quantite,

          prix:
            commande.prixUnitaire,

          montant:
            commande.quantite *
            commande.prixUnitaire,

          statut:
            getStatutLabel(
              commande.statut,
            ),

          reglement:
            formatPaymentMethod(
              commande.modeReglement,
            ),

          jdi:
            commande.jdi ||
            '',

          jdp:
            commande.jdp ||
            '',

          rf:
            commande.rf ||
            '',
        })
      },
    )

    const header =
      worksheet.getRow(1)

    header.font = {
      bold: true,
      color: {
        argb:
          'FFFFFFFF',
      },
    }

    header.fill = {
      type: 'pattern',
      pattern: 'solid',
      fgColor: {
        argb:
          'FF063B7C',
      },
    }

    header.alignment = {
      horizontal:
        'center',
      vertical:
        'middle',
    }

    worksheet.views = [
      {
        state:
          'frozen',
        ySplit: 1,
      },
    ]

    worksheet.autoFilter = {
      from: {
        row: 1,
        column: 1,
      },
      to: {
        row: 1,
        column: 14,
      },
    }

    const buffer =
      await workbook.xlsx.writeBuffer()

    const blob =
      new Blob(
        [
          new Uint8Array(
            buffer,
          ),
        ],
        {
          type:
            'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
        },
      )

    downloadBlob(
      blob,
      `Commandes_${getFileDate()}.xlsx`,
    )

    setExportMenuOpen(
      false,
    )
  }

