function formatDonateurAddress(
  donateur: Donateur,
) {
  return [
    [
      donateur.numeroVoie,
      donateur.adresse,
    ]
      .filter(Boolean)
      .join(' '),

    [
      donateur.cp,
      donateur.ville,
    ]
      .filter(Boolean)
      .join(' '),
  ]
    .filter(Boolean)
    .join(' — ')
}

function getStatutLabel(
  statut:
    StatutCommande,
) {
  const labels:
    Record<
      StatutCommande,
      string
    > = {
    BROUILLON:
      'Brouillon',
    CONFIRMEE:
      'Confirmée',
    A_LIVRER:
      'À livrer',
    LIVREE:
      'Livrée',
    ANNULEE:
      'Annulée',
  }

  return labels[
    statut
  ]
}

function formatMoney(
  value: number,
) {
  return new Intl.NumberFormat(
    'fr-FR',
    {
      style: 'currency',
      currency: 'EUR',
    },
  ).format(value)
}

function formatNumber(
  value: number,
) {
  return new Intl.NumberFormat(
    'fr-FR',
  ).format(value)
}

function formatDateLong(
  value: string,
) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return value || 'Date à préciser'
  return new Intl.DateTimeFormat(
    'fr-FR',
    {
      weekday: 'long',
      day: 'numeric',
      month: 'long',
      year: 'numeric',
    },
  ).format(
    new Date(
      `${value}T12:00:00`,
    ),
  )
}

function formatDateShort(
  value: string,
) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return value || 'Date à préciser'
  return new Intl.DateTimeFormat(
    'fr-FR',
  ).format(
    new Date(
      `${value}T12:00:00`,
    ),
  )
}

function formatPaymentMethod(
  value?: string,
) {
  switch (value) {
    case 'CHEQUE':
      return 'Chèque'
    case 'ESPECES':
      return 'Espèces'
    case 'MANDAT':
      return 'Mandat administratif'
    case 'VIREMENT':
      return 'Virement'
    default:
      return value || '-'
  }
}

function getTodayInput() {
  const now =
    new Date()

  return [
    now.getFullYear(),
    String(
      now.getMonth() +
        1,
    ).padStart(
      2,
      '0',
    ),
    String(
      now.getDate(),
    ).padStart(
      2,
      '0',
    ),
  ].join('-')
}

function createCommandeNumber(
  commandes:
    Commande[],
) {
  const year =
    new Date().getFullYear()

  const max =
    commandes
      .filter(
        (commande) =>
          commande.numero.startsWith(
            `CMD-${year}-`,
          ),
      )
      .reduce(
        (
          current,
          commande,
        ) => {
          const match =
            commande.numero.match(
              /(\d+)$/,
            )

          return Math.max(
            current,
            match
              ? Number(
                  match[1],
                )
              : 0,
          )
        },
        0,
      )

  return `CMD-${year}-${String(
    max + 1,
  ).padStart(
    4,
    '0',
  )}`
}

function getFileDate() {
  return new Date()
    .toISOString()
    .slice(
      0,
      10,
    )
}

function downloadBlob(
  blob: Blob,
  filename: string,
) {
  const url =
    URL.createObjectURL(
      blob,
    )

  const link =
    document.createElement(
      'a',
    )

  link.href = url
  link.download =
    filename

  document.body.appendChild(
    link,
  )

  link.click()

  link.remove()

  URL.revokeObjectURL(
    url,
  )
}

