      <footer>Document généré depuis OB2026 · Vérifier les coordonnées et modalités avant transmission.</footer>
      </body></html>`
    const page = window.open('', '_blank')
    if (!page) { setMessage('Autorise les fenêtres pop-up pour ouvrir le bon de commande.'); return }
    page.document.open(); page.document.write(html); page.document.close(); page.focus()
  }

  const [recherche, setRecherche] = useState('')
  const [statut, setStatut] = useState<StatutFiltre>('TOUS')

  const fournisseursGms = useMemo(
    () => fournisseurs.filter(estGms),
    [fournisseurs],
  )

  const idsGms = useMemo(
    () => new Set(fournisseursGms.map((item) => item.id)),
    [fournisseursGms],
  )

  const commandesGms = useMemo(
    () =>
      commandesArtisans.filter((commande) =>
        idsGms.has(commande.artisanId) &&
        String(commande.campagne ?? '').match(/(?:19|20)\d{2}/)?.[0] === anneeCampagne,
      ),
    [commandesArtisans, idsGms, anneeCampagne],
  )

  const resultats = useMemo(() => {
    const motif = recherche.trim().toLocaleLowerCase('fr')

    return commandesGms.filter((commande) => {
      const GMS = nomGms(
        commande.artisanId,
        fournisseursGms,
      )

      const correspondRecherche =
        !motif ||
        [
          commande.numero,
          GMS,
          commande.secteur,
          commande.responsableSecteur,
          commande.personneRetrait,
          commande.campagne,
        ]
          .join(' ')
          .toLocaleLowerCase('fr')
          .includes(motif)

      const correspondCampagne = true

      const correspondStatut = statut === 'TOUS' || etapeCommande(commande) === statut

      return (
        correspondRecherche &&
        correspondCampagne &&
        correspondStatut
      )
    })
  }, [
    commandesGms,
    fournisseursGms,
    recherche,
    statut,
  ])

  const totalQuantite = useMemo(
    () =>
      resultats.reduce(
        (total, commande) =>
          total + commande.quantiteCommandee,
        0,
      ),
    [resultats],
  )

  const totalMontant = useMemo(
    () =>
      resultats.reduce(
        (total, commande) =>
          total + montantCommande(commande),
        0,
      ),
    [resultats],
  )

  return (
    <main className="ind-page">
      <header className="ind-header">
        <div>
          <span className="ind-eyebrow">
            COMMANDES ACHATS
          </span>

          <h1>GMS</h1>

          <p>
            Suivi des commandes de brioches auprès des
            fournisseurs GMS.
          </p>
        </div>
        <div className="ind-header-buttons"><button type="button" className="ind-cancel" onClick={exporterExcel}><Download size={17}/> Excel</button><button type="button" className="ind-primary" onClick={ouvrirCreation} disabled={!fournisseursGms.some(f => f.statut !== 'INACTIF')}>
          <Plus size={18} /> Nouvelle commande
        </button></div>
      </header>

      {message && <p className="ind-notice" role="status">{message}<button type="button" onClick={() => setMessage('')}>×</button></p>}
      <nav className="ind-tabs" aria-label="Étapes des commandes">
        {([
          ['TOUS', 'Tous'],
          ['CREES', 'Bons créés'],
          ['CONFIRMES', 'Bons confirmés'],
          ['LIVRES', 'Livrés'],
          ['PAYES', 'Payés'],
        ] as const).map(([cle, titre]) => (
          <button key={cle} type="button" className={statut === cle ? 'active' : ''}
            aria-current={statut === cle ? 'page' : undefined}
            onClick={() => setStatut(cle)}>
            {titre} ({cle === 'TOUS' ? commandesGms.length : commandesGms.filter(c => etapeCommande(c) === cle).length})
          </button>
        ))}
      </nav>
      <section className="ind-stats">
        <CompactStatCard className="ind-stat"
          icon={<Package size={21} />}
          label="Commandes"
          value={String(resultats.length)}
        />

        <CompactStatCard className="ind-stat"
          icon={<Store size={21} />}
          label="Brioches commandées"
          value={new Intl.NumberFormat('fr-FR').format(
            totalQuantite,
          )}
        />

        <CompactStatCard className="ind-stat"
          icon={<Euro size={21} />}
          label="Montant estimé"
          value={argent(totalMontant)}
        />
      </section>

      <section className="ind-card">
        <div className="ind-toolbar">
          <label className="ind-search">
            <Search size={18} />

            <input
              type="search"
              placeholder="Rechercher une commande, un GMS, un secteur…"
              value={recherche}
              onChange={(event) =>
                setRecherche(event.target.value)
              }
            />
          </label>

          <select
            value={statut}
            onChange={(event) =>
              setStatut(
                event.target.value as StatutFiltre,
              )
            }
            aria-label="Filtrer par statut"
          >
            <option value="TOUS">Toutes les étapes</option><option value="CREES">Bons créés</option><option value="CONFIRMES">Bons confirmés</option><option value="LIVRES">Livrés</option><option value="PAYES">Payés</option>
          </select>
        </div>

        <div className="ind-results">
          <strong>
            {resultats.length} commande
            {resultats.length > 1 ? 's' : ''}
          </strong>

          <span>
            {fournisseursGms.length} fournisseur
            {fournisseursGms.length > 1 ? 's GMS' : ' GMS'}
            dans la base fournisseurs
          </span>
        </div>

        <div className="ind-table-wrap">
          <table className="ind-table">
            <thead>
              <tr>
                <th>N° commande</th>
                <th>GMS</th>
                <th>Campagne</th>
                <th>Date commande</th>
                <th>Date retrait</th>
                <th>Livraisons / destinations</th><th>Secteur</th>
                <th>Quantité</th>
                <th>Prix TTC / brioche</th>
                <th>Total TTC</th>
                <th>Statut</th>
                <th>Action</th>
              </tr>
            </thead>

            <tbody>
              {resultats.map(
                (commande: CommandeArtisan) => (
                  <Fragment key={commande.id}>
                  <tr className={(commande as CommandeGmsSuivi).paye ? 'ind-row-paid' : ''}>
                    <td className="ind-code">
                      {commande.numero || '—'}
                    </td>

                    <td>
                      {cellule(commande,'artisanId',nomGms(commande.artisanId,fournisseursGms),'select')}
                    </td>

                    <td>
                      {cellule(commande,'campagne',commande.campagne)}
                    </td>

                    <td>
                      <span className="ind-date">
                        <CalendarDays size={14} />
                        {cellule(commande,'dateCommande',dateLisible(commande.dateCommande),'date')}
                      </span>
                    </td>

                    <td>
                      {cellule(commande,'dateRetrait',dateLisible(commande.dateRetrait),'date')}
                    </td>

                    <td>
                      <button className="gms-expand-button" type="button" aria-expanded={destinationsOuvertes.includes(commande.id)} aria-label={`${destinationsOuvertes.includes(commande.id) ? 'Masquer' : 'Afficher'} les ${destinationsDe(commande as CommandeGmsSuivi).length} lieux de livraison de ${commande.numero}`} onClick={() => basculerDestinations(commande.id)}>
                        <span className="gms-expand-icon">{destinationsOuvertes.includes(commande.id) ? <Minus size={14}/> : <Plus size={14}/>}</span>
                        <strong>{destinationsDe(commande as CommandeGmsSuivi).length} lieu{destinationsDe(commande as CommandeGmsSuivi).length > 1 ? 'x' : ''} de livraison</strong>
                      </button>
                      <div className="gms-dest-progress">{destinationsDe(commande as CommandeGmsSuivi).filter(d=>d.livre).length} / {destinationsDe(commande as CommandeGmsSuivi).length} livrées</div>
                    </td>
                    <td>{cellule(commande,'secteur',commande.secteur)}</td>

                    <td>
                      {cellule(commande,'quantiteCommandee',new Intl.NumberFormat('fr-FR').format(commande.quantiteCommandee),'number')}
                    </td>

                    <td>
                      {argent(
                        commande.prixUnitaire,
                      )}
                    </td>

                    <td>
                      {cellule(commande,'montant',argent(montantCommande(commande)),'number')}
                    </td>

                    <td>
                      {cellule(commande,'statut',libelleBon(commande),'select')}
                    </td>
                    <td><div className="ind-bdc-actions"><button className="ind-edit" type="button" title="Bon de commande imprimable" aria-label={`Bon de commande ${commande.numero}`} onClick={() => imprimerBonCommande(commande)}><Printer size={17}/></button><button className="ind-edit" type="button" aria-label={`Modifier ${commande.numero}`} onClick={() => ouvrirEdition(commande)}><Pencil size={16} /></button></div></td>
                  </tr>
                  {destinationsOuvertes.includes(commande.id) && destinationsDe(commande as CommandeGmsSuivi).map((destination, index) => (
                    <tr key={`${commande.id}-${destination.id}`} className={`gms-subrow ${(commande as CommandeGmsSuivi).paye ? 'ind-row-paid' : ''}`}>
                      <td className="gms-sub-index">↳ {index + 1}</td>
                      <td colSpan={4} className="gms-sub-label">
                        <strong>{destinationLibelleLigne(destination)}</strong>
                        <span>{destination.type === 'ETABLISSEMENT' ? 'Établissement AEIM' : destination.type === 'MAIRIE' ? 'Mairie' : 'Stand'}</span>
                      </td>
                      <td><span className="gms-sub-destination">{destinationLibelleLigne(destination)}</span></td>
                      <td>—</td>
                      <td className="gms-sub-quantity">{new Intl.NumberFormat('fr-FR').format(destination.quantite)}</td>
                      <td>—</td>
                      <td>—</td>
                      <td><span className={`gms-sub-status ${destination.livre ? 'gms-sub-status--delivered' : ''}`}>{destination.livre ? 'Livré' : 'À livrer'}</span></td>
                      <td><button type="button" className="ind-edit" title={`Modifier la livraison : ${destinationLibelleLigne(destination)}`} aria-label={`Modifier la livraison : ${destinationLibelleLigne(destination)}`} onClick={() => ouvrirEdition(commande)}><Pencil size={16}/></button></td>
                    </tr>
                  ))}
                  </Fragment>
                ),
              )}

              {!resultats.length && (
                <tr>
                  <td
                    className="ind-empty"
                    colSpan={12}
                  >
                    Aucune commande GMS ne correspond aux
                    filtres.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </section>
      {edition && <div className="ind-overlay" onMouseDown={e => { if (e.target === e.currentTarget) setEdition(null) }}>
        <section className="ind-dialog" role="dialog" aria-modal="true" aria-labelledby="ind-dialog-title">
          <header className="ind-dialog-head"><div><span className="ind-eyebrow">ACHAT DE BRIOCHES</span><h2 id="ind-dialog-title">{editionId ? 'Modifier la commande' : 'Nouvelle commande GMS'}</h2></div>
            <button type="button" className="ind-edit" aria-label="Fermer" onClick={() => setEdition(null)}><X size={20} /></button>
          </header>
          <form onSubmit={enregistrer}>
            <div className="ind-form-grid">
              <label className="ind-wide">Fournisseur GMS *
                <select required value={edition.artisanId} onChange={e => choisirFournisseur(e.target.value)}>
                  <option value="">Sélectionner…</option>
                  {fournisseursGms.map(f => <option key={f.id} value={f.id}>{f.nom} ({f.id}){f.statut === 'INACTIF' ? ' — Inactif' : ''}</option>)}
                </select>
              </label>
              {(() => { const fournisseur = fournisseurs.find(f => f.id === edition.artisanId); return fournisseur ? <div className="ind-fournisseur-info ind-wide">
                <strong>{fournisseur.nom}</strong><span>{[fournisseur.adresse, fournisseur.codePostal, fournisseur.ville].filter(Boolean).join(' · ') || 'Adresse non renseignée'}</span>
                <span>{[fournisseur.responsable, fournisseur.telephone, fournisseur.email].filter(Boolean).join(' · ') || 'Contact non renseigné'}</span>
              </div> : null })()}
              <label>Campagne *<input required value={edition.campagne} onChange={e => modifier('campagne', e.target.value)} /></label>
              <label>N° de commande<input readOnly value={editionId ? edition.numero : numeroCommandeSuivant(commandesArtisans, edition.campagne)} /></label>
              <label>Date de commande *<input type="date" required value={edition.dateCommande} onChange={e => modifier('dateCommande', e.target.value)} /></label>
              <label>Date de retrait prévue<input type="date" value={edition.dateRetrait} onChange={e => modifier('dateRetrait', e.target.value)} /></label>
              <label>Quantité de brioches *<input type="number" required min="1" step="1" value={edition.quantiteCommandee || ''} onChange={e => modifier('quantiteCommandee', Number(e.target.value))} /></label>
              <label>Montant total TTC (€) *<input type="number" required min="0" step="0.01" value={totalTtc} onChange={e => setTotalTtc(e.target.value)} /></label>
              <section className="gms-destinations ind-wide">
                <div className="gms-dest-head"><div><strong>Répartition des livraisons</strong><p>Plusieurs établissements, mairies et stands sur un seul bon de commande.</p></div><button type="button" className="ind-cancel" onClick={()=>setEdition(p=>p?{...p,destinations:[...destinationsDe(p),nouvelleDestination()]}:null)}><Plus size={16}/> Ajouter un lieu</button></div>
                {destinationsDe(edition).map((d,i)=><div className="gms-dest-row" key={d.id}>
                  <div className="gms-dest-row-head"><strong>Livraison {i+1}</strong><button type="button" className="ind-edit" title="Supprimer cette destination" onClick={()=>setEdition(p=>p?{...p,destinations:destinationsDe(p).filter(x=>x.id!==d.id)}:null)}><X size={16}/></button></div>
                  <label>Type<select value={d.type} onChange={e=>changerDestination(d.id,{type:e.target.value as DestinationGms['type'],referenceId:'',nom:'',adresse:'',livre:false})}><option value="ETABLISSEMENT">Établissement AEIM</option><option value="MAIRIE">Mairie</option><option value="STAND">Stand</option></select></label>
                  {d.type === 'STAND' ? <><label>Stand existant<select value={d.referenceId} onChange={e=>{
                    const stand=standsDisponibles.find(s=>s.id===e.target.value)
                    changerDestination(d.id,{referenceId:stand?.id||'',nom:stand?.nom||'',adresse:[stand?.lieu,stand?.adresse].filter(Boolean).join(' · '),livre:false})
                  }}><option value="">Sélectionner un stand de la campagne…</option>{standsDisponibles.map(stand=><option key={stand.id} value={stand.id}>{stand.date} · {stand.nom}{stand.lieu?` · ${stand.lieu}`:''}</option>)}</select></label><label>Adresse / lieu<input value={d.adresse} readOnly title="À modifier dans la fiche du stand" /></label></> : <label>Destinataire<select value={d.referenceId} onChange={e=>changerDestination(d.id,{referenceId:e.target.value})}><option value="">Sélectionner…</option>{(d.type==='MAIRIE'?mairiesDisponibles.map(m=>({id:m.id,nom:m.nomAffiche||m.commune})):etablissementsDisponibles.map(e=>({id:e.id,nom:e.nom}))).map(o=><option value={o.id} key={o.id}>{o.nom}</option>)}</select></label>}
                  <label>Quantité<input type="number" min="1" step="1" value={d.quantite || ''} onChange={e=>changerDestination(d.id,{quantite:Number(e.target.value)})}/></label>
                  <label>Livraison<select value={d.livre?'LIVRE':'ATTENTE'} disabled={!estConfirmee(edition)} onChange={e=>changerDestination(d.id,{livre:e.target.value==='LIVRE'})}><option value="ATTENTE">À livrer</option><option value="LIVRE">Livré</option></select></label>
                </div>)}
                <div className="gms-dest-total"><span>Total réparti : <strong>{destinationsDe(edition).reduce((n,d)=>n+d.quantite,0)} / {edition.quantiteCommandee} brioches</strong></span><span>{destinationsDe(edition).filter(d=>d.livre).length} livraison(s) terminée(s)</span></div>
                <p className="gms-dest-help">Le stock AEIM est alimenté uniquement pour les établissements marqués « Livré ». Les mairies et stands restent suivis sans stock d'établissement fictif.</p>
              </section>
              <label>Secteur<input value={edition.secteur} onChange={e => modifier('secteur', e.target.value)} /></label>
              <label>Statut<select disabled={Boolean(editionId && paiementRapprocheVerrouille(editionId))} title={editionId && paiementRapprocheVerrouille(editionId) ? MESSAGE_PAIEMENT_VERROUILLE : undefined} value={(edition as CommandeGmsSuivi).paye ? 'PAYE' : livraisonsTerminees(edition) ? 'LIVRE' : estConfirmee(edition) ? 'CONFIRMEE' : 'BROUILLON'} onChange={e => { const v = e.target.value; setEdition(p => p ? {...p, statut:(v === 'BROUILLON' ? 'BROUILLON' : 'CONFIRMEE') as StatutCommandeArtisan, livre:livraisonsTerminees(p), paye:v === 'PAYE'} : null) }}><option value="BROUILLON">Bon créé</option><option value="CONFIRMEE">Bon confirmé</option><option value="LIVRE">Livré</option><option value="PAYE">Payé</option></select></label>

              <label className="ind-wide">Remarques<textarea rows={3} value={edition.remarque} onChange={e => modifier('remarque', e.target.value)} /></label>
              <div className="ind-form-total ind-wide">Prix TTC calculé par brioche <strong>{edition.quantiteCommandee > 0 && totalTtc.trim() !== '' && Number.isFinite(Number(totalTtc.replace(',', '.'))) ? argent(Number(totalTtc.replace(',', '.')) / edition.quantiteCommandee) : '—'}</strong></div>
              {erreur && <p className="ind-form-error ind-wide" role="alert">{erreur}</p>}
            </div>
            <footer className="ind-dialog-footer"><button type="button" className="ind-cancel" onClick={() => setEdition(null)}>Annuler</button><button type="submit" className="ind-primary"><Check size={17}/> Enregistrer la commande</button></footer>
          </form>
        </section>
      </div>}
    </main>
  )
}

import CompactStatCard from '../components/ui/CompactStatCard'
import { useObData } from '../contexts/ObDataContext'
import { useMemo, useState, type FormEvent } from 'react'
import {
  CalendarDays, Download, Printer,
  Euro,
  Package,
  Search,
  Store, Plus, X, Check, Pencil,
} from 'lucide-react'

import { useArtisans } from '../contexts/ArtisansContext'
import { useEtablissements } from '../contexts/EtablissementsContext'
import { synchroniserReceptionIndustrielle } from '../lib/commandeIndustrielleStock'
import type {
  CommandeArtisan,
  Fournisseur,
  StatutCommandeArtisan,
} from '../types/artisans'
import {
  argent,
  categoriesFournisseur,
  dateLisible,
  montantCommande,
  jourLocal,
  numeroCommandeSuivant,
} from '../types/artisans'

import { paiementRapprocheVerrouille, MESSAGE_PAIEMENT_VERROUILLE } from '../lib/paiementCommandeLock'

import './CommandesIndustriels.css'

type StatutFiltre = 'TOUS' | 'CREES' | 'CONFIRMES' | 'LIVRES' | 'PAYES'
type CommandeIndustrie = CommandeArtisan & { etablissementId?: string; livre?: boolean; paye?: boolean }
const estConfirmee = (c: CommandeArtisan) => ['CONFIRMEE','RETRAIT_PREVU','TERMINEE'].includes(c.statut)
const libelleBon = (c: CommandeArtisan) => {
  const suivi = c as CommandeIndustrie
  if (suivi.paye) return 'Payé'
  if (suivi.livre) return 'Livré'
  return estConfirmee(c) ? 'Bon de commande confirmé' : 'Bon de commande créé'
}
const etapeCommande = (c: CommandeArtisan): Exclude<StatutFiltre, 'TOUS'> => {
  const suivi = c as CommandeIndustrie
  if (!estConfirmee(c)) return 'CREES'
  if (suivi.paye) return 'PAYES'
  if (suivi.livre) return 'LIVRES'
  return 'CONFIRMES'
}



function nomIndustriel(
  fournisseurId: string,
  fournisseurs: Array<{ id: string; nom: string }>,
) {
  return (
    fournisseurs.find((item) => item.id === fournisseurId)?.nom ||
    fournisseurId ||
    '—'
  )
}

function estIndustriel(fournisseur: Fournisseur) {
  return categoriesFournisseur(fournisseur).includes('INDUSTRIEL')
}

export default function CommandesIndustriels() {
  const { commandesArtisans, setCommandesArtisans, fournisseurs } = useArtisans()
  const { selectedCampagne, activeCampagne } = useObData()
  const campagneSelectionnee = selectedCampagne ?? activeCampagne
  const anneeCampagne = String(campagneSelectionnee?.annee ?? campagneSelectionnee?.id.match(/(?:19|20)\d{2}/)?.[0] ?? '')

  const { etablissements } = useEtablissements()
  const [message, setMessage] = useState('')
  const etablissementsDisponibles = useMemo(() => etablissements.filter(e => e.statut === 'ACTIF').sort((a,b) => a.nom.localeCompare(b.nom,'fr')), [etablissements])
  const [editionCellule, setEditionCellule] = useState<{ id: string; cle: string } | null>(null)
  const [valeurCellule, setValeurCellule] = useState('')
  const [edition, setEdition] = useState<CommandeIndustrie | null>(null)
  const [editionId, setEditionId] = useState<string | null>(null)
  const [erreur, setErreur] = useState('')
  const [totalTtc, setTotalTtc] = useState('')

  function ouvrirCreation() {
    const premier = fournisseurs.filter(estIndustriel).find(f => f.statut !== 'INACTIF')
    const campagneActuelle = anneeCampagne || String(new Date().getFullYear())
    setEdition({
      id: `commande-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
      numero: numeroCommandeSuivant(commandesArtisans, campagneActuelle),
      artisanId: premier?.id ?? '', campagne: campagneActuelle, dateCommande: jourLocal(), dateRetrait: '',
      repartitionJours: '', secteur: premier?.secteur ?? '', responsableSecteur: premier?.responsableSecteur ?? '',
      adresseResponsable: '', telephoneResponsable: '', personneRetrait: '', quantiteCommandee: 0,
      quantiteFabriquee: null, prixUnitaire: premier?.tarif2026 ?? premier?.tarif2025 ?? 0,
      statut: 'BROUILLON', etablissementId: '', livre: false, paye: false, etiquettesConsignes: '', bdcEnvoyeLe: '', etiquettesEnvoyeesLe: '',
      fondsEstimes: null, fondsRecus: null, factureNumero: '', factureRecueLe: '', factureScanneeLe: '',
      factureTransmiseLe: '', remarque: '', remarqueFacture: '',
    })
    setEditionId(null)
    setTotalTtc('')
    setErreur('')
  }

  function ouvrirEdition(commande: CommandeArtisan) {
    setEdition({ ...commande })
    setTotalTtc(String(Number((commande.quantiteCommandee * commande.prixUnitaire).toFixed(2))))
    setEditionId(commande.id)
    setErreur('')
  }

  function modifier<K extends keyof CommandeArtisan>(cle: K, valeur: CommandeArtisan[K]) {
    setEdition(e => e ? { ...e, [cle]: valeur } : null)
  }

  function choisirFournisseur(id: string) {
    const f = fournisseurs.find(item => item.id === id)
    setEdition(e => e ? {
      ...e, artisanId: id,
      secteur: f?.secteur ?? e.secteur,
      responsableSecteur: f?.responsableSecteur ?? e.responsableSecteur,
      // Le prix total TTC saisi reste inchangé lors du choix d'un fournisseur.
      prixUnitaire: e.prixUnitaire,
    } : null)
  }

  function enregistrer(e: FormEvent<HTMLFormElement>) {
    e.preventDefault()
    if (!edition) return
    if (editionId && paiementRapprocheVerrouille(editionId)) {
      const origine = commandesArtisans.find(c => c.id === editionId)
      if (!origine || !edition.paye || edition.statut !== origine.statut || edition.artisanId !== origine.artisanId || edition.quantiteCommandee !== origine.quantiteCommandee || Math.abs(Number(totalTtc.replace(',', '.')) - montantCommande(origine)) > .01) {
        setErreur(MESSAGE_PAIEMENT_VERROUILLE); return
      }
    }
    if (!fournisseurs.filter(estIndustriel).some(f => f.id === edition.artisanId)) {
      setErreur('Sélectionne un fournisseur industriel existant.')
      return
    }
    const montantTtc = Number(totalTtc.replace(',', '.'))
    if (!edition.campagne.trim() || !edition.dateCommande || !Number.isInteger(edition.quantiteCommandee) || edition.quantiteCommandee <= 0 || totalTtc.trim() === '' || !Number.isFinite(montantTtc) || montantTtc < 0) {
      setErreur('Renseigne une campagne, une date, une quantité entière positive et un montant TTC valide.')
      return
    }
    // Compatibilité : la base existante stocke un prix unitaire.
    // Ne pas arrondir à 2 décimales ici, sinon quantité × prix perdrait des centimes.
    if (edition.paye && (!edition.livre || !estConfirmee(edition))) { setErreur('Un bon doit être confirmé et livré avant d’être payé.'); return }
    const commande: CommandeIndustrie = { ...edition, livre:estConfirmee(edition) ? edition.livre : false, paye:estConfirmee(edition) ? edition.paye : false, prixUnitaire: montantTtc / edition.quantiteCommandee, campagne: edition.campagne.trim(), numero: editionId ? edition.numero : numeroCommandeSuivant(commandesArtisans, edition.campagne.trim()) }
    const sync = synchroniserReceptionIndustrielle(commande, commandesArtisans.find(c => c.id === editionId), etablissements)
    if (!sync.ok) { setErreur(sync.erreur ?? 'Erreur de stock'); return }
    setCommandesArtisans(anciennes => editionId
      ? anciennes.map(c => c.id === editionId ? commande : c)
      : [...anciennes, commande])
    setEdition(null)
    setEditionId(null)
    setErreur('')
  }


  function modifierCellule(c: CommandeArtisan, cle: string, val: string) {
    setEditionCellule(null)
    if (paiementRapprocheVerrouille(c.id)) { setMessage(MESSAGE_PAIEMENT_VERROUILLE); return }
    const suivant: CommandeIndustrie = { ...(c as CommandeIndustrie) }
    if (cle === 'quantiteCommandee') {
      const q = Number(val); if (!Number.isInteger(q) || q <= 0) return setMessage('Quantité invalide.')
      suivant.quantiteCommandee = q
    } else if (cle === 'montant') {
      const m = Number(val.replace(',', '.')); if (!Number.isFinite(m) || m < 0) return setMessage('Montant TTC invalide.')
      suivant.prixUnitaire = m / suivant.quantiteCommandee
    } else if (cle === 'statut') {
      suivant.statut = val === 'BROUILLON' ? 'BROUILLON' : 'CONFIRMEE'
      suivant.livre = val === 'LIVRE' || val === 'PAYE'
      suivant.paye = val === 'PAYE'
    } else if (cle === 'artisanId') {
      if (!fournisseurs.some(f => f.id === val && estIndustriel(f))) return setMessage('Fournisseur invalide.')
      suivant.artisanId = val
    } else if (cle === 'etablissementId') suivant.etablissementId = val
    else if (cle === 'dateCommande' || cle === 'dateRetrait' || cle === 'campagne' || cle === 'secteur') Object.assign(suivant, { [cle]: val })
    else if (cle !== 'livre' && cle !== 'paye') return
    if (cle === 'livre' || cle === 'paye') {
      if (!estConfirmee(c)) return setMessage('Confirme d’abord le bon de commande.')
      if (cle === 'paye' && val === 'true' && !suivant.livre) return setMessage('Marque d’abord le bon comme livré.')
      suivant[cle] = val === 'true'
    }
    if ((c as CommandeIndustrie).paye && (cle === 'quantiteCommandee' || cle === 'montant' || cle === 'etablissementId' || cle === 'artisanId')) return setMessage('Une commande payée doit d’abord être repassée en non payée avant ces modifications.')
    if (estConfirmee(c) && cle === 'artisanId') return setMessage('Déconfirme le bon avant de changer de fournisseur.')
    const sync = synchroniserReceptionIndustrielle(suivant, c, etablissements)
    if (!sync.ok) { setMessage(sync.erreur ?? 'Mise à jour refusée.'); return }
    setCommandesArtisans(prev => prev.map(x => x.id === c.id ? suivant : x))
    setMessage('Modification enregistrée automatiquement.')
  }

  function cellule(c: CommandeArtisan, cle: string, affichage: string, type: 'text'|'number'|'date'|'select' = 'text') {
    if (cle === 'statut' && paiementRapprocheVerrouille(c.id)) return <span className="ind-status-locked" title="Paiement rapproché et validé dans Factures & Paiements">🔒 Payé</span>
    const active = editionCellule?.id === c.id && editionCellule.cle === cle
    const options = cle === 'livre' ? [['false','À livrer'],['true','Livré']] : cle === 'paye' ? [['false','À payer'],['true','Payé']] : cle === 'statut' ? [['BROUILLON','Bon créé'],['CONFIRMEE','Bon confirmé'],['LIVRE','Livré'],['PAYE','Payé']]
      : cle === 'artisanId' ? fournisseurs.filter(estIndustriel).map(f => [f.id, f.nom])
      : cle === 'etablissementId' ? [['','À affecter'],...etablissementsDisponibles.map(e => [e.id, e.nom + (e.peutRecevoirStock ? '' : ' (stock non autorisé)')])] : []
    if (active) return type === 'select'
      ? <select autoFocus className="ind-inline-input" value={valeurCellule} onChange={e => modifierCellule(c,cle,e.target.value)} onBlur={() => setEditionCellule(null)}>{options.map(([v,l]) => <option value={v} key={v}>{l}</option>)}</select>
      : <input autoFocus className="ind-inline-input" type={type} step={type === 'number' ? 'any' : undefined} value={valeurCellule} onChange={e => setValeurCellule(e.target.value)} onBlur={() => modifierCellule(c,cle,valeurCellule)} onKeyDown={e => { if (e.key === 'Enter') { e.preventDefault(); modifierCellule(c,cle,valeurCellule) } if(e.key === 'Escape')setEditionCellule(null) }} />
    return <button className="ind-inline-button" type="button" title="Cliquer pour modifier" onClick={() => {
      setEditionCellule({ id: c.id, cle })
      setValeurCellule(cle === 'statut' ? ((c as CommandeIndustrie).paye ? 'PAYE' : (c as CommandeIndustrie).livre ? 'LIVRE' : estConfirmee(c) ? 'CONFIRMEE' : 'BROUILLON') : cle === 'montant' ? String(montantCommande(c)) : cle === 'etablissementId' ? (c as CommandeIndustrie).etablissementId ?? '' : String((c as unknown as Record<string, unknown>)[cle] ?? ''))
    }}>{affichage || '—'} <Pencil size={12}/></button>
  }

  async function exporterExcel() {
    try {
      const ExcelJS = (await import('exceljs')).default
      const wb = new ExcelJS.Workbook()
      const ws = wb.addWorksheet('Commandes industriels')
      ws.addRow(['Bon','Fournisseur','Campagne','Établissement','Date commande','Date retrait','Quantité','Total TTC','Prix / brioche','Statut','Secteur'])
      resultats.forEach(c => ws.addRow([c.numero,nomIndustriel(c.artisanId,fournisseursIndustriels),c.campagne,etablissements.find(e => e.id === (c as CommandeIndustrie).etablissementId)?.nom ?? '',c.dateCommande,c.dateRetrait,c.quantiteCommandee,montantCommande(c),c.prixUnitaire,libelleBon(c),c.secteur]))
      ws.getRow(1).font = { bold: true, color: { argb:'FFFFFFFF' } }
      ws.getRow(1).fill = { type:'pattern',pattern:'solid',fgColor:{argb:'FF173B6D'} }
      ws.columns.forEach(col => { col.width = 24 })
      ws.getColumn(8).numFmt = '#,##0.00 "€"'
      ws.getColumn(9).numFmt = '#,##0.0000 "€"'
      ws.autoFilter = { from:'A1', to:`K${resultats.length + 1}` }
      const bytes = await wb.xlsx.writeBuffer()
      const url=URL.createObjectURL(new Blob([bytes],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}))
      const link=document.createElement('a');link.href=url;link.download='commandes-industriels.xlsx';link.click()
      window.setTimeout(()=>URL.revokeObjectURL(url),1000)
    } catch { setMessage('Export Excel indisponible : vérifier exceljs.') }
  }

  function imprimerBonCommande(c: CommandeArtisan) {
    const fournisseur = fournisseurs.find(f => f.id === c.artisanId)
    const etab = etablissements.find(e => e.id === (c as CommandeIndustrie).etablissementId)
    const siege = etablissements.find(e => e.code?.toUpperCase() === 'SIEGE' || e.nom.trim().toUpperCase() === 'SIEGE')
    const enc = (v: unknown) => String(v ?? '').replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch] ?? ch))
    const champ = (v: unknown) => enc(v || 'Non renseigné')
    const adresse = (f?: { adresse?: string; codePostal?: string; ville?: string }) =>
      [f?.adresse, [f?.codePostal, f?.ville].filter(Boolean).join(' ')].filter(Boolean).map(enc).join('<br>') || 'Adresse non renseignée'
    const html = `<!doctype html><html lang="fr"><head><meta charset="utf-8"><title>Bon de commande ${enc(c.numero)}</title>
      <style>
        @page{size:A4 portrait;margin:16mm}
        *{box-sizing:border-box}body{font:12px/1.55 Arial,Helvetica,sans-serif;color:#1c3556;margin:0}
        header{display:flex;justify-content:space-between;align-items:flex-start;border-bottom:3px solid #e57a21;padding-bottom:22px}
        .brand{font-size:23px;font-weight:800;color:#123b72}.subtitle{font-size:12px;color:#637b96}
        .ref{text-align:right}.ref strong{font-size:20px;color:#123b72}
        h1{font-size:21px;text-transform:uppercase;letter-spacing:1px;color:#123b72;margin:26px 0 8px}
        .muted{color:#6d8094}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin:24px 0}
        .card{border:1px solid #dce5ef;border-radius:8px;padding:15px;min-height:130px}
        .card h2{font-size:11px;letter-spacing:.5px;text-transform:uppercase;color:#d16d1a;margin:0 0 12px}
        table{border-collapse:collapse;width:100%;margin-top:20px}th{background:#123b72;color:white;text-align:left;font-size:11px;padding:11px}
        td{border-bottom:1px solid #dce5ef;padding:13px 11px}td.num,th.num{text-align:right}
        .total{display:flex;justify-content:flex-end;gap:25px;padding:17px 10px;background:#f1f5fa;font-size:16px;font-weight:800;color:#123b72}
        .notes{margin:24px 0;min-height:36px;white-space:pre-wrap}
        .signatures{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin-top:32px}
        .sign{border-top:1px solid #bccbda;padding:12px 0;min-height:85px;color:#64768a}
        footer{position:fixed;bottom:0;left:0;right:0;border-top:1px solid #dce5ef;padding-top:7px;font-size:10px;color:#798b9d}
        @media screen {.printbar{position:fixed;right:15px;top:15px;background:#123b72;color:white;border:0;border-radius:8px;padding:10px 18px;cursor:pointer}body{padding:32px;max-width:850px;margin:auto;background:white}}
        @media print {.printbar{display:none}}
      </style></head><body>
      <button class="printbar" onclick="window.print()">Imprimer / Enregistrer en PDF</button>
      <header><div><div class="brand">AEIM · Opération Brioches</div><div class="subtitle">Commande de brioches — Campagne ${enc(c.campagne)}</div></div>
      <div class="ref"><div>BON DE COMMANDE</div><strong>${enc(c.numero)}</strong><div>Émis le ${enc(dateLisible(c.dateCommande))}</div></div></header>
      <h1>Bon de commande</h1><div class="muted">Référence à rappeler sur toute correspondance et facture : ${enc(c.numero)}</div>
      <div class="grid"><section class="card"><h2>Fournisseur</h2><strong>${champ(fournisseur?.nom)}</strong><div>${adresse(fournisseur)}</div>
      <div>Tél. : ${champ(fournisseur?.telephone)}</div><div>E-mail : ${champ(fournisseur?.email)}</div>${fournisseur?.siret ? `<div>SIRET : ${enc(fournisseur.siret)}</div>` : ''}</section>
      <section class="card"><h2>Donneur d’ordre / facturation</h2><strong>AEIM — Siège</strong><div>${siege ? adresse(siege) : "6 allée de Saint-Cloud<br>54600 Villers-lès-Nancy"}</div>
      ${siege?.telephone ? `<div>Tél. : ${enc(siege.telephone)}</div>` : ""}${siege?.email ? `<div>E-mail : ${enc(siege.email)}</div>` : ""}</section></div>
      <section class="card" style="min-height:100px;margin-top:12px"><h2>Lieu de livraison des brioches</h2><strong>${champ(etab?.nom)}</strong><div>${adresse(etab)}</div>
      ${etab?.telephone ? `<div>Tél. : ${enc(etab.telephone)}</div>` : ""}${etab?.email ? `<div>E-mail : ${enc(etab.email)}</div>` : ""}</section>
      <div><strong>Date de retrait / livraison prévue :</strong> ${c.dateRetrait ? enc(dateLisible(c.dateRetrait)) : 'À convenir'}</div>
      <div><strong>Secteur :</strong> ${champ(c.secteur)}</div>
      <table><thead><tr><th>Désignation</th><th class="num">Quantité</th><th class="num">Prix unitaire TTC</th><th class="num">Montant TTC</th></tr></thead>
      <tbody><tr><td>Brioches — Opération Brioches ${enc(c.campagne)}</td><td class="num">${enc(new Intl.NumberFormat('fr-FR').format(c.quantiteCommandee))}</td>
      <td class="num">${enc(argent(c.prixUnitaire))}</td><td class="num">${enc(argent(montantCommande(c)))}</td></tr></tbody></table>
      <div class="total"><span>Total TTC</span><span>${enc(argent(montantCommande(c)))}</span></div>
      <div class="notes"><strong>Observations / consignes :</strong> ${champ(c.remarque)}</div>
      <div class="signatures"><div class="sign">Pour l'AEIM — Nom, date et signature</div><div class="sign">Pour le fournisseur — Accusé de réception / signature</div></div>
      <footer>Document généré depuis OB2026 · Vérifier les coordonnées et modalités avant transmission.</footer>
      </body></html>`
    const page = window.open('', '_blank')
    if (!page) { setMessage('Autorise les fenêtres pop-up pour ouvrir le bon de commande.'); return }
    page.document.open(); page.document.write(html); page.document.close(); page.focus()
  }

  const [recherche, setRecherche] = useState('')
  const [statut, setStatut] = useState<StatutFiltre>('TOUS')

  const fournisseursIndustriels = useMemo(
    () => fournisseurs.filter(estIndustriel),
    [fournisseurs],
  )

  const idsIndustriels = useMemo(
    () => new Set(fournisseursIndustriels.map((item) => item.id)),
    [fournisseursIndustriels],
  )

  const commandesIndustriels = useMemo(
    () =>
      commandesArtisans.filter((commande) =>
        idsIndustriels.has(commande.artisanId) &&
        String(commande.campagne ?? '').match(/(?:19|20)\d{2}/)?.[0] === anneeCampagne,
      ),
    [commandesArtisans, idsIndustriels, anneeCampagne],
  )

  const resultats = useMemo(() => {
    const motif = recherche.trim().toLocaleLowerCase('fr')

    return commandesIndustriels.filter((commande) => {
      const industriel = nomIndustriel(
        commande.artisanId,
        fournisseursIndustriels,
      )

      const correspondRecherche =
        !motif ||
        [
          commande.numero,
          industriel,
          commande.secteur,
          commande.responsableSecteur,
          commande.personneRetrait,
          commande.campagne,
        ]
          .join(' ')
          .toLocaleLowerCase('fr')
          .includes(motif)

      const correspondCampagne = true

      const correspondStatut = statut === 'TOUS' || etapeCommande(commande) === statut

      return (
        correspondRecherche &&
        correspondCampagne &&
        correspondStatut
      )
    })
  }, [
    commandesIndustriels,
    fournisseursIndustriels,
    recherche,
    statut,
  ])

  const totalQuantite = useMemo(
    () =>
      resultats.reduce(
        (total, commande) =>
          total + commande.quantiteCommandee,
        0,
      ),
    [resultats],
  )

  const totalMontant = useMemo(
    () =>
      resultats.reduce(
        (total, commande) =>
          total + montantCommande(commande),
        0,
      ),
    [resultats],
  )

  return (
    <main className="ind-page">
      <header className="ind-header">
        <div>
          <span className="ind-eyebrow">
            COMMANDES ACHATS
          </span>

          <h1>Industriels</h1>

          <p>
            Suivi des commandes de brioches auprès des
            fournisseurs industriels.
          </p>
        </div>
        <div className="ind-header-buttons"><button type="button" className="ind-cancel" onClick={exporterExcel}><Download size={17}/> Excel</button><button type="button" className="ind-primary" onClick={ouvrirCreation} disabled={!fournisseursIndustriels.some(f => f.statut !== 'INACTIF')}>
          <Plus size={18} /> Nouvelle commande
        </button></div>
      </header>

      {message && <p className="ind-notice" role="status">{message}<button type="button" onClick={() => setMessage('')}>×</button></p>}
      <nav className="ind-tabs" aria-label="Étapes des commandes">
        {([
          ['TOUS', 'Tous'],
          ['CREES', 'Bons créés'],
          ['CONFIRMES', 'Bons confirmés'],
          ['LIVRES', 'Livrés'],
          ['PAYES', 'Payés'],
        ] as const).map(([cle, titre]) => (
          <button key={cle} type="button" className={statut === cle ? 'active' : ''}
            aria-current={statut === cle ? 'page' : undefined}
            onClick={() => setStatut(cle)}>
            {titre} ({cle === 'TOUS' ? commandesIndustriels.length : commandesIndustriels.filter(c => etapeCommande(c) === cle).length})
          </button>
        ))}
      </nav>
      <section className="ind-stats">
        <CompactStatCard className="ind-stat"
          icon={<Package size={21} />}
          label="Commandes"
          value={String(resultats.length)}
        />

        <CompactStatCard className="ind-stat"
          icon={<Store size={21} />}
          label="Brioches commandées"
          value={new Intl.NumberFormat('fr-FR').format(
            totalQuantite,
          )}
        />

        <CompactStatCard className="ind-stat"
          icon={<Euro size={21} />}
          label="Montant estimé"
          value={argent(totalMontant)}
        />
      </section>

      <section className="ind-card">
        <div className="ind-toolbar">
          <label className="ind-search">
            <Search size={18} />

            <input
              type="search"
              placeholder="Rechercher une commande, un industriel, un secteur…"
              value={recherche}
              onChange={(event) =>
                setRecherche(event.target.value)
              }
            />
          </label>

          <select
            value={statut}
            onChange={(event) =>
              setStatut(
                event.target.value as StatutFiltre,
              )
            }
            aria-label="Filtrer par statut"
          >
            <option value="TOUS">Toutes les étapes</option><option value="CREES">Bons créés</option><option value="CONFIRMES">Bons confirmés</option><option value="LIVRES">Livrés</option><option value="PAYES">Payés</option>
          </select>
        </div>

        <div className="ind-results">
          <strong>
            {resultats.length} commande
            {resultats.length > 1 ? 's' : ''}
          </strong>

          <span>
            {fournisseursIndustriels.length} fournisseur
            {fournisseursIndustriels.length > 1 ? 's industriels' : ' industriel'}
            dans la base fournisseurs
          </span>
        </div>

        <div className="ind-table-wrap">
          <table className="ind-table">
            <thead>
              <tr>
                <th>N° commande</th>
                <th>Industriel</th>
                <th>Campagne</th>
                <th>Date commande</th>
                <th>Date retrait</th>
                <th>Lieu de livraison</th><th>Secteur</th>
                <th>Quantité</th>
                <th>Prix TTC / brioche</th>
                <th>Total TTC</th>
                <th>Statut</th>
                <th>Action</th>
              </tr>
            </thead>

            <tbody>
              {resultats.map(
                (commande: CommandeArtisan) => (
                  <tr key={commande.id} className={(commande as CommandeIndustrie).paye ? 'ind-row-paid' : ''}>
                    <td className="ind-code">
                      {commande.numero || '—'}
                    </td>

                    <td>
                      {cellule(commande,'artisanId',nomIndustriel(commande.artisanId,fournisseursIndustriels),'select')}
                    </td>

                    <td>
                      {cellule(commande,'campagne',commande.campagne)}
                    </td>

                    <td>
                      <span className="ind-date">
                        <CalendarDays size={14} />
                        {cellule(commande,'dateCommande',dateLisible(commande.dateCommande),'date')}
                      </span>
                    </td>

                    <td>
                      {cellule(commande,'dateRetrait',dateLisible(commande.dateRetrait),'date')}
                    </td>

                    <td>{cellule(commande,'etablissementId',etablissements.find(e => e.id === (commande as CommandeIndustrie).etablissementId)?.nom ?? 'À affecter','select')}</td>
                    <td>{cellule(commande,'secteur',commande.secteur)}</td>

                    <td>
                      {cellule(commande,'quantiteCommandee',new Intl.NumberFormat('fr-FR').format(commande.quantiteCommandee),'number')}
                    </td>

                    <td>
                      {argent(
                        commande.prixUnitaire,
                      )}
                    </td>

                    <td>
                      {cellule(commande,'montant',argent(montantCommande(commande)),'number')}
                    </td>

                    <td>
                      {cellule(commande,'statut',libelleBon(commande),'select')}
                    </td>
                    <td><div className="ind-bdc-actions"><button className="ind-edit" type="button" title="Bon de commande imprimable" aria-label={`Bon de commande ${commande.numero}`} onClick={() => imprimerBonCommande(commande)}><Printer size={17}/></button><button className="ind-edit" type="button" aria-label={`Modifier ${commande.numero}`} onClick={() => ouvrirEdition(commande)}><Pencil size={16} /></button></div></td>
                  </tr>
                ),
              )}

              {!resultats.length && (
                <tr>
                  <td
                    className="ind-empty"
                    colSpan={12}
                  >
                    Aucune commande industrielle ne correspond aux
                    filtres.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </section>
      {edition && <div className="ind-overlay" onMouseDown={e => { if (e.target === e.currentTarget) setEdition(null) }}>
        <section className="ind-dialog" role="dialog" aria-modal="true" aria-labelledby="ind-dialog-title">
          <header className="ind-dialog-head"><div><span className="ind-eyebrow">ACHAT DE BRIOCHES</span><h2 id="ind-dialog-title">{editionId ? 'Modifier la commande' : 'Nouvelle commande industrielle'}</h2></div>
            <button type="button" className="ind-edit" aria-label="Fermer" onClick={() => setEdition(null)}><X size={20} /></button>
          </header>
          <form onSubmit={enregistrer}>
            <div className="ind-form-grid">
              <label className="ind-wide">Fournisseur industriel *
                <select required value={edition.artisanId} onChange={e => choisirFournisseur(e.target.value)}>
                  <option value="">Sélectionner…</option>
                  {fournisseursIndustriels.map(f => <option key={f.id} value={f.id}>{f.nom} ({f.id}){f.statut === 'INACTIF' ? ' — Inactif' : ''}</option>)}
                </select>
              </label>
              {(() => { const fournisseur = fournisseurs.find(f => f.id === edition.artisanId); return fournisseur ? <div className="ind-fournisseur-info ind-wide">
                <strong>{fournisseur.nom}</strong><span>{[fournisseur.adresse, fournisseur.codePostal, fournisseur.ville].filter(Boolean).join(' · ') || 'Adresse non renseignée'}</span>
                <span>{[fournisseur.responsable, fournisseur.telephone, fournisseur.email].filter(Boolean).join(' · ') || 'Contact non renseigné'}</span>
              </div> : null })()}
              <label>Campagne *<input required value={edition.campagne} onChange={e => modifier('campagne', e.target.value)} /></label>
              <label>N° de commande<input readOnly value={editionId ? edition.numero : numeroCommandeSuivant(commandesArtisans, edition.campagne)} /></label>
              <label>Date de commande *<input type="date" required value={edition.dateCommande} onChange={e => modifier('dateCommande', e.target.value)} /></label>
              <label>Date de retrait prévue<input type="date" value={edition.dateRetrait} onChange={e => modifier('dateRetrait', e.target.value)} /></label>
              <label>Quantité de brioches *<input type="number" required min="1" step="1" value={edition.quantiteCommandee || ''} onChange={e => modifier('quantiteCommandee', Number(e.target.value))} /></label>
              <label>Montant total TTC (€) *<input type="number" required min="0" step="0.01" value={totalTtc} onChange={e => setTotalTtc(e.target.value)} /></label>
              <label>Lieu de livraison<select value={(edition as CommandeIndustrie).etablissementId ?? ''} onChange={e => setEdition(prev => prev ? {...prev,etablissementId:e.target.value} : null)}><option value="">À affecter</option>{etablissementsDisponibles.map(e => <option value={e.id} key={e.id}>{e.nom}{e.peutRecevoirStock ? '' : ' — stock non autorisé'}</option>)}</select></label>
              {!etablissementsDisponibles.length && <p className="ind-form-error ind-wide">Aucun établissement actif. Crée-en un dans Administration → Établissements.</p>}
              <label>Secteur<input value={edition.secteur} onChange={e => modifier('secteur', e.target.value)} /></label>
              <label>Statut<select disabled={Boolean(editionId && paiementRapprocheVerrouille(editionId))} title={editionId && paiementRapprocheVerrouille(editionId) ? MESSAGE_PAIEMENT_VERROUILLE : undefined} value={(edition as CommandeIndustrie).paye ? 'PAYE' : (edition as CommandeIndustrie).livre ? 'LIVRE' : estConfirmee(edition) ? 'CONFIRMEE' : 'BROUILLON'} onChange={e => { const v = e.target.value; setEdition(p => p ? {...p, statut:(v === 'BROUILLON' ? 'BROUILLON' : 'CONFIRMEE') as StatutCommandeArtisan, livre:v === 'LIVRE' || v === 'PAYE', paye:v === 'PAYE'} : null) }}><option value="BROUILLON">Bon créé</option><option value="CONFIRMEE">Bon confirmé — réception stock</option><option value="LIVRE">Livré</option><option value="PAYE">Payé</option></select></label>

              <label className="ind-wide">Remarques<textarea rows={3} value={edition.remarque} onChange={e => modifier('remarque', e.target.value)} /></label>
              <div className="ind-form-total ind-wide">Prix TTC calculé par brioche <strong>{edition.quantiteCommandee > 0 && totalTtc.trim() !== '' && Number.isFinite(Number(totalTtc.replace(',', '.'))) ? argent(Number(totalTtc.replace(',', '.')) / edition.quantiteCommandee) : '—'}</strong></div>
              {erreur && <p className="ind-form-error ind-wide" role="alert">{erreur}</p>}
            </div>
            <footer className="ind-dialog-footer"><button type="button" className="ind-cancel" onClick={() => setEdition(null)}>Annuler</button><button type="submit" className="ind-primary"><Check size={17}/> Enregistrer la commande</button></footer>
          </form>
        </section>
      </div>}
    </main>
  )
}

import { omitKeys } from '../lib/omitKeys'
import {
  useEffect,
  useMemo,
  useState,
  type FormEvent,
  type ReactNode,
} from 'react'

import {
  AlertTriangle,
  Boxes,
  CheckCircle2,
  ChevronLeft,
  ChevronRight,
  CircleDollarSign,
  ClipboardList,
  Download,
  Eye,
  Mail,
  Pencil,
  Phone,
  Plus,
  Search,
  Trash2,
  Truck,
  UserRound,
  X,
} from 'lucide-react'

import { useMairies } from '../contexts/MairiesContext'
import { useCommandesMairiesRs } from '../contexts/CommandesMairiesRsContext'
import type {
  CommandeMairieRs,
  NouvelleCommandeMairieRs,
  StatutCommandeMairieRs,
  TypeCommandeMairieRs,
} from '../types/commandesMairiesRs'
import './CommandesMairiesRs.css'

type FormMode = 'create' | 'edit'

const STATUS_LABELS: Record<StatutCommandeMairieRs, string> = {
  BROUILLON: 'Brouillon',
  COMMANDEE: 'Commandée',
  A_PREPARER: 'À préparer',
  A_RECUPERER: 'À récupérer',
  BRIOCHES_REMISES: 'Brioches remises',
  DONS_A_RECUPERER: 'Dons à récupérer',
  TERMINEE: 'Terminée',
  ANNULEE: 'Annulée',
}

const TYPE_LABELS: Record<TypeCommandeMairieRs, string> = {
  MAIRIE: 'Mairie',
  RS: 'RS',
}

function normalize(value: unknown) {
  return String(value ?? '')
    .trim()
    .toLocaleLowerCase('fr')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
}

function money(value: number) {
  return new Intl.NumberFormat('fr-FR', {
    style: 'currency',
    currency: 'EUR',
  }).format(value)
}

function number(value: number) {
  return new Intl.NumberFormat('fr-FR').format(value)
}

function formatDate(value: string) {
  if (!value) return '—'
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return value

  return new Intl.DateTimeFormat('fr-FR').format(
    new Date(`${value}T12:00:00`),
  )
}

function csvCell(value: unknown) {
  return `"${String(value ?? '').replace(/"/g, '""')}"`
}

function emptyCommande(
  campagne: string,
): NouvelleCommandeMairieRs {
  return {
    campagne,
    type: 'MAIRIE',
    mairieId: null,

    secteur: '',
    sousSecteur: '',
    quiPasseCommande: '',
    responsableSecteur: '',

    quantite: 0,
    nbCartons: 0,

    dateRecuperation: '',
    recuperationLibre: '',
    quiRecupere: '',
    email: '',
    telephone: '',
    lieuRecuperation: '',
    livraisonPar: '',
    remarque: '',

    prixUnitaire: 5,
    donPrevu: 0,
    nombreBriochesVendues: null,
    personneRapportantDons: '',
    lieuDepotDons: '',
    donRecu: null,

    statut: 'BROUILLON',
  }
}

function getGap(item: CommandeMairieRs) {
  if (item.donRecu === null) return null
  return item.donRecu - item.donPrevu
}


export default function CommandesMairiesRs() {
  const {
    commandes,
    createCommande,
    updateCommande,
    deleteCommande,
  } = useCommandesMairiesRs()

  const { mairies } = useMairies()

  const campaigns = useMemo(
    () =>
      Array.from(
        new Set(
          commandes
            .map((item) => item.campagne)
            .filter(Boolean),
        ),
      ).sort((a, b) =>
        b.localeCompare(a, 'fr', { numeric: true }),
      ),
    [commandes],
  )

  const [campagneFilter, setCampagneFilter] =
    useState(campaigns[0] || `OB ${new Date().getFullYear()}`)

  const [search, setSearch] = useState('')
  const [secteurFilter, setSecteurFilter] = useState('TOUS')
  const [sousSecteurFilter, setSousSecteurFilter] = useState('TOUS')
  const [typeFilter, setTypeFilter] = useState<'TOUS' | TypeCommandeMairieRs>('TOUS')
  const [statusFilter, setStatusFilter] = useState<'TOUS' | StatutCommandeMairieRs>('TOUS')

  const [page, setPage] = useState(1)
  const [perPage, setPerPage] = useState(10)

  const [detailId, setDetailId] = useState<string | null>(null)
  const [modalOpen, setModalOpen] = useState(false)
  const [formMode, setFormMode] = useState<FormMode>('create')
  const [editingId, setEditingId] = useState<string | null>(null)
  const [form, setForm] =
    useState<NouvelleCommandeMairieRs>(
      emptyCommande(campagneFilter),
    )
  const [error, setError] = useState('')

  const campagneCommandes = useMemo(
    () =>
      commandes.filter(
        (item) => item.campagne === campagneFilter,
      ),
    [commandes, campagneFilter],
  )

  const secteurs = useMemo(
    () =>
      [
        'TOUS',
        ...Array.from(
          new Set(
            campagneCommandes
              .map((item) => item.secteur.trim())
              .filter(Boolean),
          ),
        ).sort((a, b) => a.localeCompare(b, 'fr')),
      ],
    [campagneCommandes],
  )

  const sousSecteurs = useMemo(
    () =>
      [
        'TOUS',
        ...Array.from(
          new Set(
            campagneCommandes
              .filter(
                (item) =>
                  secteurFilter === 'TOUS' ||
                  item.secteur === secteurFilter,
              )
              .map((item) => item.sousSecteur.trim())
              .filter(Boolean),
          ),
        ).sort((a, b) => a.localeCompare(b, 'fr')),
      ],
    [campagneCommandes, secteurFilter],
  )

  const filtered = useMemo(() => {
    const query = normalize(search)

    return campagneCommandes
      .filter(
        (item) =>
          secteurFilter === 'TOUS' ||
          item.secteur === secteurFilter,
      )
      .filter(
        (item) =>
          sousSecteurFilter === 'TOUS' ||
          item.sousSecteur === sousSecteurFilter,
      )
      .filter(
        (item) =>
          typeFilter === 'TOUS' ||
          item.type === typeFilter,
      )
      .filter(
        (item) =>
          statusFilter === 'TOUS' ||
          item.statut === statusFilter,
      )
      .filter((item) => {
        if (!query) return true

        return normalize(
          [
            item.numero,
            item.quiPasseCommande,
            item.responsableSecteur,
            item.secteur,
            item.sousSecteur,
            item.quiRecupere,
            item.email,
            item.telephone,
            item.livraisonPar,
            item.lieuRecuperation,
          ].join(' '),
        ).includes(query)
      })
      .sort((a, b) =>
        a.numero.localeCompare(b.numero, 'fr', {
          numeric: true,
        }),
      )
  }, [
    campagneCommandes,
    search,
    secteurFilter,
    sousSecteurFilter,
    typeFilter,
    statusFilter,
  ])

  useEffect(() => {
    setPage(1)
  }, [
    search,
    campagneFilter,
    secteurFilter,
    sousSecteurFilter,
    typeFilter,
    statusFilter,
    perPage,
  ])

  useEffect(() => {
    if (
      sousSecteurFilter !== 'TOUS' &&
      !sousSecteurs.includes(sousSecteurFilter)
    ) {
      setSousSecteurFilter('TOUS')
    }
  }, [sousSecteurFilter, sousSecteurs])

  const totalPages = Math.max(
    1,
    Math.ceil(filtered.length / perPage),
  )

  const safePage = Math.min(page, totalPages)

  const paged = filtered.slice(
    (safePage - 1) * perPage,
    safePage * perPage,
  )

  const stats = useMemo(() => {
    const active = campagneCommandes.filter(
      (item) => item.statut !== 'ANNULEE',
    )

    return {
      commandes: active.length,
      brioches: active.reduce(
        (sum, item) => sum + item.quantite,
        0,
      ),
      donsPrevus: active.reduce(
        (sum, item) => sum + item.donPrevu,
        0,
      ),
      donsRecus: active.reduce(
        (sum, item) => sum + (item.donRecu ?? 0),
        0,
      ),
    }
  }, [campagneCommandes])

  const repartition = useMemo(() => {
    const map = new Map<
      string,
      { secteur: string; count: number; brioches: number }
    >()

    for (const item of campagneCommandes) {
      if (item.statut === 'ANNULEE') continue

      const key = item.secteur || 'Non renseigné'
      const current = map.get(key) || {
        secteur: key,
        count: 0,
        brioches: 0,
      }

      current.count += 1
      current.brioches += item.quantite
      map.set(key, current)
    }

    return [...map.values()].sort(
      (a, b) => b.count - a.count,
    )
  }, [campagneCommandes])

  const vigilance = useMemo(() => {
    const commandesATraiter = campagneCommandes.filter(
      (item) =>
        item.statut === 'BROUILLON' ||
        item.statut === 'COMMANDEE' ||
        item.statut === 'A_PREPARER',
    ).length

    const donsARecuperer = campagneCommandes.filter(
      (item) => item.statut === 'DONS_A_RECUPERER',
    ).length

    const sansContact = campagneCommandes.filter(
      (item) => !item.email.trim() && !item.telephone.trim(),
    ).length

    const ecartsNegatifs = campagneCommandes.filter((item) => {
      const gap = getGap(item)
      return gap !== null && gap < 0
    }).length

    return {
      commandesATraiter,
      donsARecuperer,
      sansContact,
      ecartsNegatifs,
    }
  }, [campagneCommandes])

  const detail = detailId
    ? commandes.find((item) => item.id === detailId) ?? null
    : null

  function updateField<K extends keyof NouvelleCommandeMairieRs>(
    key: K,
    value: NouvelleCommandeMairieRs[K],
  ) {
    setForm((current) => ({
      ...current,
      [key]: value,
    }))
  }

  function openCreate() {
    setFormMode('create')
    setEditingId(null)
    setForm(emptyCommande(campagneFilter))
    setError('')
    setModalOpen(true)
  }

  function openEdit(item: CommandeMairieRs) {
    const editable = omitKeys(item, 'id', 'numero', 'createdAt', 'updatedAt')

    setFormMode('edit')
    setEditingId(item.id)
    setForm(editable)
    setError('')
    setDetailId(null)
    setModalOpen(true)
  }

  function selectMairie(mairieId: string) {
    if (!mairieId) {
      updateField('mairieId', null)
      return
    }

    const mairie = mairies.find(
      (item) => item.id === mairieId,
    )

    if (!mairie) return

    const address = [
      [mairie.numeroVoie, mairie.adresse]
        .filter(Boolean)
        .join(' '),
      [mairie.cp, mairie.ville || mairie.commune]
        .filter(Boolean)
        .join(' '),
    ]
      .filter(Boolean)
      .join('\n')

    setForm((current) => ({
      ...current,
      mairieId: mairie.id,
      type: 'MAIRIE',
      secteur: mairie.secteur || current.secteur,
      quiPasseCommande: mairie.nomAffiche,
      quiRecupere:
        current.quiRecupere ||
        [mairie.contactPrenom, mairie.contactNom]
          .filter(Boolean)
          .join(' '),
      email: mairie.email,
      telephone: mairie.telephone,
      lieuRecuperation:
        current.lieuRecuperation || address,
    }))
  }

  function changeQuantity(value: number) {
    const quantity = Math.max(0, value || 0)

    setForm((current) => ({
      ...current,
      quantite: quantity,
      nbCartons: quantity / 7,
      donPrevu: quantity * current.prixUnitaire,
    }))
  }

  function changePrice(value: number) {
    const price = Math.max(0, value || 0)

    setForm((current) => ({
      ...current,
      prixUnitaire: price,
      donPrevu: current.quantite * price,
    }))
  }

  function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault()
    setError('')

    if (!form.campagne.trim()) {
      setError('La campagne est obligatoire.')
      return
    }

    if (!form.quiPasseCommande.trim()) {
      setError(
        'La mairie ou le responsable de secteur est obligatoire.',
      )
      return
    }

    if (!form.secteur.trim()) {
      setError('Le secteur est obligatoire.')
      return
    }

    if (form.quantite <= 0) {
      setError(
        'Le nombre de brioches commandées doit être supérieur à 0.',
      )
      return
    }

    const normalized: NouvelleCommandeMairieRs = {
      ...form,
      secteur: form.secteur.trim(),
      sousSecteur: form.sousSecteur.trim(),
      quiPasseCommande: form.quiPasseCommande.trim(),
      responsableSecteur: form.responsableSecteur.trim(),
      recuperationLibre: form.recuperationLibre.trim(),
      quiRecupere: form.quiRecupere.trim(),
      email: form.email.trim(),
      telephone: form.telephone.trim(),
      lieuRecuperation: form.lieuRecuperation.trim(),
      livraisonPar: form.livraisonPar.trim(),
      remarque: form.remarque.trim(),
      personneRapportantDons:
        form.personneRapportantDons.trim(),
      lieuDepotDons: form.lieuDepotDons.trim(),
      nbCartons: Number(
        (form.nbCartons || form.quantite / 7).toFixed(2),
      ),
    }

    if (formMode === 'edit' && editingId) {
      updateCommande(editingId, normalized)
    } else {
      createCommande(normalized)
    }

    setModalOpen(false)
    setEditingId(null)
  }

  function remove(item: CommandeMairieRs) {
    const ok = window.confirm(
      `Supprimer la commande ${item.numero} de ${item.quiPasseCommande} ?`,
    )

    if (!ok) return

    deleteCommande(item.id)
    setDetailId(null)
  }

  function exportCsv() {
    const rows = [
      [
        'Numero',
        'Campagne',
        'Type',
        'Secteur',
        'Sous-secteur',
        'Qui passe la commande',
        'Responsable de secteur',
        'Brioches commandees',
        'Cartons',
        'Date de recuperation',
        'Information recuperation',
        'Qui recupere',
        'Email',
        'Telephone',
        'Lieu de recuperation',
        'Livraison par',
        'Remarque',
        'Don prevu',
        'Brioches vendues',
        'Personne rapportant les dons',
        'Lieu de depot des dons',
        'Don recu',
        'Ecart',
        'Statut',
      ],
      ...filtered.map((item) => [
        item.numero,
        item.campagne,
        TYPE_LABELS[item.type],
        item.secteur,
        item.sousSecteur,
        item.quiPasseCommande,
        item.responsableSecteur,
        item.quantite,
        item.nbCartons,
        item.dateRecuperation,
        item.recuperationLibre,
        item.quiRecupere,
        item.email,
        item.telephone,
        item.lieuRecuperation,
        item.livraisonPar,
        item.remarque,
        item.donPrevu,
        item.nombreBriochesVendues ?? '',
        item.personneRapportantDons,
        item.lieuDepotDons,
        item.donRecu ?? '',
        getGap(item) ?? '',
        STATUS_LABELS[item.statut],
      ]),
    ]

    const csv = rows
      .map((row) => row.map(csvCell).join(';'))
      .join('\n')

    const blob = new Blob([`\ufeff${csv}`], {
      type: 'text/csv;charset=utf-8',
    })

    const url = URL.createObjectURL(blob)
    const anchor = document.createElement('a')
    anchor.href = url
    anchor.download = `commandes-mairies-rs-${campagneFilter
      .replace(/\s+/g, '-')
      .toLowerCase()}.csv`
    document.body.appendChild(anchor)
    anchor.click()
    anchor.remove()
    URL.revokeObjectURL(url)
  }

  const receivedProgress =
    stats.donsPrevus > 0
      ? Math.min(
          100,
          (stats.donsRecus / stats.donsPrevus) * 100,
        )
      : 0

  return (
    <main className="cmr-page">
      <header className="cmr-header">
        <div>
          <span className="cmr-eyebrow">
            Commandes dons · Mairies & RS
          </span>

          <h1>Commandes Mairies & RS</h1>

          <p>
            Suivez les commandes des mairies et responsables
            de secteur, les récupérations et les retours de dons.
          </p>
        </div>

        <div className="cmr-header-actions">
          <label>
            <span>Campagne</span>
            <select
              value={campagneFilter}
              onChange={(event) =>
                setCampagneFilter(event.target.value)
              }
            >
              {campaigns.map((campagne) => (
                <option
                  key={campagne}
                  value={campagne}
                >
                  {campagne}
                </option>
              ))}
            </select>
          </label>

          <button
            type="button"
            className="cmr-primary"
            onClick={openCreate}
          >
            <Plus size={18} />
            Nouvelle commande
          </button>
        </div>
      </header>

      <section className="cmr-kpis">
        <Kpi
          icon={<ClipboardList size={22} />}
          tone="orange"
          label="Commandes"
          value={number(stats.commandes)}
        />
        <Kpi
          icon={<Boxes size={22} />}
          tone="gold"
          label="Brioches"
          value={number(stats.brioches)}
        />
        <Kpi
          icon={<CircleDollarSign size={22} />}
          tone="orange"
          label="Dons prévus"
          value={money(stats.donsPrevus)}
        />
        <Kpi
          icon={<CheckCircle2 size={22} />}
          tone="green"
          label="Dons reçus"
          value={money(stats.donsRecus)}
        />
      </section>

      <section className="cmr-card">
        <div className="cmr-toolbar">
          <label className="cmr-search">
            <Search size={17} />
            <input
              value={search}
              onChange={(event) =>
                setSearch(event.target.value)
              }
              placeholder="Rechercher une mairie, un RS, une commune..."
            />
          </label>

          <select
            value={secteurFilter}
            onChange={(event) =>
              setSecteurFilter(event.target.value)
            }
          >
            {secteurs.map((secteur) => (
              <option
                key={secteur}
                value={secteur}
              >
                {secteur === 'TOUS'
                  ? 'Tous les secteurs'
                  : secteur}
              </option>
            ))}
          </select>

          <select
            value={sousSecteurFilter}
            onChange={(event) =>
              setSousSecteurFilter(event.target.value)
            }
          >
            {sousSecteurs.map((sousSecteur) => (
              <option
                key={sousSecteur}
                value={sousSecteur}
              >
                {sousSecteur === 'TOUS'
                  ? 'Tous les sous-secteurs'
                  : sousSecteur}
              </option>
            ))}
          </select>

          <select
            value={typeFilter}
            onChange={(event) =>
              setTypeFilter(
                event.target.value as
                  | 'TOUS'
                  | TypeCommandeMairieRs,
              )
            }
          >
            <option value="TOUS">Mairies + RS</option>
            <option value="MAIRIE">Mairies</option>
            <option value="RS">RS</option>
          </select>

          <select
            value={statusFilter}
            onChange={(event) =>
              setStatusFilter(
                event.target.value as
                  | 'TOUS'
                  | StatutCommandeMairieRs,
              )
            }
          >
            <option value="TOUS">Tous les statuts</option>
            {(
              Object.keys(
                STATUS_LABELS,
              ) as StatutCommandeMairieRs[]
            ).map((status) => (
              <option
                key={status}
                value={status}
              >
                {STATUS_LABELS[status]}
              </option>
            ))}
          </select>

          <button
            type="button"
            className="cmr-secondary"
            onClick={exportCsv}
          >
            <Download size={16} />
            Exporter
          </button>
        </div>

        <div className="cmr-table-wrap">
          <table className="cmr-table">
            <thead>
              <tr>
                <th>N°</th>
                <th>Mairie / RS</th>
                <th>Type</th>
                <th>Secteur</th>
                <th>Qté</th>
                <th>Récupération</th>
                <th>Récupéré par</th>
                <th>Livraison par</th>
                <th>Don prévu</th>
                <th>Don reçu</th>
                <th>Écart</th>
                <th>Statut</th>
                <th>Actions</th>
              </tr>
            </thead>

            <tbody>
              {paged.map((item) => {
                const gap = getGap(item)

                return (
                  <tr
                    key={item.id}
                    onDoubleClick={() =>
                      setDetailId(item.id)
                    }
                  >
                    <td className="cmr-number">
                      {item.numero}
                    </td>

                    <td>
                      <strong>
                        {item.quiPasseCommande}
                      </strong>
                      {item.sousSecteur && (
                        <small>
                          {item.sousSecteur}
                        </small>
                      )}
                    </td>

                    <td>
                      <TypeBadge type={item.type} />
                    </td>

                    <td>{item.secteur || '—'}</td>

                    <td>
                      <strong>
                        {number(item.quantite)}
                      </strong>
                    </td>

                    <td>
                      {item.dateRecuperation
                        ? formatDate(item.dateRecuperation)
                        : item.recuperationLibre || '—'}
                    </td>

                    <td>{item.quiRecupere || '—'}</td>
                    <td>{item.livraisonPar || '—'}</td>
                    <td>{money(item.donPrevu)}</td>

                    <td>
                      {item.donRecu === null
                        ? '—'
                        : money(item.donRecu)}
                    </td>

                    <td>
                      {gap === null ? (
                        '—'
                      ) : (
                        <span
                          className={`cmr-gap ${
                            gap < 0
                              ? 'negative'
                              : gap > 0
                                ? 'positive'
                                : 'zero'
                          }`}
                        >
                          {gap > 0 ? '+' : ''}
                          {money(gap)}
                        </span>
                      )}
                    </td>

                    <td>
                      <StatusBadge
                        status={item.statut}
                      />
                    </td>

                    <td>
                      <div className="cmr-actions">
                        <button
                          type="button"
                          title="Voir"
                          onClick={() =>
                            setDetailId(item.id)
                          }
                        >
                          <Eye size={15} />
                        </button>

                        <button
                          type="button"
                          title="Modifier"
                          onClick={() =>
                            openEdit(item)
                          }
                        >
                          <Pencil size={15} />
                        </button>
                      </div>
                    </td>
                  </tr>
                )
              })}

              {paged.length === 0 && (
                <tr>
                  <td
                    colSpan={13}
                    className="cmr-empty"
                  >
                    Aucune commande ne correspond aux
                    critères sélectionnés.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>

        <footer className="cmr-pagination">
          <span>
            {filtered.length === 0
              ? '0 résultat'
              : `${(safePage - 1) * perPage + 1}–${Math.min(
                  safePage * perPage,
                  filtered.length,
                )} sur ${filtered.length} commandes`}
          </span>

          <div>
            <button
              type="button"
              disabled={safePage <= 1}
              onClick={() =>
                setPage((current) =>
                  Math.max(1, current - 1),
                )
              }
            >
              <ChevronLeft size={16} />
            </button>

            <strong>
              {safePage} / {totalPages}
            </strong>

            <button
              type="button"
              disabled={safePage >= totalPages}
              onClick={() =>
                setPage((current) =>
                  Math.min(totalPages, current + 1),
                )
              }
            >
              <ChevronRight size={16} />
            </button>

            <select
              value={perPage}
              onChange={(event) =>
                setPerPage(Number(event.target.value))
              }
            >
              <option value={10}>10 par page</option>
              <option value={25}>25 par page</option>
              <option value={50}>50 par page</option>
            </select>
          </div>
        </footer>
      </section>

      <section className="cmr-bottom-grid">
        <article className="cmr-dashboard-card">
          <header>
            <Boxes size={18} />
            <h2>Répartition des commandes</h2>
          </header>

          <div className="cmr-sector-list">
            {repartition.map((item, index) => {
              const percentage =
                stats.commandes > 0
                  ? Math.round(
                      (item.count / stats.commandes) * 100,
                    )
                  : 0

              return (
                <div
                  key={item.secteur}
                  className="cmr-sector-row"
                >
                  <span className={`dot dot-${index % 6}`} />
                  <strong>{item.secteur}</strong>
                  <span>{item.count}</span>
                  <em>{percentage} %</em>
                </div>
              )
            })}
          </div>
        </article>

        <article className="cmr-dashboard-card">
          <header>
            <CircleDollarSign size={18} />
            <h2>Suivi des dons</h2>
          </header>

          <Metric
            label="Dons prévus"
            value={money(stats.donsPrevus)}
          />
          <Metric
            label="Dons reçus"
            value={money(stats.donsRecus)}
          />
          <Metric
            label="Reste à collecter"
