function FichesCaisse() {
  const [globalSearchParams] = useSearchParams()
  const {
    fichesCaisse,
    setFichesCaisse,
    depotsBanque,
    commandes,
    getDonateurById,
    activeCampagne,
  } = useObData()

  /* =======================================================
     INTÉGRATION AUTOMATIQUE DES ANCIENNES FICHES
     ======================================================= */

  useEffect(() => {
    if (
      !fichesCaisse.some(
        fiche => fiche.statutCoffre !== 'CONTROLEE',
      )
    ) {
      return
    }

    setFichesCaisse(current =>
      current.map(fiche =>
        fiche.statutCoffre === 'CONTROLEE'
          ? fiche
          : {
              ...fiche,
              statutCoffre: 'CONTROLEE',
            },
      ),
    )
  }, [fichesCaisse, setFichesCaisse])


  const [
    search,
    setSearch,
  ] = useState('')

  const [
    typeFilter,
    setTypeFilter,
  ] = useState('Tous')

  const [
    secteurFilter,
    setSecteurFilter,
  ] = useState('Tous')

  const [
    dateFilter,
    setDateFilter,
  ] = useState('')

  const [
    sortKey,
    setSortKey,
  ] =
    useState<SortKey>(
      'numero',
    )

  const [
    sortDirection,
    setSortDirection,
  ] =
    useState<SortDirection>(
      'desc',
    )

  const [
    modalOpen,
    setModalOpen,
  ] = useState(false)

  const [
    modalMode,
    setModalMode,
  ] =
    useState<FicheFormMode>(
      'create',
    )

  const [
    editingFiche,
    setEditingFiche,
  ] =
    useState<FicheCaisse | null>(
      null,
    )

  const [
    detailFiche,
    setDetailFiche,
  ] =
    useState<FicheCaisse | null>(
      null,
    )

  // Ouverture directe depuis la recherche globale, sans contourner les permissions.
  const ficheRecherche = globalSearchParams.get('fiche')
  useEffect(() => {
    if (!ficheRecherche) return
    const match = fichesCaisse.find(f => String(f.id) === ficheRecherche || f.numero === ficheRecherche)
    if (match) setDetailFiche(match)
  }, [ficheRecherche, fichesCaisse])

  const [
    exportMenuOpen,
    setExportMenuOpen,
  ] = useState(false)

  const [
    columnsMenuOpen,
    setColumnsMenuOpen,
  ] = useState(false)

  const [
    actionMenuId,
    setActionMenuId,
  ] =
    useState<number | null>(
      null,
    )

  const [
    visibleColumns,
    setVisibleColumns,
  ] = useState<
    Record<
      ColumnKey,
      boolean
    >
  >(() => {
    const saved =
      localStorage.getItem(
        'ob-fiches-caisse-columns',
      )

    if (!saved) {
      return {
        ...DEFAULT_COLUMNS,
      }
    }

    try {
      return {
        ...DEFAULT_COLUMNS,
        ...JSON.parse(saved),
      }
    } catch {
      return {
        ...DEFAULT_COLUMNS,
      }
    }
  })

  /* =======================================================
     MEMORISATION DES COLONNES
     ======================================================= */

  useEffect(() => {
    localStorage.setItem(
      'ob-fiches-caisse-columns',
      JSON.stringify(
        visibleColumns,
      ),
    )
  }, [
    visibleColumns,
  ])

  /* =======================================================
     SECTEURS
     ======================================================= */

  const secteurs =
    useMemo(() => {
      const values =
        fichesCaisse
          .map(
            (fiche) =>
              fiche.secteur,
          )
          .filter(
            (
              value,
            ): value is string =>
              Boolean(value),
          )

      return [
        'Tous',
        ...Array.from(
          new Set(values),
        ).sort(
          (a, b) =>
            a.localeCompare(
              b,
              'fr',
            ),
        ),
      ]
    }, [
      fichesCaisse,
    ])

  /* =======================================================
     FILTRE + TRI
     ======================================================= */

  const filteredFiches =
    useMemo(() => {
      const query =
        search
          .trim()
          .toLowerCase()

      const filtered =
        fichesCaisse.filter(
          (fiche) => {
            const searchable =
              [
                fiche.numero,
                fiche.libelle,
                fiche.ville,
                fiche.cp,
                fiche.secteur,
                fiche.type,
              ]
                .filter(Boolean)
                .join(' ')
                .toLowerCase()

            const matchesSearch =
              !query ||
              searchable.includes(
                query,
              )

            const matchesType =
              typeFilter ===
                'Tous' ||
              fiche.type ===
                typeFilter

            const matchesSecteur =
              secteurFilter ===
                'Tous' ||
              fiche.secteur ===
                secteurFilter

            const matchesDate =
              !dateFilter ||
              fiche.date ===
                dateFilter

            return (
              matchesSearch &&
              matchesType &&
              matchesSecteur &&
              matchesDate
            )
          },
        )

      return [
        ...filtered,
      ].sort(
        (a, b) => {
          const valueA =
            getSortValue(
              a,
              sortKey,
            )

          const valueB =
            getSortValue(
              b,
              sortKey,
            )

          const comparison =
            typeof valueA === 'number' && typeof valueB === 'number'
              ? valueA - valueB
              : String(valueA).localeCompare(String(valueB), 'fr', {
                  numeric: true,
                  sensitivity: 'base',
                })

          return sortDirection ===
            'asc'
            ? comparison
            : -comparison
        },
      )
    }, [
      fichesCaisse,
      search,
      typeFilter,
      secteurFilter,
      dateFilter,
      sortKey,
      sortDirection,
    ])

  /* =======================================================
     TOTAUX
     ======================================================= */

     /* =======================================================
   PAGINATION DES FICHES DE CAISSE
   ======================================================= */

// Préférence enregistrée dans le navigateur.
// Par défaut : 20 fiches par page.

const [pageSize, setPageSize] = useState<PageSize>(() => {
  try {
    const saved = localStorage.getItem(PAGE_SIZE_KEY)

    if (saved === 'infini') {
      return 'infini'
    }

    if (
      saved === '20' ||
      saved === '50' ||
      saved === '100'
    ) {
      return Number(saved) as 20 | 50 | 100
    }
  } catch {
    // La pagination reste utilisable sans localStorage.
  }

  return 20
})

const [page, setPage] = useState(1)

// Mémorisation de la préférence utilisateur.

useEffect(() => {
  try {
    localStorage.setItem(
      PAGE_SIZE_KEY,
      String(pageSize),
    )
  } catch {
    // Pas de blocage si le stockage est indisponible.
  }
}, [pageSize])

// Retour en page 1 après modification des filtres.

useEffect(() => {
  setPage(1)
}, [
  search,
  typeFilter,
  secteurFilter,
  dateFilter,
])

// Calcul du nombre total de pages.

const pageCount =
  pageSize === 'infini'
    ? 1
    : Math.max(
        1,
        Math.ceil(filteredFiches.length / pageSize),
      )

// Évite de rester sur une page inexistante
// après une suppression ou une modification des données.

const currentPage = Math.min(page, pageCount)

useEffect(() => {
  setPage(current =>
    Math.min(current, pageCount),
  )
}, [pageCount])

// Liste réellement affichée dans le tableau.
// filteredFiches reste intact pour les totaux et exports.

const visibleFiches = useMemo(() => {
  if (pageSize === 'infini') {
    return filteredFiches
  }

  const start =
    (currentPage - 1) * pageSize

  return filteredFiches.slice(
    start,
    start + pageSize,
  )
}, [
  filteredFiches,
  pageSize,
  currentPage,
])

// Numéros affichés : exemple "21–40 sur 87".

const firstVisible =
  filteredFiches.length === 0
    ? 0
    : pageSize === 'infini'
      ? 1
      : (currentPage - 1) * pageSize + 1

const lastVisible =
  pageSize === 'infini'
    ? filteredFiches.length
    : Math.min(
        currentPage * pageSize,
        filteredFiches.length,
      )

// Afficher au maximum cinq boutons numérotés.

const firstPageButton = Math.max(
  1,
  Math.min(
    currentPage - 2,
    pageCount - 4,
  ),
)

const pageButtons = Array.from(
  {
    length: Math.min(5, pageCount),
  },
  (_, index) => firstPageButton + index,
)

  const totals =
    useMemo(() => {
      return filteredFiches.reduce(
        (
          result,
          fiche,
        ) => {
          result.especes +=
            getMontantEspeces(
              fiche,
            )

          result.cheques +=
            fiche.montantCheques

          result.tpe +=
            fiche.montantTpe

          result.virement +=
            fiche.montantVirement

          result.dons +=
            getMontantDons(
              fiche,
            )

          result.total +=
            getTotalFiche(
              fiche,
            )

          return result
        },
        {
          especes: 0,
          cheques: 0,
          tpe: 0,
          virement: 0,
          dons: 0,
          total: 0,
        },
      )
    }, [
      filteredFiches,
    ])

  /* =======================================================
     TRI
     ======================================================= */

  function changeSort(
    key: SortKey,
  ) {
    if (
      key === sortKey
    ) {
      setSortDirection(
        (current) =>
          current ===
          'asc'
            ? 'desc'
            : 'asc',
      )

      return
    }

    setSortKey(
      key,
    )

    setSortDirection(
      'asc',
    )
  }

  /* =======================================================
     COLONNES
     ======================================================= */

  function toggleColumn(
    key: ColumnKey,
  ) {
    setVisibleColumns(
      (current) => ({
        ...current,
        [key]:
          !current[key],
      }),
    )
  }

  /* =======================================================
     CREATION
     ======================================================= */

  function openCreateModal() {
    setEditingFiche(
      null,
    )

    setModalMode(
      'create',
    )

    setModalOpen(
      true,
    )

    setActionMenuId(
      null,
    )
  }

  /* =======================================================
     MODIFICATION
     ======================================================= */

  function openEditModal(fiche: FicheCaisse) {
    // Une fiche contrôlée alimente déjà le coffre : correction bloquée.
    if (fiche.statutCoffre === 'CONTROLEE') {
      window.alert(
        'Cette fiche est contrôlée et intégrée au coffre. Une procédure de correction dédiée est nécessaire pour modifier ses montants.',
      )
      return
    }

    setDetailFiche(null)
    setEditingFiche(fiche)
    setModalMode('edit')
    setModalOpen(true)
    setActionMenuId(null)
  }

  /* =======================================================
     SAUVEGARDE

     Création et modification = fiche à contrôler.
     Une fiche contrôlée ne peut pas être écrasée par le formulaire.
     ======================================================= */

  function saveFiche(fiche: FicheCaisse) {
    try {
      if (modalMode === 'edit') {
        const originale = fichesCaisse.find(item => item.id === fiche.id)

        if (!originale) {
          throw new Error('Impossible de retrouver la fiche à modifier.')
        }

        if (originale.statutCoffre === 'CONTROLEE') {
          throw new Error('Cette fiche est contrôlée et ne peut pas être modifiée.')
        }
      } else if (fichesCaisse.some(item => item.id === fiche.id)) {
        throw new Error('Cet identifiant de fiche existe déjà.')
      }

      const prochaineFiche: FicheCaisse = {
        ...fiche,
        statutCoffre: 'CONTROLEE',
        dateControleCoffre: new Date().toISOString(),
}

      // Validation des quantités et des chèques avant la sauvegarde.
      // La simulation ne déclenche aucun mouvement réel du coffre.
      calculerCoffre(
        prochaineFiche.campagne,
        [{ ...prochaineFiche, statutCoffre: 'CONTROLEE' }],
        [],
      )

      setFichesCaisse(current =>
        modalMode === 'edit'
          ? current.map(item => item.id === fiche.id ? prochaineFiche : item)
          : [...current, prochaineFiche],
      )

      setModalOpen(false)
      setEditingFiche(null)
    } catch (error) {
      window.alert(
        error instanceof Error ? error.message : 'Enregistrement impossible.',
      )
    }
  }

  /* =======================================================
     CONTRÔLER POUR LE COFFRE

     La fiche conserve son ID et n'est pas dupliquée.
     Le coffre calcule ensuite les entrées automatiquement.
     ======================================================= */

  function controlerFiche(fiche: FicheCaisse) {
    if (fiche.statutCoffre === 'CONTROLEE') return

    const prochaineFiche: FicheCaisse = {
      ...fiche,
      statutCoffre: 'CONTROLEE',
      dateControleCoffre: new Date().toISOString(),
    }

    const prochainesFiches = fichesCaisse.map(item =>
      item.id === fiche.id ? prochaineFiche : item,
    )

    try {
      // Refuser la validation si elle conduit à un stock incohérent.
      calculerCoffre(fiche.campagne, prochainesFiches, depotsBanque)
    } catch (error) {
      window.alert(
        `Impossible de contrôler cette fiche.\n\n${
          error instanceof Error ? error.message : 'Erreur inconnue.'
        }`,
      )
      return
    }

    const confirme = window.confirm(
      `Contrôler la fiche ${fiche.numero} ?\n\n` +
      'Ses pièces, billets et chèques seront ajoutés au coffre. ' +
      'La fiche sera ensuite verrouillée pour éviter une modification involontaire.',
    )

    if (!confirme) return

    setFichesCaisse(prochainesFiches)
    setDetailFiche(current =>
      current?.id === fiche.id ? prochaineFiche : current,
    )
    setActionMenuId(null)
  }

