        width: 16,
      },
      {
        key: 'montant',
        width: 22,
      },
    ]

    worksheet.mergeCells(
      'A1:C1',
    )

    worksheet.getCell(
      'A1',
    ).value =
      'OPÉRATION BRIOCHES'

    worksheet.mergeCells(
      'A2:C2',
    )

    worksheet.getCell(
      'A2',
    ).value =
      'FICHE DE CAISSE'

    worksheet.mergeCells(
      'A3:C3',
    )

    worksheet.getCell(
      'A3',
    ).value =
      fiche.numero

    worksheet.mergeCells(
      'A5:C5',
    )

    worksheet.getCell(
      'A5',
    ).value =
      fiche.libelle

    worksheet.addRow([])

    worksheet.addRow([
      'Date',
      '',
      formatDate(
        fiche.date,
      ),
    ])

    worksheet.addRow([
      'Type',
      '',
      formatType(
        fiche.type,
      ),
    ])

    worksheet.addRow([
      'Campagne',
      '',
      fiche.campagne,
    ])

    worksheet.addRow([
      'Code postal',
      '',
      fiche.cp || '',
    ])

    worksheet.addRow([
      'Ville',
      '',
      fiche.ville || '',
    ])

    worksheet.addRow([
      'Secteur',
      '',
      fiche.secteur ||
        '',
    ])

    worksheet.addRow([])

    const billetsTitleRow =
      worksheet.addRow([
        'BILLETS',
        'QUANTITÉ',
        'MONTANT',
