    BILLETS.forEach(
      (item) => {
        const quantity =
          Number(
            fiche[
              item.key
            ],
          )

        worksheet.addRow([
          item.label,
          quantity,
          quantity *
            item.valeur,
        ])
      },
    )

    worksheet.addRow([
      'Total billets',
      '',
      getMontantBillets(
        fiche,
      ),
    ])

    worksheet.addRow([])

    const piecesTitleRow =
      worksheet.addRow([
        'PIÈCES',
        'QUANTITÉ',
        'MONTANT',
      ])

    PIECES.forEach(
      (item) => {
        const quantity =
          Number(
            fiche[
              item.key
            ],
