    worksheet.addRow([
      'Total pièces',
      '',
      getMontantPieces(
        fiche,
      ),
    ])

    worksheet.addRow([
      'TOTAL ESPÈCES',
      '',
      getMontantEspeces(
        fiche,
      ),
    ])

    worksheet.addRow([])

    const encaissementTitle =
      worksheet.addRow([
        'ENCAISSEMENTS',
        'NOMBRE',
        'MONTANT',
      ])

    worksheet.addRow([
      'Chèques',
      fiche.nbCheques,
      fiche.montantCheques,
    ])

    worksheet.addRow([
      'TPE',
      fiche.nbTpe,
      fiche.montantTpe,
    ])

    worksheet.addRow([
      'Virement',
      '',
      fiche.montantVirement,
    ])

    worksheet.addRow([])

