      'A3',
    ).font = {
      bold: true,
      size: 12,
      color: {
        argb:
          'FFFF8614',
      },
    }

    worksheet.getCell(
      'A5',
    ).font = {
      bold: true,
      size: 14,
      color: {
        argb:
          'FF1F344D',
      },
    }

    ;[
      billetsTitleRow,
      piecesTitleRow,
      encaissementTitle,
      donsTitle,
    ].forEach(
      (row) => {
        row.eachCell(
          (cell) => {
            cell.font = {
              bold: true,
              color: {
                argb:
                  'FFFFFFFF',
              },
            }

            cell.fill = {
              type:
                'pattern',
              pattern:
                'solid',
              fgColor: {
                argb:
                  'FF063B7C',
              },
            }

            cell.alignment = {
              horizontal:
                'center',
              vertical:
                'middle',
            }
          },
        )
      },
    )

    totalRow.eachCell(
      (cell) => {
        cell.font = {
          bold: true,
          size: 13,
          color: {
            argb:
              'FFFF8614',
          },
        }

        cell.fill = {
          type:
            'pattern',
          pattern:
            'solid',
          fgColor: {
            argb:
              'FFFFF3E8',
          },
        }
      },
    )

    worksheet.eachRow(
      (row) => {
        row.height =
          Math.max(
            row.height ||
              15,
            21,
          )

        row.eachCell(
          (cell) => {
            cell.alignment = {
              ...cell.alignment,
              vertical:
                'middle',
            }
          },
        )
      },
    )

    worksheet.getColumn(
      3,
    ).numFmt =
      '#,##0.00 [$€-fr-FR]'

    const buffer =
      await workbook.xlsx.writeBuffer()

    const blob =
      new Blob(
        [
          new Uint8Array(
            buffer,
          ),
        ],
        {
          type:
            'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
        },
      )

    downloadBlob(
      blob,
      `${fiche.numero}_${safeFilename(
        fiche.libelle,
      )}.xlsx`,
    )

    setActionMenuId(
      null,
    )
  }

