        20 par page
      </option>

      <option value="50">
        50 par page
      </option>

      <option value="100">
        100 par page
      </option>

      <option value="infini">
        Infini — tout afficher
      </option>
    </select>

  </div>

  {/* BOUTONS DE NAVIGATION */}

  {pageSize !== 'infini' && pageCount > 1 && (

    <div className="fiches-caisse-pagination-pages">

      {/* PAGE PRÉCÉDENTE */}

      <button
        type="button"
        aria-label="Page précédente"
        disabled={currentPage === 1}
        onClick={() =>
          setPage(current =>
            Math.max(1, current - 1),
          )
        }
      >
        <ChevronLeft size={17} />
      </button>

      {/* NUMÉROS DES PAGES */}

      {pageButtons.map(number => (

        <button
          key={number}
          type="button"
          aria-label={`Page ${number}`}
          aria-current={
            number === currentPage
              ? 'page'
              : undefined
          }
          className={
            number === currentPage
              ? 'active'
              : ''
          }
          onClick={() => setPage(number)}
        >
          {number}
        </button>

      ))}

      {/* PAGE SUIVANTE */}

      <button
        type="button"
        aria-label="Page suivante"
        disabled={currentPage === pageCount}
        onClick={() =>
          setPage(current =>
            Math.min(pageCount, current + 1),
          )
        }
      >
        <ChevronRight size={17} />
      </button>

    </div>

  )}

</nav>


      </section>

      {/* =================================================
          DETAIL
      ================================================= */}

      {detailFiche && (
        <FicheDetailModal
          fiche={
            detailFiche
          }
          onClose={() =>
            setDetailFiche(
              null,
            )
          }
          onEdit={() =>
            openEditModal(
              detailFiche,
            )
          }
          onPdf={() =>
            void exportSingleFichePdf(
              detailFiche,
            )
          }
          onExcel={() =>
            void exportSingleFicheExcel(
              detailFiche,
            )
          }
        />
      )}

      {/* =================================================
          CREATION / MODIFICATION
      ================================================= */}

      {modalOpen && (
        <FicheCaisseModal
          mode={
            modalMode
          }
          fiche={
            editingFiche
          }
          fiches={
            fichesCaisse
          }
          commandes={commandes}
          getDonateurById={getDonateurById}
          campagneActive={activeCampagne?.id ?? ''}
          onClose={() => {
            setModalOpen(
              false,
            )

            setEditingFiche(
              null,
            )
          }}
          onSave={
            saveFiche
          }
        />
      )}

    </div>
  )
}

