/* =========================================================
   MODALE CREATION / MODIFICATION
   ========================================================= */

function FicheCaisseModal({
  mode,
  fiche,
  fiches,
  commandes,
  getDonateurById,
  campagneActive,
  onClose,
  onSave,
}: {
  mode: FicheFormMode
  fiche: FicheCaisse | null
  fiches: FicheCaisse[]
  commandes: ReturnType<typeof useObData>['commandes']
  getDonateurById: ReturnType<typeof useObData>['getDonateurById']
  campagneActive: string
  onClose: () => void
  onSave: (fiche: FicheCaisse) => void
}) {
  const [
    form,
    setForm,
  ] =
    useState<FicheCaisse>(
      fiche
        ? {
            ...fiche,
          }
        : createEmptyFiche(
            fiches,
          ),
    )

  const [
    error,
    setError,
  ] = useState('')

  // Les références de commande sont liées à la fiche de caisse (commandeId).
  // On normalise OB2026 / OB 2026 / 2026 pour ne pas mélanger les campagnes.
  const campagneAnnee = (value: string) =>
    String(value || '').match(/(?:19|20)\d{2}/)?.[0] ?? String(value || '').trim().toUpperCase()

  const bonsDeCommande = useMemo(() => {
    const annee = campagneAnnee(form.campagne || campagneActive)
    return commandes
      .filter(commande =>
        commande.statut !== 'ANNULEE' &&
        campagneAnnee(commande.campagne) === annee,
      )
      .sort((a, b) => a.numero.localeCompare(b.numero, 'fr', { numeric: true }))
  }, [commandes, form.campagne, campagneActive])

  function choisirBonDeCommande(value: string) {
    const id = Number(value)
    const commande = bonsDeCommande.find(item => item.id === id)
    if (!commande) {
      setForm(current => ({ ...current, commandeId: undefined, donateurId: undefined }))
      return
    }
    const donateur = getDonateurById(commande.donateurId)
    setForm(current => ({
      ...current,
      type: 'ENTREPRISE',
      commandeId: commande.id,
      donateurId: commande.donateurId,
      campagne: commande.campagne,
      libelle: donateur?.nom ?? current.libelle,
      cp: donateur?.cp ?? current.cp,
      ville: donateur?.ville ?? current.ville,
    }))
  }

  function updateField<
    K extends keyof FicheCaisse,
  >(
    key: K,
    value:
      FicheCaisse[K],
  ) {
    setForm(
      (current) => ({
        ...current,
        [key]:
          value,
      }),
    )
  }

  function updateNumber(
    key:
      NumericFicheField,
    value:
      string,
  ) {
    const number =
      Math.max(
        0,
        Number(value) ||
          0,
      )

    setForm(
      (current) => ({
        ...current,
        [key]:
          number,
      }),
    )
  }

  function submit(
    event:
      FormEvent<HTMLFormElement>,
  ) {
    event.preventDefault()

    setError('')

    if (
      !form.libelle.trim()
    ) {
      setError(
        'Le nom de la structure est obligatoire.',
      )

      return
    }

    if (
      !form.date
    ) {
      setError(
        'La date est obligatoire.',
      )

      return
    }

    onSave({
      ...form,

      libelle:
        form.libelle.trim(),
    })
  }

  const montantBillets =
    getMontantBillets(
      form,
    )

  const montantPieces =
    getMontantPieces(
      form,
    )

  const montantEspeces =
    getMontantEspeces(
      form,
    )

  const montantDons =
    getMontantDons(
      form,
    )

  const total =
    getTotalFiche(
      form,
    )

  return (
    <div className="fiche-modal-overlay">

      <div className="fiche-modal">

        <header className="fiche-modal-header">

          <div>

            <span>
              Fiche de caisse
            </span>

            <h2>
              {mode ===
              'create'
                ? 'Nouvelle fiche'
                : 'Modifier la fiche'}
            </h2>

          </div>

          <button
            type="button"
            className="fiche-modal-close-button"
            onClick={
              onClose
            }
          >
            <X
              size={22}
            />
          </button>

        </header>

        <form
          onSubmit={
            submit
          }
        >

          <div className="fiche-modal-content">

            <FormSection
              title="Identification de la fiche"
            >

              <div className="fiche-form-grid">

                <FormField
                  label="N° de fiche"
                >
                  <input
                    value={
                      form.numero
                    }
                    onChange={(
                      event,
                    ) =>
                      updateField(
                        'numero',
                        event.target.value,
                      )
                    }
                  />
                </FormField>

                <FormField
                  label="Date"
                >
                  <input
                    type="date"
                    value={
                      form.date
                    }
                    onChange={(
                      event,
                    ) =>
                      updateField(
                        'date',
                        event.target.value,
                      )
                    }
                  />
                </FormField>

                <FormField
                  label="Type"
                >
                  <select
                    value={
                      form.type
                    }
                    onChange={(
                      event,
                    ) =>
                      setForm(current => ({
                        ...current,
                        type: event.target.value as TypeFicheCaisse,
                        ...(event.target.value === 'ENTREPRISE'
                          ? {}
                          : { commandeId: undefined, donateurId: undefined }),
                      }))
                    }
                  >
                    <option value="ENTREPRISE">
                      Entreprise
                    </option>

                    <option value="MAIRIE">
                      Mairie
                    </option>

                    <option value="ETABLISSEMENT">
                      Établissement
                    </option>

                    <option value="STAND">
                      Stand
                    </option>

                    <option value="AUTRE">
                      Autre
                    </option>
                  </select>
                </FormField>

                <FormField
                  label="Campagne"
                >
                  <input
                    value={
                      form.campagne
                    }
                    onChange={(
                      event,
                    ) =>
                      setForm(current => ({
                        ...current,
                        campagne: event.target.value,
                        commandeId: undefined,
                        donateurId: undefined,
                      }))
                    }
                  />
                </FormField>

                {form.type === 'ENTREPRISE' && (
                  <FormField label="Bon de commande entreprise" wide>
                    <select
                      value={form.commandeId ?? ''}
                      onChange={event => choisirBonDeCommande(event.target.value)}
                      aria-label="Sélectionner un bon de commande entreprise"
                    >
                      <option value="">— Sélectionner un bon de commande —</option>
                      {bonsDeCommande.map(commande => {
                        const donateur = getDonateurById(commande.donateurId)
                        const montant = Number(commande.quantite || 0) * Number(commande.prixUnitaire || 0)
                        return (
                          <option key={commande.id} value={commande.id}>
                            {commande.numero} · {donateur?.nom ?? 'Donateur inconnu'} · {commande.quantite} brioches · {montant.toLocaleString('fr-FR', { style: 'currency', currency: 'EUR' })}
                          </option>
                        )
                      })}
                    </select>
                    <small className="fiche-commande-hint">
                      {bonsDeCommande.length === 0
                        ? 'Aucun bon de commande actif pour cette campagne.'
                        : 'Choisis la commande pour relier automatiquement cette fiche de caisse au suivi des règlements.'}
                    </small>
                  </FormField>
                )}

                <FormField
                  label="Structure / Nom"
                  wide
                >
                  <input
                    value={
                      form.libelle
                    }
                    onChange={(
                      event,
                    ) =>
                      updateField(
                        'libelle',
                        event.target.value,
                      )
                    }
                  />
                </FormField>

                <FormField
                  label="Code postal"
                >
                  <input
                    value={
                      form.cp ||
                      ''
                    }
                    onChange={(
                      event,
                    ) =>
                      updateField(
                        'cp',
                        event.target.value,
                      )
                    }
                  />
                </FormField>

                <FormField
                  label="Ville"
                >
                  <input
                    value={
                      form.ville ||
                      ''
                    }
                    onChange={(
                      event,
                    ) =>
                      updateField(
                        'ville',
                        event.target.value,
                      )
                    }
                  />
                </FormField>

                <FormField
                  label="Secteur"
                  wide
                >
                  <input
                    value={
                      form.secteur ||
                      ''
                    }
                    onChange={(
                      event,
                    ) =>
                      updateField(
                        'secteur',
                        event.target.value,
                      )
                    }
                  />
                </FormField>

              </div>

            </FormSection>

            <FormSection
              title="Comptage des espèces"
            >

              <div className="fiche-cash-columns">

                <div className="fiche-cash-column">

                  <div className="fiche-cash-column-title">

                    <Banknote
                      size={21}
                    />

                    <span>
                      Billets
                    </span>

                    <strong>
                      {formatMoney(
                        montantBillets,
                      )}
                    </strong>

                  </div>

                  {BILLETS.map(
                    (
                      item,
                    ) => (
                      <CashInput
                        key={
                          item.key
                        }
                        label={
                          item.label
                        }
                        value={Number(
                          form[
                            item.key
                          ],
                        )}
                        total={
                          Number(
                            form[
                              item.key
                            ],
                          ) *
                          item.valeur
                        }
                        onChange={(
                          value,
                        ) =>
                          updateNumber(
                            item.key,
                            value,
                          )
                        }
                      />
                    ),
                  )}

                </div>

                <div className="fiche-cash-column">

                  <div className="fiche-cash-column-title">

                    <Coins
                      size={21}
                    />

                    <span>
                      Pièces
                    </span>

                    <strong>
                      {formatMoney(
                        montantPieces,
                      )}
                    </strong>

                  </div>

                  {PIECES.map(
                    (
                      item,
                    ) => (
                      <CashInput
                        key={
                          item.key
                        }
                        label={
                          item.label
                        }
                        value={Number(
                          form[
                            item.key
                          ],
                        )}
                        total={
                          Number(
                            form[
                              item.key
                            ],
                          ) *
                          item.valeur
                        }
                        onChange={(
                          value,
                        ) =>
                          updateNumber(
                            item.key,
                            value,
                          )
                        }
                      />
                    ),
                  )}

                </div>

              </div>

              <div className="fiche-cash-total">

                <span>
                  Total espèces
                </span>

                <strong>
                  {formatMoney(
                    montantEspeces,
                  )}
                </strong>

              </div>

            </FormSection>

            <FormSection
              title="Autres encaissements"
            >

              <div className="fiche-payment-grid">

                <PaymentCard
                  icon={
                    <Check
                      size={21}
                    />
                  }
                  title="Chèques"
                >

                  <FormField
                    label="Nombre de chèques"
                  >
                    <input
                      type="number"
                      min="0"
                      value={
                        form.nbCheques
