/* =========================================================
   CALCULS
   ========================================================= */

function getMontantBillets(
  fiche: FicheCaisse,
) {
  return (
    fiche.billets100 *
      100 +
    fiche.billets50 *
      50 +
    fiche.billets20 *
      20 +
    fiche.billets10 *
      10 +
    fiche.billets5 *
      5
  )
}

function getMontantPieces(
  fiche: FicheCaisse,
) {
  return (
    fiche.pieces2 *
      2 +
    fiche.pieces1 +
    fiche.pieces050 *
      0.5 +
    fiche.pieces020 *
      0.2 +
    fiche.pieces010 *
      0.1 +
    fiche.pieces005 *
      0.05 +
    fiche.pieces002 *
      0.02 +
    fiche.pieces001 *
      0.01
  )
}

function getMontantEspeces(
  fiche: FicheCaisse,
) {
  return (
    getMontantBillets(
      fiche,
    ) +
    getMontantPieces(
      fiche,
    )
  )
}

function getMontantDons(
  fiche: FicheCaisse,
) {
  return (
    fiche.nbDons5 *
      5 +
    fiche.nbDons3 *
      3 +
    fiche.montantDonsAutres
  )
}

function getTotalFiche(
  fiche: FicheCaisse,
) {
  return (
    getMontantEspeces(
      fiche,
    ) +
    fiche.montantCheques +
    fiche.montantTpe +
    fiche.montantVirement +
    getMontantDons(
      fiche,
    )
  )
}

/* =========================================================
   TRI
   ========================================================= */

function getSortValue(
  fiche: FicheCaisse,
  key: SortKey,
):
  | string
  | number {
  switch (key) {
    case 'numero':
      return fiche.numero

    case 'date':
      return fiche.date

    case 'type':
      return fiche.type

    case 'libelle':
      return fiche.libelle

    case 'ville':
      return (
        fiche.ville ||
        ''
      )

    case 'secteur':
      return (
        fiche.secteur ||
        ''
      )

    case 'especes':
      return getMontantEspeces(
        fiche,
      )

    case 'cheques':
      return fiche.montantCheques

    case 'tpe':
      return fiche.montantTpe

    case 'virement':
      return fiche.montantVirement

    case 'dons':
      return getMontantDons(
        fiche,
      )

    case 'total':
      return getTotalFiche(
        fiche,
      )
  }
}

/* =========================================================
   CREATION D'UNE FICHE VIDE
   ========================================================= */

function createEmptyFiche(
  fiches: FicheCaisse[],
): FicheCaisse {
  const year =
    new Date().getFullYear()

  return {
    id:
      Math.max(
        0,
        ...fiches.map(
          (fiche) =>
            fiche.id,
        ),
      ) + 1,

    numero:
      createFicheNumber(
        fiches,
      ),

    campagne:
      `OB ${year}`,

    date:
      getTodayInput(),

    type:
      'ENTREPRISE',

    libelle: '',

    ville: '',

    cp: '',

    secteur: '',

    billets100: 0,
    billets50: 0,
    billets20: 0,
    billets10: 0,
    billets5: 0,

    pieces2: 0,
    pieces1: 0,
    pieces050: 0,
    pieces020: 0,
    pieces010: 0,
    pieces005: 0,
    pieces002: 0,
    pieces001: 0,

    nbCheques: 0,

    montantCheques: 0,

    nbTpe: 0,

    montantTpe: 0,

    montantVirement: 0,

    nbDons5: 0,

    nbDons3: 0,

    montantDonsAutres: 0,

    remarque: '',
    statutCoffre: 'A_CONTROLER',
  }
}

function createFicheNumber(
  fiches: FicheCaisse[],
) {
  const year =
    new Date().getFullYear()

  const next =
    Math.max(
      0,
      ...fiches.map(
        (fiche) => {
          const match =
            fiche.numero.match(
              /(\d+)$/,
            )

          return match
            ? Number(
                match[1],
              )
            : 0
        },
      ),
    ) + 1

  return `FC-${year}-${String(
    next,
  ).padStart(
    4,
    '0',
  )}`
}

