/* =========================================================
   FORMATAGE
   ========================================================= */

function formatType(
  type:
    TypeFicheCaisse,
) {
  switch (type) {
    case 'ENTREPRISE':
      return 'Entreprise'

    case 'MAIRIE':
      return 'Mairie'

    case 'ETABLISSEMENT':
      return 'Établissement'

    case 'STAND':
      return 'Stand'

    case 'AUTRE':
      return 'Autre'
  }
}

function formatMoney(
  value: number,
) {
  return new Intl.NumberFormat(
    'fr-FR',
    {
      style:
        'currency',
      currency:
        'EUR',
    },
  ).format(
    value,
  )
}

function formatMoneyPdf(
  value: number,
) {
  return formatMoney(
    value,
  ).replace(
    /[\u00A0\u202F]/g,
    ' ',
  )
}

function formatDate(
  value: string,
) {
  if (
    !value
  ) {
    return '-'
  }

  const [
    year,
    month,
    day,
  ] =
    value.split('-')

  if (
    !year ||
    !month ||
    !day
  ) {
    return value
  }

  return `${day}/${month}/${year}`
}

function getTodayInput() {
  const date =
    new Date()

  const year =
    date.getFullYear()

  const month =
    String(
      date.getMonth() +
        1,
    ).padStart(
      2,
      '0',
    )

  const day =
    String(
      date.getDate(),
    ).padStart(
      2,
      '0',
    )

  return `${year}-${month}-${day}`
}

