/* =========================================================
   CHARGEMENT DES LOGOS
   ========================================================= */

async function loadImageAsDataUrl(
  url: string,
): Promise<string> {
  const response =
    await fetch(
      url,
    )

  if (
    !response.ok
  ) {
    throw new Error(
      `Impossible de charger l'image : ${url}`,
    )
  }

  const blob =
    await response.blob()

  return new Promise(
    (
      resolve,
      reject,
    ) => {
      const reader =
        new FileReader()

      reader.onloadend =
        () => {
          if (
            typeof reader.result ===
            'string'
          ) {
            resolve(
              reader.result,
            )
          } else {
            reject(
              new Error(
                'Conversion du logo impossible.',
              ),
            )
          }
        }

      reader.onerror =
        () => {
          reject(
            new Error(
              'Lecture du logo impossible.',
            ),
          )
        }

      reader.readAsDataURL(
        blob,
      )
    },
  )
}

/* =========================================================
   TELECHARGEMENT
   ========================================================= */

function downloadBlob(
  blob: Blob,
  filename: string,
) {
  const url =
    URL.createObjectURL(
      blob,
    )

  const link =
    document.createElement(
      'a',
    )

  link.href =
    url

  link.download =
    filename

  document.body.appendChild(
    link,
  )

  link.click()

  link.remove()

  URL.revokeObjectURL(
    url,
  )
}

