function buildFeatureCollection(
  points: GeoSalePoint[],
  metric: GeoMetric,
) {
  return {
    type: 'FeatureCollection',
    features: points
      .filter(
        (point) =>
          point.longitude !== null &&
          point.latitude !== null,
      )
      .map((point) => ({
        type: 'Feature',
        geometry: {
          type: 'Point',
          coordinates: [
            point.longitude as number,
            point.latitude as number,
          ],
        },
        properties: {
          id: point.id,
          name: point.name,
          city: point.city,
          sector: point.sector,
          channel: point.channel,
          channelLabel: CHANNEL_LABELS[point.channel],
          channelColor: CHANNEL_COLORS[point.channel],
          sold: point.sold ?? 0,
          donations: point.donations,
          entrusted: point.entrusted ?? 0,
          metricValue: metricValue(point, metric),
          estimated: point.estimatedSold ? 1 : 0,
        },
      })),
  }
}

function buildSectorCollection(
  sectors: GeoSectorSummary[],
  metric: GeoMetric,
) {
  return {
    type: 'FeatureCollection',
    features: sectors
      .filter(
        (sector) =>
          sector.longitude !== null &&
          sector.latitude !== null,
      )
      .map((sector) => ({
        type: 'Feature',
        geometry: {
          type: 'Point',
          coordinates: [
            sector.longitude as number,
            sector.latitude as number,
          ],
        },
        properties: {
          id: sector.sector,
          sector: sector.sector,
          sold: sector.sold,
          donations: sector.donations,
          flow: sector.flow ?? 0,
          points: sector.points,
          metricValue:
            metric === 'DONATIONS'
              ? sector.donations
              : metric === 'FLOW'
                ? sector.flow ?? 0
                : metric === 'POINTS'
                  ? sector.points
                  : sector.sold,
        },
      })),
  }
}

type DepartmentFeature = {
  type: 'Feature'
  geometry: unknown
  properties: {
    code: string
    nom: string
    color: string
  }
}

type GenericGeoJsonFeature = {
  type?: unknown
  geometry?: unknown
  properties?: Record<string, unknown>
}

function departmentDefinition(code: string) {
  return DEPARTMENT_DEFINITIONS.find(
    (item) => item.code === code,
  )
}

function normalizeDepartmentFeature(
  feature: GenericGeoJsonFeature,
): DepartmentFeature | null {
  if (
    feature.type !== 'Feature' ||
    !feature.geometry ||
    !feature.properties
  ) {
    return null
  }

  const code = String(
    feature.properties.code ??
      feature.properties.codeDepartement ??
      feature.properties.dep ??
      '',
  ).trim()

  const definition = departmentDefinition(code)

  if (!definition) {
    return null
  }

  return {
    type: 'Feature',
    geometry: feature.geometry,
    properties: {
      code: definition.code,
      nom: definition.name,
      color: definition.color,
    },
  }
}

function extendBoundsFromCoordinates(
  bounds: maplibregl.LngLatBounds,
  coordinates: unknown,
) {
  if (!Array.isArray(coordinates)) {
    return
  }

  if (
    coordinates.length >= 2 &&
    typeof coordinates[0] === 'number' &&
    typeof coordinates[1] === 'number'
  ) {
    bounds.extend([
      coordinates[0],
      coordinates[1],
    ])

    return
  }

  for (const child of coordinates) {
    extendBoundsFromCoordinates(
      bounds,
      child,
    )
  }
}

function fitDepartments(
  map: MapLibreMap,
  features: DepartmentFeature[],
) {
  const bounds =
    new maplibregl.LngLatBounds()

  for (const feature of features) {
    const geometry =
      feature.geometry as
        | {
            coordinates?: unknown
          }
        | undefined

    if (geometry?.coordinates) {
      extendBoundsFromCoordinates(
        bounds,
        geometry.coordinates,
      )
    }
  }

  if (!bounds.isEmpty()) {
    map.fitBounds(bounds, {
      padding: {
        top: 105,
        right: 55,
        bottom: 55,
        left: 55,
      },
      duration: 900,
      maxZoom: 9.2,
    })
  }
}

async function fetchDepartmentsGeoJson() {
  let lastError: unknown = null

  for (const url of DEPARTMENTS_GEOJSON_URLS) {
    try {
      const response = await fetch(url)

      if (!response.ok) {
        throw new Error(
          `Contours administratifs indisponibles (${response.status})`,
        )
      }

      const payload = (await response.json()) as {
        type?: unknown
        features?: GenericGeoJsonFeature[]
      }

      if (
        payload.type !== 'FeatureCollection' ||
        !Array.isArray(payload.features)
      ) {
        throw new Error(
          'Le fichier de contours ne contient pas une FeatureCollection valide.',
        )
      }

      return payload.features
    } catch (error) {
      lastError = error
    }
  }

  throw lastError ??
    new Error(
      'Impossible de charger les contours administratifs.',
    )
}

