import { useEffect, useMemo, useState, type FormEvent } from 'react'
import { AlertCircle, CheckCircle2, ClipboardList, Plus, ShieldAlert, Users } from 'lucide-react'
import { getUserDisplayName, POLE_LABELS, useUsers, type UserPole } from '../contexts/UsersContext'
import './GestionMonEquipe.css'

type Priority = 'normale' | 'haute' | 'urgente'
type TaskStatus = 'a_faire' | 'en_cours' | 'terminee'
type TeamTask = {
  id: string; pole: UserPole; authorId: string; assigneeId: string
  title: string; description: string; priority: Priority; status: TaskStatus; createdAt: string
}
const STORAGE_KEY = 'ob-team-alerts-v1'
function loadTasks(): TeamTask[] {
  try {
    const value = JSON.parse(localStorage.getItem(STORAGE_KEY) || '[]')
    if (!Array.isArray(value)) return []
    return value.filter((task): task is TeamTask => task && typeof task.id === 'string' && typeof task.title === 'string' && typeof task.assigneeId === 'string' && (task.pole === 'comptabilite' || task.pole === 'communication') && ['normale','haute','urgente'].includes(task.priority) && ['a_faire','en_cours','terminee'].includes(task.status))
  } catch { return [] }
}
const statusLabels: Record<TaskStatus, string> = {a_faire:'À faire', en_cours:'En cours', terminee:'Terminée'}
const priorityLabels: Record<Priority, string> = {normale:'Normale', haute:'Haute', urgente:'Urgente'}

export default function GestionMonEquipe() {
  const { users, currentUser } = useUsers()
  const pole = currentUser?.pole
  const isManager = Boolean(currentUser && currentUser.status === 'actif' && currentUser.responsablePole && pole)
  const members = useMemo(() => users.filter(u => u.status === 'actif' && u.pole === pole), [users, pole])
  const [tasks, setTasks] = useState<TeamTask[]>(loadTasks)
  const [title, setTitle] = useState('')
  const [description, setDescription] = useState('')
  const [assigneeId, setAssigneeId] = useState('')
  const [priority, setPriority] = useState<Priority>('normale')
  const [filter, setFilter] = useState('tous')
  const [error, setError] = useState('')
  useEffect(() => { try {localStorage.setItem(STORAGE_KEY, JSON.stringify(tasks))} catch { /* browser storage unavailable */ } }, [tasks])
  useEffect(() => { if (!members.some(m => m.id === assigneeId)) setAssigneeId('') }, [members,assigneeId])
  const teamTasks = tasks.filter(t => t.pole === pole)
  const displayed = teamTasks.filter(t => filter === 'tous' || t.assigneeId === filter)
  function createTask(e: FormEvent<HTMLFormElement>) {
    e.preventDefault()
    if (!isManager || !currentUser || !pole) return
    if (!title.trim() || !members.some(u=>u.id === assigneeId)) {setError('Indique une alerte et un membre de ton équipe.'); return}
    setTasks(old => [{id:crypto.randomUUID(), pole, authorId:currentUser.id, assigneeId, title:title.trim(), description:description.trim(), priority, status:'a_faire', createdAt:new Date().toISOString()},...old])
    setTitle('');setDescription('');setPriority('normale');setError('')
  }
  function updateTask(id:string, change:Partial<Pick<TeamTask,'assigneeId'|'priority'|'status'>>) {
    if (!isManager) return
    if (change.assigneeId && !members.some(u=>u.id === change.assigneeId)) return
    setTasks(old => old.map(t => t.id === id && t.pole === pole ? {...t,...change}:t))
  }
  if (!isManager || !pole) return null
  return <section className="ob-team" aria-label="Gestion de mon équipe">
    <header className="ob-team-header"><div><h2><Users size={22}/> Gestion de mon équipe</h2><p>Équipe {POLE_LABELS[pole]} · Attribution des alertes et priorités</p></div><span className="ob-team-count">{members.length} membre{members.length>1?'s':''}</span></header>
    <div className="ob-team-members">
      {members.map(u=><div className="ob-team-member" key={u.id}><span className="ob-team-avatar">{(u.prenom || u.name).trim().slice(0,1).toUpperCase()}</span><span><strong>{getUserDisplayName(u)}</strong><small>{u.poste || (u.responsablePole ? 'Responsable de pôle' : 'Membre de l’équipe')}</small></span><span className="ob-team-member-count">{teamTasks.filter(t=>t.assigneeId===u.id&&t.status!=='terminee').length} en cours</span></div>)}
      {members.length===0 && <p>Aucun membre actif dans ce pôle.</p>}
    </div>
    <div className="ob-team-layout">
      <section className="ob-team-panel"><h3><Plus size={18}/> Créer une alerte pour l’équipe</h3>
        <form onSubmit={createTask} className="ob-team-form">
          <label>Objet de l’alerte<input value={title} onChange={e=>setTitle(e.target.value)} placeholder="Ex. Vérifier les stands sans bénévole" maxLength={160} required/></label>
          <label>Attribuer à<select value={assigneeId} onChange={e=>setAssigneeId(e.target.value)} required><option value="">Choisir un membre</option>{members.map(u=><option key={u.id} value={u.id}>{getUserDisplayName(u)}</option>)}</select></label>
          <label>Priorité<select value={priority} onChange={e=>setPriority(e.target.value as Priority)}><option value="normale">Normale</option><option value="haute">Haute</option><option value="urgente">Urgente</option></select></label>
          <label>Consignes (facultatif)<textarea value={description} onChange={e=>setDescription(e.target.value)} rows={3} placeholder="Informations utiles pour la personne concernée"/></label>
          {error && <p className="ob-team-error" role="alert">{error}</p>}
          <button type="submit" className="ob-team-button"><Plus size={16}/> Attribuer l’alerte</button>
        </form>
      </section>
      <section className="ob-team-panel"><div className="ob-team-list-heading"><h3><ClipboardList size={18}/> Alertes de l’équipe</h3><select aria-label="Filtrer les alertes par personne" value={filter} onChange={e=>setFilter(e.target.value)}><option value="tous">Toute l’équipe</option>{members.map(u=><option value={u.id} key={u.id}>{getUserDisplayName(u)}</option>)}</select></div>
        {displayed.length===0 ? <div className="ob-team-empty"><CheckCircle2 size={24}/><p>Aucune alerte attribuée pour ce filtre.</p></div> : <div className="ob-team-tasks">{displayed.map(task=><article className="ob-team-task" key={task.id}>
          <div className="ob-team-task-top"><strong>{task.priority==='urgente'?<ShieldAlert size={16}/>:<AlertCircle size={16}/>} {task.title}</strong><span className={'ob-team-priority ob-team-priority-'+task.priority}>{priorityLabels[task.priority]}</span></div>
          {task.description&&<p>{task.description}</p>}
          <div className="ob-team-task-controls"><label>Attribuée à<select aria-label={'Responsable de '+task.title} value={task.assigneeId} onChange={e=>updateTask(task.id,{assigneeId:e.target.value})}>{members.map(u=><option value={u.id} key={u.id}>{getUserDisplayName(u)}</option>)}</select></label>
          <label>Priorité<select aria-label={'Priorité de '+task.title} value={task.priority} onChange={e=>updateTask(task.id,{priority:e.target.value as Priority})}><option value="normale">Normale</option><option value="haute">Haute</option><option value="urgente">Urgente</option></select></label>
          <label>Statut<select aria-label={'Statut de '+task.title} value={task.status} onChange={e=>updateTask(task.id,{status:e.target.value as TaskStatus})}>{(Object.keys(statusLabels) as TaskStatus[]).map(s=><option key={s} value={s}>{statusLabels[s]}</option>)}</select></label></div>
        </article>)}</div>}
      </section>
    </div>
    <p className="ob-team-note">Première version : ces alertes sont créées manuellement et stockées dans ce navigateur. Les alertes automatiques des modules et la synchronisation sécurisée entre collègues nécessitent une base de données et des contrôles d’accès côté serveur.</p>
  </section>
}

import { useMemo, useState, type ChangeEvent } from 'react'
import { Download, FileSpreadsheet, Upload, X, AlertTriangle, CheckCircle2 } from 'lucide-react'
import type { EtablissementAEIM, NouvelEtablissementAEIM } from '../types/etablissements'
import { useEtablissements } from '../contexts/EtablissementsContext'
import './ImportEtablissementsExcel.css'

type Field = keyof NouvelEtablissementAEIM
const FIELDS: Field[] = [
  'code','nom','type','statut','adresse','codePostal','ville','telephone','email',
  'responsableNom','responsableTelephone','responsableEmail','secteur','pole',
  'participeOperationBrioches','peutEffectuerLivraisons','peutRecevoirStock',
  'peutVendreBrioches','roleOperationBrioches','commentaire'
]
const LABELS: Partial<Record<Field,string>> = {
  code:'Code établissement', nom:'Nom', type:'Type', statut:'Statut',adresse:'Adresse',
  codePostal:'Code postal',ville:'Ville',telephone:'Téléphone',email:'Email',
  responsableNom:'Responsable', responsableTelephone:'Téléphone responsable',
  responsableEmail:'Email responsable',secteur:'Secteur',pole:'Pôle',
  participeOperationBrioches:'Participe opération brioches',
  peutEffectuerLivraisons:'Peut effectuer livraisons',peutRecevoirStock:'Peut recevoir stock',
  peutVendreBrioches:'Peut remettre brioches',roleOperationBrioches:'Rôle opération',commentaire:'Commentaire'
}
const DEFAULT: NouvelEtablissementAEIM = {
  code:'',nom:'',type:'AUTRE',statut:'ACTIF',adresse:'',codePostal:'',ville:'',telephone:'',email:'',
  responsableNom:'',responsableTelephone:'',responsableEmail:'',secteur:'',pole:'',rattachementId:'',
  participeOperationBrioches:true,peutEffectuerLivraisons:false,peutRecevoirStock:false,
  peutVendreBrioches:false,roleOperationBrioches:'',commentaire:''
}
const BOOL_FIELDS = new Set<Field>(['participeOperationBrioches','peutEffectuerLivraisons','peutRecevoirStock','peutVendreBrioches'])
const TYPES = new Set(['SIEGE','ESAT','IME','MAS','FAM','FOYER','SAJ','SAVS','EAM','SESSAD','AUTRE'])
const norm = (s:string) => s.trim().normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]/g,'')
const cellText = (value:unknown):string => {
  if (value == null) return ''
  if (typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean') return String(value).trim()
  if (typeof value === 'object') {
    const o = value as Record<string,unknown>
    if ('result' in o) return cellText(o.result)
    if ('text' in o) return cellText(o.text)
    if (Array.isArray(o.richText)) return o.richText.map((p:any)=>cellText(p.text)).join('')
  }
  return ''
}
function parseBoolean(value:string): boolean|null {
  const v = norm(value)
  if (['oui','o','true','vrai','1','yes'].includes(v)) return true
  if (['non','n','false','faux','0','no'].includes(v)) return false
  return null
}
type ImportRow = {line:number;code:string;nom:string;status:'creation'|'modification'|'inchange'|'erreur';reason:string;changes:Partial<NouvelEtablissementAEIM>;original?:EtablissementAEIM}
export default function ImportEtablissementsExcel({onClose}:{onClose:()=>void}) {
  const {etablissements,setEtablissements} = useEtablissements()
  const [rows,setRows] = useState<ImportRow[]>([])
  const [fileName,setFileName] = useState('')
  const [busy,setBusy] = useState(false)
  const [error,setError] = useState('')
  const [complete,setComplete] = useState('')
  const counts = useMemo(()=>({creation:rows.filter(r=>r.status==='creation').length,modification:rows.filter(r=>r.status==='modification').length,inchange:rows.filter(r=>r.status==='inchange').length,erreur:rows.filter(r=>r.status==='erreur').length}),[rows])
  async function downloadTemplate() {
    const ExcelJS = (await import('exceljs')).default
    const book = new ExcelJS.Workbook()
    const sheet = book.addWorksheet('Établissements')
    sheet.addRow(FIELDS.map(k=>LABELS[k]||k))
    sheet.addRow(['ET001','ESAT Exemple','ESAT','ACTIF','1 rue Exemple','54000','Nancy','0383000000','contact@exemple.fr'])
    sheet.getRow(1).font={bold:true,color:{argb:'FFFFFFFF'}}
    sheet.getRow(1).fill={type:'pattern',pattern:'solid',fgColor:{argb:'FF153F7B'}}
    sheet.columns.forEach(c=>{c.width=24})
    const binary=await book.xlsx.writeBuffer()
    const url=URL.createObjectURL(new Blob([binary],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}))
    const a=document.createElement('a');a.href=url;a.download='modele_etablissements_OB2026.xlsx';a.click();URL.revokeObjectURL(url)
  }
  async function onFile(event:ChangeEvent<HTMLInputElement>) {
    const file=event.target.files?.[0]
    setError('');setComplete('');setRows([])
    if (!file) return
    setFileName(file.name)
    if (!/\.xlsx$/i.test(file.name)){setError('Utilise un fichier Excel .xlsx.');return}
    setBusy(true)
    try {
      const ExcelJS=(await import('exceljs')).default
      const book=new ExcelJS.Workbook()
      await book.xlsx.load(await file.arrayBuffer() as any)
      const sheet=book.worksheets[0]
      if (!sheet || sheet.rowCount<2) throw new Error('Feuille vide ou sans données.')
      const header=sheet.getRow(1)
      const fieldForColumn=new Map<number,Field>()
      header.eachCell((c,col)=>{
        const text=norm(cellText(c.value))
        const field=FIELDS.find(k=>norm(k)===text || norm(LABELS[k]||'')===text)
        if(field) fieldForColumn.set(col,field)
      })
      if (![...fieldForColumn.values()].includes('code') || ![...fieldForColumn.values()].includes('nom')) throw new Error('Colonnes obligatoires : Code établissement et Nom. Utilise le modèle fourni.')
      const existingCodes=new Map(etablissements.map(e=>[norm(e.code),e]))
      const seen=new Set<string>()
      const imported:ImportRow[]=[]
      sheet.eachRow((r,index)=>{
        if(index===1)return
        const raw:Partial<Record<Field,string>>={}
        fieldForColumn.forEach((field,col)=>{const c=r.getCell(col);const v=cellText(c.text || c.value);if(v!=='')raw[field]=v})
        if(!Object.keys(raw).length)return
        const code=(raw.code||'').trim();const nom=(raw.nom||'').trim()
        const row:ImportRow={line:index,code,nom,status:'erreur',reason:'',changes:{}}
        const key=norm(code)
        if(!code||!nom){row.reason='Code et nom obligatoires';imported.push(row);return}
        if(seen.has(key)){row.reason='Code dupliqué dans le fichier';imported.push(row);return}
        seen.add(key)
        const original=existingCodes.get(key)
        const changes:Partial<NouvelEtablissementAEIM>={}
        let invalid=''
        for(const field of FIELDS){
          const value=raw[field];if(value===undefined)continue
          if(BOOL_FIELDS.has(field)){
            const parsed=parseBoolean(value)
            if(parsed===null){invalid=`Valeur Oui/Non incorrecte : ${LABELS[field]}`;break}
            ;(changes as any)[field]=parsed
          } else if(field==='type') {
            if(!TYPES.has(value.toUpperCase())){invalid=`Type inconnu : ${value}`;break}
            changes.type=value.toUpperCase() as NouvelEtablissementAEIM['type']
          } else if(field==='statut') {
            if(!['ACTIF','INACTIF'].includes(value.toUpperCase())){invalid='Statut attendu : ACTIF ou INACTIF';break}
            changes.statut=value.toUpperCase() as NouvelEtablissementAEIM['statut']
          } else (changes as any)[field]=value
        }
        if(invalid){row.reason=invalid;imported.push(row);return}
        row.changes=changes;row.original=original
        if(!original)row.status='creation'
        else {
          const difference=Object.entries(changes).some(([k,v])=>String((original as any)[k])!==String(v))
          row.status=difference?'modification':'inchange'
        }
        row.reason=row.status==='creation'?'Nouvel établissement':row.status==='modification'?'Mise à jour par code':'Aucun changement'
        imported.push(row)
      })
      if(!imported.length)throw new Error('Aucune ligne exploitable dans le fichier.')
      setRows(imported)
    } catch(e){setError(e instanceof Error?e.message:'Impossible de lire le fichier Excel.')}
    finally{setBusy(false);event.target.value=''}
  }
  function apply() {
    if(counts.erreur){setError('Corrige les lignes en erreur avant de valider. Aucune donnée n’a été modifiée.');return}
    const now=new Date().toISOString()
    const updates=new Map(rows.filter(r=>r.status==='modification').map(r=>[r.original!.id,r.changes]))
    const creations=rows.filter(r=>r.status==='creation').map(r=>({
      ...DEFAULT,...r.changes,id:crypto.randomUUID(),createdAt:now,updatedAt:now
    }))
    // Met à jour les objets existants sans changer leur id ni leurs liens.
    setEtablissements(current=>[
      ...current.map(e=>updates.has(e.id)?{...e,...updates.get(e.id),updatedAt:now}:e),
      ...creations,
    ])
    setComplete(`${counts.creation} création(s), ${counts.modification} mise(s) à jour. Import terminé.`)
    setRows([])
  }
  return <div className="ex-overlay" role="presentation"><section className="ex-dialog" role="dialog" aria-modal="true" aria-label="Importer les établissements">
    <header className="ex-head"><div><h2>Importer des établissements</h2><p>Import Excel avec contrôle des doublons et aperçu préalable.</p></div><button className="ex-icon" onClick={onClose} aria-label="Fermer"><X size={20}/></button></header>
    <div className="ex-body">
      <div className="ex-actions"><label className="ex-upload"><Upload size={18}/> Sélectionner un fichier Excel<input type="file" accept=".xlsx" onChange={onFile}/></label><button className="ex-secondary" onClick={downloadTemplate}><Download size={18}/> Télécharger le modèle</button></div>
      <p className="ex-hint">Le rapprochement est effectué uniquement par <strong>code établissement</strong>. Les champs absents ou vides ne remplacent pas les valeurs existantes. Exporter une sauvegarde de ton référentiel avant tout import important.</p>
      {fileName&&<p className="ex-file"><FileSpreadsheet size={17}/> {fileName}</p>}
      {busy&&<p>Lecture du fichier en cours…</p>}
      {error&&<p className="ex-error"><AlertTriangle size={17}/> {error}</p>}
      {complete&&<p className="ex-success"><CheckCircle2 size={17}/> {complete}</p>}
      {rows.length>0&&<><div className="ex-summary"><span>À créer : <b>{counts.creation}</b></span><span>À mettre à jour : <b>{counts.modification}</b></span><span>Inchangés : <b>{counts.inchange}</b></span><span>Erreurs : <b>{counts.erreur}</b></span></div>
        <div className="ex-table-wrap"><table className="ex-table"><thead><tr><th>Ligne</th><th>Code</th><th>Établissement</th><th>Action</th><th>Observation</th></tr></thead><tbody>{rows.map(r=><tr key={r.line}><td>{r.line}</td><td>{r.code}</td><td>{r.nom}</td><td><span className={`ex-tag ex-${r.status}`}>{r.status}</span></td><td>{r.reason}</td></tr>)}</tbody></table></div>
      </>}
    </div><footer className="ex-foot"><button className="ex-secondary" onClick={onClose}>Fermer</button><button className="ex-confirm" disabled={busy||!rows.length||!!counts.erreur||(!counts.creation&&!counts.modification)} onClick={apply}><CheckCircle2 size={18}/> Confirmer l'import</button></footer>
  </section></div>
}

import { useState, type ChangeEvent } from 'react'
import { FileSpreadsheet, X, Download, Upload } from 'lucide-react'
import type { Fournisseur, TypeFournisseur } from '../types/artisans'
import './ImportFournisseursExcel.css'

type Preview = { row: number; code: string; name: string; kind: 'creation' | 'modification' | 'identique' | 'erreur'; message: string; data?: Fournisseur }
type Props = { fournisseurs: Fournisseur[]; onCommit: (next: Fournisseur[]) => void; onClose: () => void }
const HEADERS = ['Code','Type','Raison sociale','Responsable','Responsable secteur','Adresse','Code postal','Ville','Secteur','Téléphone','Email','SIRET','Tarif 2026','Tarif 2025','Conditions règlement','Commentaires','Statut']
const text = (v: unknown): string => {
  if (v == null) return ''
  if (typeof v === 'object') {
    const obj = v as { text?: string; result?: unknown; richText?: { text: string }[] }
    if (typeof obj.text === 'string') return obj.text.trim()
    if (Array.isArray(obj.richText)) return obj.richText.map(x => x.text).join('').trim()
    if (obj.result !== undefined) return text(obj.result)
  }
  return String(v).trim()
}
const normalize = (v: string) => v.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]/g,'')
const numeric = (v: string): number | null | 'error' => {
  if (!v) return null
  const n = Number(v.replace(/\s/g,'').replace(',','.').replace('€',''))
  return Number.isFinite(n) && n >= 0 ? n : 'error'
}
function download(blob: Blob, filename: string) {
  const u = URL.createObjectURL(blob)
  const a = document.createElement('a'); a.href = u; a.download = filename; a.click()
  setTimeout(() => URL.revokeObjectURL(u), 2000)
}
export default function ImportFournisseursExcel({ fournisseurs, onCommit, onClose }: Props) {
  const [preview, setPreview] = useState<Preview[]>([])
  const [error,setError] = useState('')
  const [busy,setBusy] = useState(false)
  async function template() {
    const ExcelJS = (await import('exceljs')).default
    const wb = new ExcelJS.Workbook(); const sh=wb.addWorksheet('Fournisseurs')
    sh.addRow(HEADERS); sh.getRow(1).font={bold:true}; sh.columns=HEADERS.map(h=>({width:Math.max(17,h.length+4)}))
    sh.addRow(['FRN-000001','ARTISAN','Exemple fournisseur','Contact','','','54000','Nancy','','','','','','','','','ACTIF'])
    download(new Blob([await wb.xlsx.writeBuffer()],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}),'modele-import-fournisseurs.xlsx')
  }
  async function readFile(event: ChangeEvent<HTMLInputElement>) {
    const file=event.target.files?.[0]; if(!file) return
    setError(''); setPreview([]); setBusy(true)
    try {
      if(!/\.xlsx$/i.test(file.name)) throw Error('Utilise un fichier Excel .xlsx (sans macros).')
      if(file.size>8_000_000) throw Error('Fichier trop volumineux (maximum 8 Mo).')
      const ExcelJS=(await import('exceljs')).default
      const wb=new ExcelJS.Workbook(); await wb.xlsx.load(await file.arrayBuffer() as any)
      const sh=wb.worksheets[0]; if(!sh) throw Error('Le classeur ne contient aucune feuille.')
      const keys=new Map<string,number>(); sh.getRow(1).eachCell((cell,col)=>keys.set(normalize(text(cell.value)),col))
      for(const required of ['Code','Type','Raison sociale']) if(!keys.has(normalize(required))) throw Error(`Colonne obligatoire manquante : ${required}. Télécharge le modèle.`)
      const seen = new Set<string>(); const output:Preview[]=[]
      const existing=new Map(fournisseurs.map(f=>[f.id.toUpperCase(),f]))
      for(let i=2;i<=sh.rowCount;i++) {
        const row=sh.getRow(i)
        const val=(key:string)=>text(row.getCell(keys.get(normalize(key))||0).value)
        const code=val('Code'), name=val('Raison sociale'), type=val('Type').toUpperCase()
        if(!code&&!name&&!type) continue
        const invalid=(message:string)=>output.push({row:i,code,name,kind:'erreur',message})
        if(!code||!name||!['GMS','ARTISAN','INDUSTRIEL'].includes(type)) {invalid('Code, raison sociale ou type invalide');continue}
        if(seen.has(code.toUpperCase())) {invalid('Code présent plusieurs fois dans le fichier');continue}
        seen.add(code.toUpperCase())
        const old=existing.get(code.toUpperCase())
        // Empty cells never overwrite existing values.
        const field=(key:string, previous='')=>val(key)||previous
        const price26=numeric(val('Tarif 2026')),price25=numeric(val('Tarif 2025'))
        if(price26==='error'||price25==='error'){invalid('Tarif numérique invalide');continue}
        const statutValue=val('Statut').toUpperCase()
        if(statutValue && !['ACTIF','INACTIF','A_VERIFIER'].includes(statutValue)){invalid('Statut invalide');continue}
        if(!old && fournisseurs.some(f=>normalize(f.nom)===normalize(name))) {invalid('Nom déjà présent avec un autre code : vérification manuelle nécessaire');continue}
        const typed=type as TypeFournisseur
        const updated: Fournisseur={
          id:old?.id||code,type:typed,categories:[typed],nom:name,
          responsable:field('Responsable',old?.responsable),responsableSecteur:field('Responsable secteur',old?.responsableSecteur),
          adresse:field('Adresse',old?.adresse),codePostal:field('Code postal',old?.codePostal),ville:field('Ville',old?.ville),
          secteur:field('Secteur',old?.secteur),telephone:field('Téléphone',old?.telephone),email:field('Email',old?.email),siret:field('SIRET',old?.siret),
          tarif2026:price26===null?old?.tarif2026??null:price26,tarif2025:price25===null?old?.tarif2025??null:price25,
          conditionsReglement:field('Conditions règlement',old?.conditionsReglement),commentaires:field('Commentaires',old?.commentaires),
          statut:(statutValue || old?.statut || 'ACTIF') as Fournisseur['statut'],
        }
        if(old && !val('Type')) updated.type=old.type
        if(old && !val('Type')) updated.categories=old.categories
        const kind=!old?'creation':JSON.stringify(old)===JSON.stringify(updated)?'identique':'modification'
        output.push({row:i,code,name,kind,message:kind==='creation'?'Nouvelle fiche':kind==='modification'?'Fiche existante mise à jour':'Aucune modification',data:updated})
      }
      if(!output.length) throw Error('Aucune ligne exploitable dans ce fichier.')
      setPreview(output)
    } catch(e) {setError(e instanceof Error?e.message:'Impossible de lire ce fichier Excel.')}
    finally {setBusy(false);event.target.value=''}
  }
  function confirm() {
    if(preview.some(p=>p.kind==='erreur')) {setError('Corrige les lignes en erreur avant l’import. Aucune donnée n’a été modifiée.');return}
    const map=new Map(fournisseurs.map(f=>[f.id,f]))
    for(const p of preview) if(p.data) map.set(p.data.id,p.data)
    // Backup before changing local state.
    download(new Blob([JSON.stringify(fournisseurs,null,2)],{type:'application/json'}),`sauvegarde-fournisseurs-${new Date().toISOString().slice(0,10)}.json`)
    onCommit([...map.values()]); onClose()
  }
  return <div className="fi-overlay" role="presentation"><section className="fi-dialog" role="dialog" aria-modal="true" aria-label="Import Excel fournisseurs">
    <header className="fi-head"><h2><FileSpreadsheet size={22}/> Importer des fournisseurs</h2><button type="button" onClick={onClose} aria-label="Fermer"><X size={20}/></button></header>
    <p>Réservé à l’administrateur. Les codes identifient les fiches existantes ; les cellules vides n’effacent pas les valeurs enregistrées. Aucune suppression automatique.</p>
    <div className="fi-actions"><button onClick={template} type="button"><Download size={17}/> Télécharger le modèle</button><label className="fi-upload"><Upload size={17}/>{busy?'Lecture en cours…':'Choisir un fichier .xlsx'}<input type="file" accept=".xlsx" onChange={readFile} disabled={busy}/></label></div>
    {error&&<p role="alert" className="fi-error">{error}</p>}
    {preview.length>0&&<><div className="fi-counts">{(['creation','modification','identique','erreur'] as const).map(k=><span key={k}>{k}: <strong>{preview.filter(r=>r.kind===k).length}</strong></span>)}</div><div className="fi-table"><table><thead><tr><th>Ligne</th><th>Code</th><th>Fournisseur</th><th>Résultat</th></tr></thead><tbody>{preview.map(r=><tr key={r.row}><td>{r.row}</td><td>{r.code}</td><td>{r.name}</td><td className={'fi-'+r.kind}>{r.message}</td></tr>)}</tbody></table></div><button className="fi-confirm" type="button" disabled={preview.some(r=>r.kind==='erreur')||busy} onClick={confirm}>Confirmer l’import ({preview.filter(r=>r.kind==='creation'||r.kind==='modification').length} changements)</button></>}
  </section></div>
}

import { useRef, useState, type ChangeEvent, type DragEvent } from 'react'
import { FileUp, X, ArrowRight, ArrowLeft, Check, AlertTriangle } from 'lucide-react'
import type { CommandeArtisan, Fournisseur } from '../types/artisans'
import { argent, montantCommande } from '../types/artisans'
import pdfWorkerUrl from 'pdfjs-dist/legacy/build/pdf.worker.min.mjs?url'
import './ImportSelectionCegi.css'
import { conserverCegi } from '../lib/cegiDocuments'

export type CegiOperation = {
  id: string
  source: string
  beneficiaire: string
  compte: string
  piece: string
  libelle: string
  datePiece: string
  echeance: string
  montant: number
  mode: string
  referenceListe: string
  categorie: 'ACHAT_BRIOCHES' | 'TRANSPORT' | 'COMMUNICATION' | 'MATERIEL' | 'AUTRE'
  fournisseurId: string
  commandeIds: string[]
  traitement: 'a_verifier' | 'ignoree'
}

type Props = {
  fournisseurs: Fournisseur[]
  commandes: CommandeArtisan[]
  onClose: () => void
  onSave: (operation: CegiOperation) => string | null
  onArchived?: () => void
}
const cat: Record<CegiOperation['categorie'], string> = { ACHAT_BRIOCHES: 'Achats de brioches', TRANSPORT: 'Transport / logistique', COMMUNICATION: 'Communication', MATERIEL: 'Matériel', AUTRE: 'Autre dépense' }
const norm = (v:string) => v.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]/g,'')
const amount = (v:string) => Number(v.replace(/\s/g,'').replace(',','.'))
const toISO = (v:string) => { const m = /^(\d{2})\/(\d{2})\/(\d{4})$/.exec(v); return m ? `${m[3]}-${m[2]}-${m[1]}` : '' }
const opId = (source:string, row:string) => `${source}:${row}`
const somme = (items:CegiOperation[]) => Math.round(items.reduce((v,o)=>v+o.montant,0)*100)/100
const formatMoney = (v:number) => new Intl.NumberFormat('fr-FR',{style:'currency',currency:'EUR'}).format(v)

// Recherche ciblée sur les sélections de virement CEGI. Chaque ligne est revalidée par l'utilisateur.
export function analyserSelectionCegi(text:string, source:string): CegiOperation[] {
  const lines=text.split(/\r?\n/).map(s=>s.replace(/\s+/g,' ').trim()).filter(Boolean)
  const joined=lines.join('\n')
  const ref=/Pi[eè]ce\s*n[°o]?\s*([\w\-/]+)/i.exec(joined)?.[1] ?? ''
  const operations:CegiOperation[]=[]
  let dernierBeneficiaire=''
  let dernierCompte=''
  for(let i=0;i<lines.length;i++) {
    const line=lines[i]
    const identity=/^([A-Z]?\d{6,})\s+(.{3,})$/.exec(line)
    if(identity && !/\bTOTAL\b|\bBANQUE\b/i.test(identity[2])) { dernierCompte=identity[1]; dernierBeneficiaire=identity[2]; continue }
    // Date pièce, pièce comptable, libellé, référence, date d'échéance, dossier et crédit.
    const match=/^(\d{2}\/\d{2}\/\d{4})\s+(\S+)\s+(.+?)\s+(\d{2}-[A-Z0-9-]+)\s+(\d{2}\/\d{2}\/\d{4})\s+(\d{2})\s+([\d\s.,]+)$/.exec(line)
    if(!match) continue
    const valeur=amount(match[7]); if(!Number.isFinite(valeur)||valeur<=0) continue
    operations.push({id:opId(source,`${i}-${match[2]}-${valeur}`),source,beneficiaire:dernierBeneficiaire||'Bénéficiaire à renseigner',compte:dernierCompte,piece:match[2],libelle:match[3],datePiece:toISO(match[1]),echeance:toISO(match[5]),montant:valeur,mode:'Virement',referenceListe:ref,categorie:'AUTRE',fournisseurId:'',commandeIds:[],traitement:'a_verifier'})
  }
  return operations
}

export default function ImportSelectionCegi({fournisseurs,commandes,onClose,onSave,onArchived}:Props){
 const [files,setFiles]=useState<File[]>([])
 const [operations,setOperations]=useState<CegiOperation[]>([])
 const [idx,setIdx]=useState(0)
 const [busy,setBusy]=useState(false)
 const [error,setError]=useState('')
 const [done,setDone]=useState<string[]>([])
 const [drag,setDrag]=useState(false)
 const [checks,setChecks]=useState<string[]>([])
 const input=useRef<HTMLInputElement>(null)
 const current=operations[idx]
 const supplier = current?.fournisseurId
 const choices=commandes.filter(c=>supplier && c.artisanId===supplier)
 function update(partial:Partial<CegiOperation>){setOperations(old=>old.map((op,i)=>i===idx?{...op,...partial}:op))}
 async function importFiles(uploaded:File[]){
  const pdfs=uploaded.filter(f=>f.name.toLowerCase().endsWith('.pdf'))
  if(!pdfs.length){setError('Sélectionne un ou plusieurs PDF CEGI.');return}
  setBusy(true);setError('')
  try {
   // Installer pdfjs-dist pour lire les PDF textuels directement dans le navigateur.
   const pdfjs=await import('pdfjs-dist/legacy/build/pdf.mjs')
   pdfjs.GlobalWorkerOptions.workerSrc=pdfWorkerUrl
   const next:CegiOperation[]=[]
   const warnings:string[]=[]
   for(const file of pdfs){
    const loadingTask=pdfjs.getDocument({data:new Uint8Array(await file.arrayBuffer()),useSystemFonts:true,disableFontFace:true})
    const pdfDocument=await loadingTask.promise
    let content=''
    for(let p=1;p<=pdfDocument.numPages;p++){
     const page=await pdfDocument.getPage(p)
     const text=await page.getTextContent()
     const rows=new Map<number,{x:number;text:string}[]>()
     for(const item of text.items){if(!('str' in item))continue;const y=Math.round(item.transform[5]/3)*3;const row=rows.get(y)||[];row.push({x:item.transform[4],text:item.str});rows.set(y,row)}
     content += [...rows.entries()].sort((a,b)=>b[0]-a[0]).map(([,row])=>row.sort((a,b)=>a.x-b.x).map(x=>x.text).join(' ')).join('\n')+'\n'
    }
    const found=analyserSelectionCegi(content,file.name)
    const totalGeneral=/TOTAL\s+GENERAL\s+([\d\s]+,\d{2})/i.exec(content)?.[1]
    const totalAttendu=totalGeneral ? amount(totalGeneral) : null
    const montantLu=somme(found)
    if(totalAttendu!==null && Math.abs(totalAttendu-montantLu)>0.01) warnings.push(`${file.name} : montant de la liste ${formatMoney(totalAttendu)}, mais ${formatMoney(montantLu)} extrait sur ${found.length} opération(s). Contrôle les lignes absentes avant de valider.`)
    // Conserver le PDF source, même si aucune correspondance fournisseur n’est trouvée.
    await conserverCegi(file, found.length, montantLu)
    onArchived?.()
    next.push(...found.map(row=>{
      const f=fournisseurs.find(f=>norm(row.beneficiaire).includes(norm(f.nom))||norm(f.nom).includes(norm(row.beneficiaire)))
      return {...row,fournisseurId:f?.id||'',categorie:f?'ACHAT_BRIOCHES' as const:'AUTRE' as const}
    }))
    // La méthode destroy appartient à la tâche de chargement pdfjs-dist.
    // Selon la version, elle peut être absente sur l'objet document PDF.
    if (typeof loadingTask.destroy === 'function') await loadingTask.destroy()
   }
   if(!next.length)throw new Error('Aucune opération reconnue. Vérifie que le PDF contient du texte sélectionnable et une liste CEGI standard. Aucune donnée n’a été enregistrée.')
   const seen=new Set(operations.map(o=>o.id)); const unique=next.filter(o=>!seen.has(o.id)&&!!seen.add(o.id))
   setOperations(old=>[...old,...unique]);setFiles(old=>[...old,...pdfs]);setChecks(old=>[...old,...warnings]);setIdx(0)
  }catch(e){setError(e instanceof Error?e.message:'Lecture du PDF impossible.')}finally{setBusy(false)}
 }
 const upload=(e:ChangeEvent<HTMLInputElement>)=>{void importFiles([...e.target.files||[]]);e.target.value=''}
 const drop=(e:DragEvent)=>{e.preventDefault();setDrag(false);void importFiles([...e.dataTransfer.files])}
 const saved=done.includes(current?.id||'')
 const duplicate=operations.filter(o=>o.piece===current?.piece&&o.beneficiaire===current?.beneficiaire).length>1
 const totalSelection=current?.commandeIds.reduce((s,id)=>s+montantCommande(commandes.find(c=>c.id===id)!),0)||0
 return <div className="cegi-overlay"><section className="cegi-modal" role="dialog" aria-modal="true" aria-label="Importer une liste CEGI"><header><div><h2>Importer une sélection CEGI</h2><p>Dépose des listes de virement, puis valide chaque opération.</p></div><button onClick={onClose} aria-label="Fermer"><X size={20}/></button></header>
 <div className={`cegi-drop ${drag?'drag':''}`} onDragOver={e=>{e.preventDefault();setDrag(true)}} onDragLeave={()=>setDrag(false)} onDrop={drop} onClick={()=>input.current?.click()} role="button" tabIndex={0} onKeyDown={e=>e.key==='Enter'&&input.current?.click()}><FileUp size={25}/><b>Glisser-déposer des listes PDF CEGI</b><span>ou cliquer pour choisir un ou plusieurs fichiers</span><input ref={input} type="file" accept="application/pdf,.pdf" multiple hidden onChange={upload}/></div>
 {busy&&<p>Lecture des documents en cours…</p>}{error&&<p className="cegi-error" role="alert">{error}</p>}
 {files.length>0&&<p className="cegi-small">Documents lus : {files.map(f=>f.name).join(', ')} · {operations.length} opération(s) détectée(s) · {done.length} enregistrée(s) · Total détecté : {formatMoney(somme(operations))}</p>}
 {checks.map((message,i)=><p key={i} className="cegi-warning cegi-check"><AlertTriangle size={16}/>{message}</p>)}
 {operations.length>0&&<div className="cegi-operations"><strong>Opérations détectées — clique pour vérifier chacune</strong><div className="cegi-operations-list">{operations.map((op,i)=><button type="button" key={op.id} className={i===idx?'active':''} onClick={()=>{setIdx(i);setError('')}}><span>{done.includes(op.id)?'✓ ':''}{i+1}. {op.beneficiaire} · {op.piece}</span><b>{formatMoney(op.montant)}</b><small>{done.includes(op.id)?'Enregistrée':'À contrôler'}</small></button>)}</div></div>}
 {current&&<div className="cegi-review"><h3>Opération {idx+1} sur {operations.length} {saved&&<span className="cegi-saved"><Check size={14}/> Enregistrée</span>}</h3><div className="cegi-facts"><div><small>Bénéficiaire extrait</small><strong>{current.beneficiaire}</strong></div><div><small>Montant extrait</small><strong>{argent(current.montant)}</strong></div><div><small>Pièce / échéance</small><strong>{current.piece} · {current.echeance||'—'}</strong></div><div><small>Liste CEGI</small><strong>{current.referenceListe||current.source}</strong></div></div>{duplicate&&<p className="cegi-warning"><AlertTriangle size={15}/> Une référence semblable apparaît plusieurs fois : contrôle avant enregistrement.</p>}
 <div className="cegi-fields"><label>Bénéficiaire (corrigeable)<input value={current.beneficiaire} disabled={saved} onChange={e=>update({beneficiaire:e.target.value})}/></label><label>Fournisseur à rapprocher<select disabled={saved} value={current.fournisseurId} onChange={e=>update({fournisseurId:e.target.value,commandeIds:[]})}><option value="">Autre bénéficiaire / non trouvé</option>{fournisseurs.map(f=><option key={f.id} value={f.id}>{f.nom}</option>)}</select></label><label>Catégorie de dépense<select disabled={saved} value={current.categorie} onChange={e=>update({categorie:e.target.value as CegiOperation['categorie']})}>{Object.entries(cat).map(([v,label])=><option key={v} value={v}>{label}</option>)}</select></label><label>Montant TTC<input disabled={saved} type="number" min="0.01" step="0.01" value={current.montant} onChange={e=>update({montant:Number(e.target.value)})}/></label></div>
 <fieldset><legend>Rapprochement avec les commandes achats</legend>{!choices.length?<p className="cegi-small">Sélectionne un fournisseur pour voir ses commandes. Si aucune ne correspond, l'opération peut être enregistrée sans commande.</p>:<div className="cegi-orders">{choices.map(c=><label key={c.id}><input type="checkbox" checked={current.commandeIds.includes(c.id)} disabled={saved} onChange={e=>update({commandeIds:e.target.checked?[...current.commandeIds,c.id]:current.commandeIds.filter(x=>x!==c.id)})}/>{c.numero} — {argent(montantCommande(c))}</label>)}</div>}{current.commandeIds.length>0&&<p className="cegi-small">Commandes sélectionnées : {argent(totalSelection)} — à rapprocher avec le montant de la sélection avant validation.</p>}</fieldset>
 <p className="cegi-warning"><AlertTriangle size={15}/> Règle OB2026 : en validant cette opération, tu la déclares payée sur la base de la sélection CEGI. Le rapprochement bancaire reste une vérification distincte.</p>
 <footer><button className="cegi-secondary" disabled={idx===0} onClick={()=>setIdx(i=>i-1)}><ArrowLeft size={16}/> Précédent</button><button className="cegi-primary" disabled={saved||!current.beneficiaire.trim()||current.montant<=0} onClick={()=>{const problem=onSave(current);if(problem)setError(problem);else{setError('');setDone(old=>[...old,current.id]);if(idx<operations.length-1)setIdx(i=>i+1)}}}><Check size={16}/> {saved?'Enregistrée':'Déclarer payée et enregistrer'}</button><button className="cegi-secondary" disabled={idx===operations.length-1} onClick={()=>{setError('');setIdx(i=>i+1)}}>Suivant <ArrowRight size={16}/></button></footer>
 </div>}
 </section></div>
}

