function safeArrayFromStorage(key: string): unknown[] {
  try {
    const raw = localStorage.getItem(key)
    if (!raw) return []
    const parsed = JSON.parse(raw)
    return Array.isArray(parsed) ? parsed : []
  } catch {
    return []
  }
}

function readDonateurs(): DonateurRef[] {
  return safeArrayFromStorage('ob-donateurs')
    .map<DonateurRef | null>((value) => {
      const item = value as Record<string, unknown>
      const nom = String(item.nom ?? '').trim()
      if (!nom) return null

      return {
        id: String(item.id ?? item.code ?? nom),
        code: item.code ? String(item.code) : undefined,
        nom,
        ville: item.ville ? String(item.ville) : undefined,
        adresse: [item.numeroVoie, item.adresse]
          .filter(Boolean)
          .map(String)
          .join(' '),
        cp: item.cp ? String(item.cp) : undefined,
        email: item.email ? String(item.email) : undefined,
        telephone: item.telephone
          ? String(item.telephone)
          : undefined,
      } satisfies DonateurRef
    })
    .filter((item): item is DonateurRef => item !== null)
    .sort((a, b) => a.nom.localeCompare(b.nom, 'fr'))
}

function readCommandes(): CommandeRef[] {
  return safeArrayFromStorage('ob-commandes')
    .map<CommandeRef | null>((value) => {
      const item = value as Record<string, unknown>
      const id = item.id ?? item.numero
      if (id === undefined || id === null) return null

      return {
        id: String(id),
        numero: item.numero ? String(item.numero) : undefined,
        donateurId:
          item.donateurId !== undefined
            ? String(item.donateurId)
            : undefined,
        campagne: item.campagne
          ? String(item.campagne)
          : undefined,
        quantite:
          typeof item.quantite === 'number'
            ? item.quantite
            : Number(item.quantite ?? 0),
        prixUnitaire:
          typeof item.prixUnitaire === 'number'
            ? item.prixUnitaire
            : Number(item.prixUnitaire ?? 0),
      } satisfies CommandeRef
    })
    .filter((item): item is CommandeRef => item !== null)
}

function readCampagnes(): CampagneRef[] {
  const source = safeArrayFromStorage('ob-campagnes-v1')

  const values = source
    .map<CampagneRef | null>((value) => {
      const item = value as Record<string, unknown>
      const id = String(item.id ?? '').trim()

      if (!id) return null

      const anneeValue = item.annee
      const annee =
        typeof anneeValue === 'number' && Number.isFinite(anneeValue)
          ? anneeValue
          : Number(id.match(/\b(?:19|20)\d{2}\b/)?.[0] ?? NaN)

      return {
        id,
        annee: Number.isFinite(annee) ? annee : null,
        nom: String(item.nom ?? id),
        statut: String(item.statut ?? ''),
      } satisfies CampagneRef
    })
    .filter((item): item is CampagneRef => item !== null)
    .sort((a, b) => {
      if (a.statut === 'ACTIVE' && b.statut !== 'ACTIVE') return -1
      if (b.statut === 'ACTIVE' && a.statut !== 'ACTIVE') return 1
      return (b.annee ?? 0) - (a.annee ?? 0)
    })

  if (values.length > 0) {
    return values
  }

  return [
    {
      id: DEFAULT_CAMPAIGN,
      annee: Number(new Date().getFullYear()),
      nom: DEFAULT_CAMPAIGN,
      statut: 'ACTIVE',
    },
  ]
}

function formatMoney(value: number) {
  return new Intl.NumberFormat('fr-FR', {
    style: 'currency',
    currency: 'EUR',
  }).format(value)
}

function formatDate(value?: string) {
  if (!value) return '—'

  const date = new Date(
    value.length === 10 ? `${value}T12:00:00` : value,
  )

  if (Number.isNaN(date.getTime())) return value

  return new Intl.DateTimeFormat('fr-FR').format(date)
}

function statusLabel(status: JustificatifStatut) {
  const labels: Record<JustificatifStatut, string> = {
    BROUILLON: 'Brouillon',
    A_VERIFIER: 'À vérifier',
    EMIS: 'Émis',
    ENVOYE: 'Envoyé',
    ARCHIVE: 'Archivé',
    ERREUR: 'Erreur',
  }

  return labels[status]
}

function paymentLabel(status: PaiementStatut) {
  const labels: Record<PaiementStatut, string> = {
    EN_ATTENTE: 'En attente',
    PAYE: 'Payé',
    NON_APPLICABLE: 'Non applicable',
  }

  return labels[status]
}

function documentLabel(status: DocumentStatut) {
  const labels: Record<DocumentStatut, string> = {
    A_GENERER: 'À générer',
    GENERE: 'PDF généré',
    ENVOYE: 'Envoyé',
    ERREUR: 'Erreur',
  }

  return labels[status]
}

function downloadText(
  content: string,
  filename: string,
  type = 'text/plain;charset=utf-8',
) {
  const blob = new Blob([content], { type })
  const url = URL.createObjectURL(blob)
  const anchor = document.createElement('a')

  anchor.href = url
  anchor.download = filename
  document.body.appendChild(anchor)
  anchor.click()
  anchor.remove()
  URL.revokeObjectURL(url)
}


function JustificatifsDons() {
  const donneesOb = useObData() as ReturnType<typeof useObData> & { selectedCampagne?: {id:string}|null }
  const { commandes: commandesOb, donateurs: donateursOb, fichesCaisse } = donneesOb
  const campagneActive = donneesOb.selectedCampagne?.id ?? donneesOb.activeCampagne?.id ?? ''
  const [searchParams, setSearchParams] = useSearchParams()
  const [commandeInitiale, setCommandeInitiale] = useState<string>('')
  const [typeInitial, setTypeInitial] = useState<JustificatifType>('JDI')
  const [messageChorus, setMessageChorus] = useState('')
  const {
    justificatifs,
    createJustificatif,
    updateJustificatif,
    markDocumentGenerated,
    markSent,
    archiveJustificatif,
    convertJdiToJdp,
  } = useJustificatifs()

  const demandes = useMemo(() => calculerDemandesJustificatifs(
    commandesOb, donateursOb, fichesCaisse, justificatifs, campagneActive,
    todayInput(),
  ), [commandesOb, donateursOb, fichesCaisse, justificatifs, campagneActive])
  const demandesManquantes = demandes.filter(d => !d.existant)

  const [modalMode, setModalMode] = useState<
    'create' | 'edit' | null
  >(null)
  const [editing, setEditing] = useState<JustificatifDon | null>(
    null,
  )
  const [detail, setDetail] = useState<JustificatifDon | null>(
    null,
  )

  function preparerDepuisCommande(id: string) {
    const commande = commandesOb.find(c => String(c.id) === id)
    if (!commande) return
    const existant = justificatifs.find(j => j.type === 'JDI' &&
      (j.commandeId === id || j.commandeNumero === commande.numero) &&
      (j.campagne === commande.campagne || j.campagne.match(/(?:19|20)\d{2}/)?.[0] === commande.campagne.match(/(?:19|20)\d{2}/)?.[0]))
    if (existant) {
      setDetail(existant)
      return
    }
    setCommandeInitiale(id)
    setTypeInitial('JDI')
    setEditing(null)
    setModalMode('create')
  }

  useEffect(() => {
    const id = searchParams.get('commande')
    if (!id) return
    const commande = commandesOb.find(c => String(c.id) === id)
    if (!commande) return
    preparerDepuisCommande(id)
    setSearchParams(old => {
      const next = new URLSearchParams(old)
      next.delete('commande')
      return next
    }, { replace: true })
  // on traite une unique navigation d'entrée ; les changements des justificatifs ne rouvrent pas le formulaire
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [searchParams, commandesOb, setSearchParams])

  function demanderInfosChorus(demande: DemandeJustificatif) {
    const mail = composerDemandeChorus(demande.commande, demande.donateur)
    setMessageChorus(`Objet : ${mail.objet}\n\n${mail.corps}`)
    const params = `subject=${encodeURIComponent(mail.objet)}&body=${encodeURIComponent(mail.corps)}`
    // Ouverture du client mail : aucune transmission automatique.
    window.location.href = `mailto:${encodeURIComponent(mail.destinataire)}?${params}`
  }

  const [activeTab, setActiveTab] = useState<MainTab>('ALL')
  const [search, setSearch] = useState('')
  const [campaignFilter, setCampaignFilter] = useState('ALL')
  const [statusFilter, setStatusFilter] = useState('ALL')
  const [periodFilter, setPeriodFilter] = useState('ALL')
  const [pageSize, setPageSize] = useState<PageSize>(20)
  const [currentPage, setCurrentPage] = useState(1)

  const [moreId, setMoreId] = useState<string | null>(null)
  const [chorusIssue, setChorusIssue] = useState<{
    item: JustificatifDon
    donateur: DonateurDocumentData
