    return values
  }, [justificatifs])

  const filtered = useMemo(() => {
    const normalized = search.trim().toLowerCase()
    const now = new Date()

    return [...justificatifs]
      .filter((item) => {
        if (activeTab !== 'ALL' && item.type !== activeTab) {
          return false
        }

        if (
          campaignFilter !== 'ALL' &&
          item.campagne !== campaignFilter
        ) {
          return false
        }

        if (
          statusFilter !== 'ALL' &&
          item.statut !== statusFilter
        ) {
          return false
        }

        if (periodFilter !== 'ALL') {
          const days = Number(periodFilter)
          const itemDate = new Date(`${item.dateEmission}T12:00:00`)
          const diff =
            (now.getTime() - itemDate.getTime()) /
            (1000 * 60 * 60 * 24)

          if (diff < 0 || diff > days) {
            return false
          }
        }

        if (!normalized) {
          return true
        }

        return [
          item.numero,
          item.donateurNom,
          item.donateurCode,
          item.commandeNumero,
          item.donateurVille,
          item.type,
          item.campagne,
        ]
          .filter(Boolean)
          .join(' ')
