    ).length

    const errors = justificatifs.filter(
      (item) =>
        item.statut === 'ERREUR' ||
        item.documentStatut === 'ERREUR',
    ).length

    return {
      total: justificatifs.length,
      jdiWaiting,
      jdpPaid,
      errors,
      amount: justificatifs.reduce(
        (sum, item) => sum + item.montant,
