function createMissionId() {
  if (
    typeof crypto !== 'undefined' &&
    typeof crypto.randomUUID === 'function'
  ) {
    return crypto.randomUUID()
  }

  return `mission-${Date.now()}-${Math.random()
    .toString(36)
    .slice(2)}`
}

function normalizeText(value: unknown) {
  return String(value ?? '')
    .trim()
